window.__D("text/pelach-harimon/c006",{"p":[[4801940544,"בכתבי האריז\"ל דמחסד דעתיק<sup data-n=\"4667\">99</sup> מתחיל ההתלבשות בגולגלתא כו'] שבא בבחי' ידיעת המציאות ובחי' זאת בכלל נק' בשם שכינה לגבי כל עולם האצי' ובחי' הא\"ק שלמעלה מבחי' עתיק נק' בשם קוב\"ה [וגם ג\"ר דעתיק נכללין בו שאינם מתגלים אפי' בבחי' ידיעת<sup data-n=\"4668\">100</sup> שאעפ\"י שהם בחי' המל' שבו שהוא בחי' גילוי אור וזיו מ\"מ הוא בבחי' אור הנכלל במאור כידוע בסידור שער יוה\"כ<sup data-n=\"4669\">101</sup> בענין קדוש אתה כו' והוא בחי' כי נשגב שמו כו'] לגבי עולם האצי' כו'. ועם זה יובן<sup data-n=\"4670\">102</sup> ענין שמו בגימט' רצון כמבואר בסה\"ק הקדמונים<sup data-n=\"4671\">103</sup> ובכתבי האריז\"ל מבואר ששם הוא במל'<sup data-n=\"4672\">104</sup>, אך שניהם אמת כנ\"ל שבחי' שכינה הוא המל' שבא בבחי' מקיף ופנימי במקבל שחוץ ממנו וענין המקיף הוא הכתר שהוא הרצון להיות מתקבל במקבל ובחי' זאת מקפת את המקבל ונמשך בו בדרך השראה כנ\"ל וא\"כ מל' דא<sup data-n=\"4673\">106</sup> נק' בחי' שם באצי' להיותה גילוי אור וזיו בלבד מבחי' מהות האצי' ונעשים<sup data-n=\"4674\">107</sup> כתר לבריאה<sup data-n=\"4675\">105</sup> כו' וכן בחי' המל' דא\"ק נעשית כתר לאצי'<sup data-n=\"4676\">108</sup> כו' כנ\"ל, וא\"כ הא\"ק נק' בעהר\"צ להיותו מקור שממנו נמשך כל מיני גילויי' דרצון באצי' כו' וזהו בחי'<sup data-n=\"4677\">109</sup> רעדכ\"ר<sup data-n=\"4678\">110</sup> כו' אך גם בחי' בעהר\"צ נמשך מבחי' הקו\"ח וא\"כ בחי' הקו\"ח נק' בשם שכינה שוכן בג' עולמות בי\"ע שהוא בחי' ג' מיני אדם<sup data-n=\"4679\">111</sup> כידוע כו' ובחי' מהות ועצמו' אא\"ס שלפני הצמצום נק' בשם קוב\"ה [ובחי' מל' דא\"ס שלפני הצמצום הוא בחי' אור הנכלל במאור ונק' שמו הגדול וכנ\"ל בענין ג\"ר דעתיק כו'], וזהו אמיתית ענין יחוד קוב\"ה ושכינתי' שהוא להמשיך מבחי' מהות ועצמות אא\"ס בבחי' המל' דא\"ס עצמו ובחי' זאת נק' מקדשי שמך שע\"ז נאמר וישמחו בך<sup data-n=\"4680\">112</sup> כו'.\n<b>והנה</b> בחי' זאת תאיר ותתגלה לע\"ל, והוא ע\"ד דוגמא שמחה של מצוה שהוא מצד עצם המצוה דייקא שהם רצה\"ע הפנימי' והעצמי' שהוא ורצונו אחד<sup data-n=\"4681\">113</sup>",[["4667","99","<b>בכתבי האריז\"ל דמחסד דעתיק</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו ופ\"ז."],["4668","100","<b>ידיעת שאעפ\"י</b>: אוצ\"ל: ידיעת המציאות שאעפ\"י."],["4669","101","<b>בסידור שער יוה\"כ</b>: רנ, ג."],["4670","102","<b>ועם זה יובן</b>: ראה גם לקו\"ת פקודי ז, סע\"ג ואילך."],["4671","103","<b>שמו בגימט' רצון כמבואר בסה\"ק הקדמונים</b>: ועד\"ז בלקו\"ת פקודי ז רע\"ד־ ר\"ה נט, ד. הובא במאמרי אדה\"ז תקס\"ד ע' רלו בשם הפרדס. ראה גם פע\"ח שער הק\"ש ש\"ח, ספכ\"ח. מאמרי אדה\"א דברים ח\"ב ע' שסח. וש\"נ."],["4672","104","<b>ובכתבי האריז\"ל מבואר ששם הוא במל'</b>: ראה מאו\"א מערכת שם אות נג וביאיר נתיב שם. ש\"א לו, ב ובהערה 40. וראה גם פרדס שעה\"כ שכ\"ג, פכ\"א מערכת שם."],["4673","106","<b>דא</b>: אוצ\"ל: דאצי'."],["4674","107","<b>ונעשים</b>: אוצ\"ל: ונעשית."],["4675","105","<b>מל'. . האצי'. . כתר לבריאה</b>: ראה ע\"ח שער כסה\"כ שמ\"ו, פ\"ב. פ\"ד פ\"ו. שער העקודים ש\"ו, פ\"ב."],["4676","108","<b>המל' דא\"ק נעשית כתר לאצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"ב. לקו\"ת מסעי צה, ב. לעיל ע' פד ובהערה 24."],["4677","109","<b>א\"ק. . בחי' רעדכ\"ר</b>: ראה לקו\"ת מסעי צה, ב. לעיל ע' עז ובהערה 25."],["4678","110","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג."],["4679","111","<b>ג' מיני אדם</b>: ראה מאמרי אדה\"ז על ענינים בתחילתו ובהנסמן במ\"מ לשם. אוה\"ת על ענינים ע' עז. סה\"מ תש\"ח ע' 113 בהערה. הנסמן בסה\"מ תרל\"ב ח\"א ע' ד."],["4680","112","<b>מקדשי שמך. . וישמחו בך</b>: נוסח תפלת העמידה ליו\"ט."],["4681","113","<b>שהוא ורצונו אחד</b>: ראה תניא פל\"ח [נ, ב]. פ\"מ [נד, ב. נה, סע\"א]."]]],[4801940566,"וא\"כ השמחה הוא מצד עצם המהות ולא מצד ההמשכה שנמשך ממנו שזהו\"ע כוונת המצוה כו' ולעתיד תהי' מאיר בשלימות כנ\"ל, אך עכשיו לא תוכל להאיר בחי' זאת בשלימות רק הביטול בדרך עמל בלבד שהוא בחי' הביטול לבחי' בעהר\"צ וכמו בשעת מ\"ת שהקדימו ישראל נעשה לנשמע<sup data-n=\"4682\">114</sup> שזהו בחי' הביטול לבעהר\"צ<sup data-n=\"4683\">115</sup> כידוע אך בשבת שמאיר מעין לע\"ל<sup data-n=\"4684\">116</sup> אז מאיר בחי' עונג מביטול זה שלגבי בעהר\"צ והו\"ע נשמה יתירה<sup data-n=\"4685\">117</sup> שהוא התגלות רצה\"ע הנק' רעדכ\"ר בבחי' תענוג וכידוע בענין נשמת כל חי נשמתא דפרחא מחי העולמים [שהוא בחי' א\"ק<sup data-n=\"4686\">118</sup> כו'] אך כ\"ז הוא הארה מעין לע\"ל אבל לעתיד תאיר בחי' מל' דא\"ס שלפני הצמצום בבחי' או\"ח מעצמות המהות דא\"ס עצמו [שלא הי' בגדר אור מעולם כלל וזהו למע' מאור הגנוז<sup data-n=\"4687\">119</sup> שהי' בגדר אור רק שנגנז ואח\"כ נתגלה מגניזותו ולא נק' בשם אור חדש עדיין כו' וד\"ל] וזהו\"ע מקדשי שמך כו' שממשיכים ע\"י המצות בחי' קדושת העצם ממש לבחי' שמך העצמי' שהוא בחי' מל' דא\"ס שלפני הצמצום [והיום לעשותם<sup data-n=\"4688\">120</sup> שמכינים גילוי אור הזה ולע\"ל יתגלה ויהי' הקיבול שכר כו']. והנה בחי' זאת נק' נשמות חדשות<sup data-n=\"4689\">121</sup> שהוא בחי' גילוי אא\"ס מ\"מ<sup data-n=\"4690\">122</sup> שלפני הצמצום בבחי' התחדשות אור, אך ידוע דהנשמה אעפ\"י שהיא בחי' גילוי אא\"ס מוכרח להתלבש בתחילה בבחי' הטיפה דמ\"ן ומ\"ד שנמשך מבחי' משפיע ומקבל שעי\"ז תוכל להתגלות אח\"כ למטה בבי\"ע ובבחי' הגוף כו'. וזהו ונתנה הארץ בחי' המל'<sup data-n=\"4691\">123</sup> דאצי' יבולה שהוא בחי' העלאת מ\"ן ואח\"כ ועץ השדה הוא בחי' אדה\"ע שעל הכסא שהוא בחי' ז\"א דאצי' שנק' עץ<sup data-n=\"4692\">124</sup> השדה וכמאמר כי האדם עץ השדה<sup data-n=\"4693\">125</sup>, יתן פריו בבחי' המשכת מ\"ד ואז יתלבש בזה בחי' המשכות נשמות חדשות שיתגלו לע\"ל כו' וד\"ל.",[["4682","114","<b>שהקדימו ישראל נעשה לנשמע</b>: שבת פח, א."],["4683","115","<b>שהקדימו. . הביטול לבעהר\"צ</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רח. שה\"א כו, ב. סה\"מ תרכ\"ט ע' רנג."],["4684","116","<b>בשבת שמאיר מעין לע\"ל</b>: ראה תו\"ח שמות ח\"א לג, ג. וש\"נ."],["4685","117","<b>נשמה יתירה</b>: ביצה טז, א. ראה לעיל ע' רנ הערה 89."],["4686","118","<b>נשמת. . דפרחא. . א\"ק</b>: תפלת שויו\"ט. ראה זהר תרומה קלח, א. מאמרי אדה\"ז על ענינים ע' יב. מאמרי אדה\"א בראשית ע' תנה. דברים ח\"ב ע' תסא. תו\"ח ויקהל ח\"ב תל, ג. שעה\"י קכב, ב."],["4687","119","<b>מאור הגנוז</b>: חגיגה יב, א."],["4688","120","<b>והיום לעשותם</b>: ואתחנן ז, יא. ראה ערובין כב, א."],["4689","121","<b>נשמות חדשות</b>: ראה גם בענין נשמות חדשות לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 100. לעיל ע' כז ובהערה 101."],["4690","122","<b>מ\"מ</b>: אינו ברור בהכת\"י ואולי מיותר."],["4691","123","<b>הארץ בחי' המל'</b>: ראה זהר תוספתא בראשית לא, ב."],["4692","124","<b>ז\"א. . עץ</b>: ע\"ח שער הזווגים שט\"ו, פ\"ג. מאו\"א מערכת עץ אות יז. לעיל ע' שסו."],["4693","125","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."]]],[4801940129,"<b>בסעודה הנ\"ל [א' דשבועות תר\"י]</b>\n<b>אם</b> בחקתי<sup data-n=\"4694\">1</sup> תלכו<sup data-n=\"4695\">2</sup> ונתתי גשמיכם בעתם ונתנה הארץ יבולה ועץ השדה יתן פריו<sup data-n=\"4696\">3</sup> כו'<sup data-n=\"4697\">4</sup>, היינו בעצרת על פירות האילן<sup data-n=\"4698\">5</sup> כו', ומתחילה יש להבין ענין תלכו שהוא ענין ההילוך באהבה כמ\"ש הלוך ונסוע<sup data-n=\"4699\">6</sup> כו' וענין ההילוך דאה' יובן בהקדם ענין ואהבת שיש בו ב' פירושים הא' ל' ציווי והא'<sup data-n=\"4700\">8</sup> ל' הבטחה<sup data-n=\"4701\">7</sup>, כי הנה ידוע שיש ג' נפשות<sup data-n=\"4702\">9</sup> באדם נה\"ט הבהמי' שנק' רוח הבהמה היורדת למטה<sup data-n=\"4703\">10</sup> שהוא בחי' המדות שבאדם הטבעיים שהן יורדין למטה להתאוות תאוה לעצמו ולגרמי' וחפיצים להיות בבחי' יש. והנפש הב' היא בחי' נה\"א שהיא בחי' רוח האדם העולה למעלה<sup data-n=\"4704\">11</sup> מעלה להפשיט א\"ע מבחי' הכלי ולהיות בבחי' כלות הנפש אליו ממש כו', והנפש הג' הוא בחי' נפש השכלית<sup data-n=\"4705\">12</sup> היינו השכל אנושי שבמוח שנבדל בערך מבחי' המדות עד שלפעמים יכול גם בשכלו האנושי למשול על מדותיו, הנה בחי' זאת היא ממוצעת בין נפה\"א לנה\"ט ונק' בחי' לבוש שע\"י מתחברת נה\"א בנה\"ט הבהמי' ונק' בחי' צלם כמ\"ש אך בצלם יתהלך איש<sup data-n=\"4706\">13</sup> כו' והנה הנה\"א עצמה נק' נר הוי'<sup data-n=\"4707\">14</sup> כמו הנר שעולה בטבעו למקורו כן הנה\"א עולה למעלה בבחי' כלות הנפש לבחי' אלקות מצד שממנו לוקחה אך להיותה מוסתרת בנה\"ב [כמשי\"ת לקמן בענין רשע מכתיר את הצדיק] לזאת מוכרח להיות ההתבוננות כו', וענין ההתבוננות הוא תפיסת אור האלקי בשכל",[["4694","1","<b>אם בחקתי תלכו</b>: הנחת ר' הלל מדרוש כ\"ק אדמור הצ\"צ.\nלמאמר זה ראה אוה\"ת ויקרא כרך ב' ע' תרלד ואילך (והמשכו בכרך ד ע' א'קסז ואילך) ובהנסמן במ\"מ לשם במהדורת תשנ\"ג. (וראה גם מאמר ד\"ה אם בחוקותי תרכ\"ו סה\"מ תרכ\"ו ע' צד ואילך ובהדרושים שנסמנו בהמפתח שם ס\"ע ואילך. תר\"ל ע' קמ ואילך. ע' קמח ואילך). לפסקא ד\"ה ואח\"כ א' ונתתי — ראה אוה\"ת ויקרא כרך א ע' קצד ואילך (ס\"ד).\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["4695","2","<b>אם בחקתי תלכו </b>[א ניתוסף: כו']: בחוקותי כו, ג."],["4696","3","<b>ונתתי גשמיכם בעתם </b>[א: כ\"ז ליתא]<b> ונתנה. . פריו </b>[א: ונתנה כו' ועץ כו' יתן פריו]: בחוקותי שם, ג."],["4697","4","<b>כו'</b>: א: ליתא. בג: כבפנים."],["4698","5","<b>בעצרת על פירות האילן</b>: ר\"ה טז, א (במשנה)."],["4699","6","<b>הלוך ונסוע</b>: לך יב, ט. ראה לקמן ביאור למאמר ד\"ה והתהלכתי בתוככם תר\"ב ובהערה 26."],["4700","8","<b>והא'</b>: ג: והב'. אב: כבפנים."],["4701","7","<b>ואהבת. . ל' ציווי. . הבטחה</b>: ראה גם (בנוסף להערה 1) תו\"א תשא פו, ג. לקו\"ת ואתחנן יא, ב. סוכות פ, ד. מאמרי אדה\"ז תקס\"ו כאן ע' קסג. מאמרי אדה\"א ויקרא ח\"ב ע' תשלח. תו\"ח וארא ח\"א נב, ג. ויקהל ח\"ב תלו, ג. אוה\"ת ואתחנן ע' שצג. שופטים ע' תתכז. סה\"מ תרל\"ב ח\"א ע' צה וע' קלט. תער\"ב ח\"א ר\"ע תקיג."],["4702","9","<b>ג' נפשות</b>: ראה גם בהערה 1 ובמקומות שנסמנו במ\"מ לשם."],["4703","10","<b>רוח הבהמה היורדת למטה</b>: ע\"פ קהלת ג, כא. ראה בהערה הבאה."],["4704","11","<b>רוח האדם העולה למעלה</b>: ע\"פ קהלת שם. ראה גם שע\"ת סא, א ואילך."],["4705","12","<b>נפש השכלית</b>: ראה גם בענין נפש השכלית (בנוסף להערה 9) אגה\"ק סט\"ו קכג, סע\"א. לקו\"ת בחוקותי מז, ג. מאמרי אדה\"ז תקס\"ו ע' קסג. ע' קעט. תו\"ח בא ח\"א קלב, ג. וש\"נ. קא, ג. וש\"נ. שמות מז, ב. וש\"נ. ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"י. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קמא. מאמרי אדה\"א שמות ח\"ב ס\"ע שצו. דברים ח\"ד ע' א'רז. תו\"ח ח\"ש קל, ב. ש\"א יא, א. סה\"מ עטר\"ת ע' תכא ואילך. תש\"ב ע' 105 ואילך. לקמן מאמר ד\"ה אם בחוקותי הג' ובהערה 32."],["4706","13","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז."],["4707","14","<b>נר הוי'</b>: משלי כ, כז. ראה תניא פי\"ט."]]],[4801940193,"אנושי שבנפשו השכלית כנ\"ל ולהיותה ממוצעת לזאת עי\"ז תוכל גם הנה\"ב ג\"כ להתהפך מחושך לאור והיינו שהמדות ותאוות שהי' לו בעניני עוה\"ז המה בעצמם יתהפכו לאה' את הוי', וענין ההתבוננות הוא בתיבת שמע שם ע' רבתי<sup data-n=\"4708\">15</sup> והיינו איך שכל העולמות הם שם והארה בעלמא מעצמות מדותיו הנק' ע' רבתי להיותם בבחי' א\"ס וא\"כ הם בטלים למקורם ואינם תופסים מקום כלל, וכאשר מרגיש איכות ביטול העולמות למקורם ושרשם ממילא מתעלית גם הנה\"ט לשרשה ליכלל באלקים חיים [והיינו להיות שרש נה\"ט נמשך מע' רבתי שהם רפ\"ח ניצוצין<sup data-n=\"4709\">16</sup> שנפלו מבחי' הז' מדות עליונים בבחי' שם ב\"ן וב\"ן ורפ\"ח גימ' ש\"ם<sup data-n=\"4710\">17</sup> וזהו שם ע' כו'] והנה אהבה זאת שהוא בחי' התפעלות הנה\"ט היא אה' דבכל לבבך בשני יצריך<sup data-n=\"4711\">18</sup> אך אח\"כ מאיר התפעלות אה' מצד הנה\"א שמאירה ונמשכה בבחי' כלות הנפש למקורה שהיא בחי' חלק אלוה ממעל<sup data-n=\"4712\">19</sup>, וממעל היינו מלמעלה ממקור ההשתלשלות [... כי מקור ההשתלשלות הוא בבחי' ע' רבתי הנ\"ל שהם מדות דבינה אבל שרש הנשמה הוא בחכ' עילאה שלמעלה מבחי' השבירה כו'. ..] כי ישראל עלו במח'<sup data-n=\"4713\">20</sup> כו' והנה אה' זאת נק' אה' דבכל נפשך<sup data-n=\"4714\">21</sup> ועל אהבות אלו נאמר ואהבת ל' ציווי כו'<sup data-n=\"4715\">22</sup>, והנה לכאורה למה ירדה הנשמה בגוף בבחי' הסתר והעלם בכדי לבררו ולהפכו כיון שגם אח\"כ לא תגיע רק לשרשה הקדום כמו שעלתה במח' א\"כ למה תצטרך לירידה זאת. וע\"כ צ\"ל שירידה לצורך עלי'<sup data-n=\"4716\">23</sup> היא וענין העלי' הוא בחי' האה' דבכל מאדך<sup data-n=\"4717\">24</sup> שגם אה' זאת היא ג\"כ בנה\"א אך לא תגיע אלי' רק מצד בירור והתהפכות נה\"ב דייקא כו'.\n<b>והטעם</b> לזה ידוע בענין ואלה המלכים<sup data-n=\"4718\">25</sup> אשר מלכו בארץ אדום לפני מלוך מלך לבנ\"י שזהו ענין התוהו שקדם לתיקון<sup data-n=\"4719\">26</sup> וענין התוהו הם אורות בלתי מוגבלים בכלים [מחמת ששם הוא בחי' ריבוי האור ומיעוט הכלים<sup data-n=\"4720\">27</sup> לזאת לא יוכלו הכלים לסבול את האור] רק שנתהווה מהם שפע בדרך נפילה והוא התהוות היש ופירוד שלמטה שזהו שרש ומקור נה\"ט, לזאת כאשר תתהפך הנה\"ט לאה' את ה' אזי",[["4708","15","<b>שמע שם ע' רבתי</b>: זהר פינחס רלו, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשמא ואילך. וש\"נ. סה\"מ תרל\"ג ח\"א ע' רב. וש\"נ."],["4709","16","<b>רפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. לקו\"ש וישב כרך טו ע' 4־ 52 (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["4710","17","<b>וב\"ן ורפ\"ח גי' ש\"ם</b>: פע\"ח שער הק\"ש ש\"ח, פ\"ט."],["4711","18","<b>דבכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9."],["4712","19","<b>הנה\"א. . חלק אלוה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. תו\"ח וארא ח\"א נא, ד. וש\"נ."],["4713","20","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 52."],["4714","21","<b>דבכל נפשך</b>: ואתחנן ו, ה."],["4715","22","<b>ועל אהבות. . כו'</b>: אבג: ליתא."],["4716","23","<b>שירידה לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["4717","24","<b>דבכל מאדך</b>: ואתחנן ו, ה."],["4718","25","<b>ואלה המלכים</b>: וישלח לו, לא. ראה זהר אד\"ר נשא קכח, א. ע\"ח שער הכללים פ\"א. שער דרושי הנקודות ש\"ח, פ\"ד."],["4719","26","<b>התוהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["4720","27","<b>התוהו. . ריבוי האור ומיעוט הכלים</b>: ראה ע\"ח שער הכללים שם. שער שבה\"כ ש\"ט, פ\"ו. מאמרי אדה\"א דברים ח\"ד ע' א'תעו. וש\"נ."]]],[4801940250,"כאשר מתעלה האור והחיות שבה לשרשה שהוא בחי' ע' רבתי מתעלי' אח\"כ בעלי' אחר עלי' לעורר שרשם הקדום באורות דתוהו שהם למעלה משרש הנשמה שעלתה במח' כמ\"ש לפני מלוך מלך לבנ\"י ובחי' זאת נק' בחי' חשך סתרו<sup data-n=\"4721\">28</sup> ועי\"ז מגלה עמוקות מני חשך<sup data-n=\"4722\">29</sup> והוא בחי' יתרון אור כו' ולכן יאיר אור האה' דבכל מאדך בנשמה האלקית כי ענין מאד הוא אור שלמעלה מבחי' הגבלת הכלים כו'. והנה אחר התעוררות אורות דתהו להתגלות צריך לעשות כלים לרבוי האורות בכדי שלא יהי' נפילה עוד והיינו ע\"י המצות דרמ\"ח פקודין<sup data-n=\"4723\">30</sup> כו' ונמצא שאע\"פ שכלים דהשתלשלות לא יכילו האור מ\"מ ע\"י הכלים דמצות יכילו אורות דתוהו כו' וזהו שאחרי האה' דבכל מאדך נא' והיו הדברים<sup data-n=\"4724\">32</sup> כו' ושננתם<sup data-n=\"4725\">33</sup> וקשרתם כו'<sup data-n=\"4726\">34</sup>, וזהו ענין מה שהמקיים את המצות נק' צדיק<sup data-n=\"4727\">35</sup> וצדיק נק' זכאי בלשון תרגום כדמתרגמינן על חמשים צדיקים<sup data-n=\"4728\">36</sup> חמשין זכאין והיינו משום דע\"י המצות נגלי' אורות דתוהו בלי הסתר כלל, כי המצות הם כלים זכים לגלות האור כמש\"נ<sup data-n=\"4729\">31</sup><sup data-n=\"4730\">37</sup>. וזהו ענין העלי' שבנשמה מצד ירידתה בגוף כו' וד\"ל. ועל אהבה זאת נאמר ואהבת לשון הבטחה כו'<sup data-n=\"4731\">38</sup>. וזהו משארז\"ל ע\"פ כי לא יראני האדם וחי<sup data-n=\"4732\">39</sup> ואמרו בחייהם אינם רואין<sup data-n=\"4733\">40</sup> אבל במיתתן הם רואים, ולכאורה היינו מחמת שאז נפשטי' מחומר הגוף וא\"כ יקשה שהלא אמרו אפי' חיות הקודש אינם רואים את הכבוד ואפי' מה\"ש אינם רואים את הכבוד כו' והלא גם הם מופשטים מחומר גופני, אלא ע\"כ לומר שאפי' מלאכים הרוחנים לא יוכלו לראות רק בחי' אורות המלובש בכלים וכן הנשמה קודם בואה לגוף לא תוכל לראות רק בבחי' אור המלובש בכלי [רק שראייתה בפנימי' יותר מן המלאכים מצד שעלתה במח' כו'] רק במיתתה שהייתה בחומר הגוף וביררה את כל הניצוצין שצריכה לברר ולכן נתעוררו אורות דתוהו להתגלות ונתלבשו בכלים ע\"י המצות שעשתה מאז כו'<sup data-n=\"4734\">42</sup> ואז היא רואה את הכבוד היינו האור שלמעלה מהגבלת הכלי כו' וד\"ל<sup data-n=\"4735\">41</sup>.",[["4721","28","<b>דתוהו. . חשך סתרו</b>: תהלים יח, יב. ראה גם (בנוסף לאוה\"ת כאן ע' תרלו) מאמרי אדה\"א דברים ח\"א ע' ו־ ח\"ב ע' תקסח־ ח\"ד ע' א'רמז־ תו\"ח בשלח ח\"א קנח, ב ובהנסמן בהנ\"ל."],["4722","29","<b>מגלה עמוקות מני חשך</b>: איוב יב, כב. ראה אוה\"ת כאן."],["4723","30","<b>דרמ\"ח פקודין</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["4724","32","<b>והיו הדברים</b>: ואתחנן ו, ו. ראה גם לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 157. ד\"ה והתהלכתי תר\"ב על יד הערה 79. ד\"ה והתהלכתי תרכ\"ב על יד הערה 83."],["4725","33","<b>ושננתם</b>: שם ו, ז. אב: ליתא. ג: ניתוסף כו'."],["4726","34","<b>וקשרתם כו'</b>: שם שם, ח. אב: ליתא."],["4727","35","<b>שהמקיים את המצות נק' צדיק</b>: ראה לקו\"ת שה\"ש טז, ג. סה\"מ תרל\"ח ע' תז. וש\"נ."],["4728","36","<b>כדמתרגמינן על חמשים צדיקים</b>: אונקלוס ויוב\"ע וירא יח, כד."],["4729","31","<b>נא'. . האור כמש\"נ</b>: א: ליתא."],["4730","37","<b>כמש\"נ</b>: א: ליתא כנ\"ל הערה 31. בג: כמ\"ש כמו שהוא."],["4731","38","<b>ועל אהבה. . כו'</b>: אב: ליתא."],["4732","39","<b>כי לא יראני האדם וחי</b>: תשא לג, כ."],["4733","40","<b>בחייהם אינם רואין</b>: ראה במד\"ר ספי\"ד (באוה\"ת כאן ע' תרלז מציין גם לס\"פ במדבר). מאמרי אדה\"א דברים ח\"א ע' שכד. וש\"נ. ראה גם תו\"ח בא ח\"א קב, ד ואילך. מאמרי אדה\"א ויקרא ח\"ב כאן ע' תשמט ואילך. אוה\"ת כאן ע' תרלז ואילך. סה\"מ עטר\"ת ע' תכו."],["4734","42","<b>מאז כו'</b>: אבג: ליתא."],["4735","41","<b>בפנימי'. . וד\"ל</b>: א: ליתא."]]],[4801940303,"<b>וזהו</b> אם בחקתי תלכו ענין ההילוך היא האה' דבכל מאדך דייקא שהוא בחי' הרגשת האור שלמעלה מהגבלת כלי [משא\"כ האה' דבכל נפשך שמצד עצם הנשמה האלקי' נק' עמידה וכמ\"ש ע\"פ ונתתי לך מהלכים<sup data-n=\"4736\">43</sup> בין העומדים כו' שהמלאכים וכן הנשמות קודם בואם לגוף נק' עומדים משא\"כ אחרי התלבשותן בגוף נק' מהלכים כו'], ולזה אמר שההילוך הזה יהי' על ידי חוקותי דייקא שהיא<sup data-n=\"4737\">45</sup> שני חקיקות<sup data-n=\"4738\">44</sup> חקיקה מבחוץ וחקיקה מבפנים<sup data-n=\"4739\">46</sup>. וענין החקיקה מבחוץ הוא ע\"י התבוננות דפסוד\"ז שהוא ענין רוממות אל בגרונם<sup data-n=\"4740\">47</sup> וענין רוממות אל היינו כאשר ההתבוננות הוא מבחי' האור מקור ההשתלשלות כמ\"ש כלול בעצמות המאור [... שהוא ענין הי' הוא ושמו בלבד<sup data-n=\"4741\">48</sup> כו'. ..] ועי\"ז נעשה כריתת יניקת החיצוני' וזהו וחרב פיפיות בידם<sup data-n=\"4742\">49</sup> להכרית יניקת החיצוני', כי הנה רשע מכתיר את הצדיק<sup data-n=\"4743\">50</sup> שהרע מסבב לקדושה וכמו בנבואת יחזקאל שראה מתחלה רוח סערה וענן גדול<sup data-n=\"4744\">51</sup> ואש מתלקחת שהוא בחי' שלש קה\"ט<sup data-n=\"4745\">52</sup> ואח\"כ ונוגה לו סביב ואח\"כ סיפר איכות המרכבה דקדושה כו' ולכן צריך להפריד הרע אשר סביב לקדושה והוא ענין הנסירה<sup data-n=\"4746\">53</sup> ע\"ד הקבלה להפריד הרע הנאחז בקדושה, והפרדת הרע הוא ע\"י ההתבוננות ברוממות אלקות דייקא כו', וזהו ענין פסוד\"ז כי זמרה יש בו ב' פירושי' מלשון זמר ושבח [שזהו פועל רוממות האור להתכלל במאור כמו כאשר משבחי' לאדם במדותיו מרוממי' אותו לעצמי' נפשו כו'] ומלשון זמיר עריצים<sup data-n=\"4747\">54</sup> שהוא ענין כריתת יניקת החיצונים, ושני הפי' אמת והא בהא תלי' כנ\"ל.\n<b>וזהו</b> ענין החקיקה מבחוץ כמו בגשמי' כאשר רוצים לעשות כלי מחליקין הגולמי תחלה שתהא ראוי' להיות כלי ואח\"כ עושין בה החלל כו' כן למעלה ענין החקיקה מבחוץ<sup data-n=\"4748\">55</sup> הוא הפרדת הרע בכדי שתוכל לקלוט הנשמה האור אלקי בתוך",[["4736","43","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 155. ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 10 ואילך. תרכ\"ב על יד הערה 18. תו\"א וישב ל, ג. תו\"ח בשלח ח\"א קסד, ב ואילך. וש\"נ. מאמר ד\"ה צאינה וראינה־ ד\"ה וידבר אלקים. . אנכי שבועות תשכ\"ב."],["4737","45","<b>שהיא</b>: ג: שהו\"ע. אב: שהוא ענין."],["4738","44","<b>חוקותי. . שני חקיקות</b>: ראה גם בענין ב' חקיקות אוה\"ת בחוקותי כאן ע' תרלט. לעיל מאמר ד\"ה אם בחוקותי הא' ובהערה 54."],["4739","46","<b>חקיקה מבחוץ וחקיקה מבפנים</b>: ראה גם אוה\"ת כאן. לעיל מאמר ד\"ה אם בחוקותי הא' ובהערה 55."],["4740","47","<b>רוממות אל בגרונם</b>: תהלים קמט, ו. ראה גם לעיל מאמר ד\"ה כי תבואו גו' ושבתה תר\"ט על יד הערה 123."],["4741","48","<b>הי' הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["4742","49","<b>וחרב פיפיות בידם</b>: המשך הכתוב רוממות אל."],["4743","50","<b>רשע מכתיר את הצדיק</b>: חבקוק א, ד. ראה גם לעיל מאמר ד\"ה אם בחוקותי הא' על יד הערה 20."],["4744","51","<b>רוח סערה וענן גדול</b>: יחזקאל א, ד [ושם: סערה. . ענן — ראה תניא ספ\"ו. מכתב ימי חנוכה תש\"ג נדפס באג\"ק ח\"א ע' עא. וראה גם או\"ת בהעלותך מה, ד [נעתק באוה\"ת (יהל אור) תהלים ע' שנט]. אבל ראה שם עקב נב, א]."],["4745","52","<b>קה\"ט</b>: אג ניתוסף: לגמרי."],["4746","53","<b>ענין הנסירה</b>: ראה גם סה\"מ תרכ\"ו כאן ע' צט. תר\"ל כאן ע' קנא."],["4747","54","<b>פסוד\"ז. . זמיר עריצים</b>: ישעי' כה, ה. ראה גם לעיל מאמר ד\"ה כי תבואו גו' ושבתה תר\"ט ובהערה 122."],["4748","55","<b>כמו </b>[אג: וכמו]<b> בגשמי'. . מבחוץ</b>: ב: ליתא. וכנראה נשמט מפני תיבות הדומות: מבחוץ. . מבחוץ."]]],[4801940353,"תוכה משא\"כ כשלא נפרד הרע לא תוכל להיות כלי לקלוט אור האלקי בקרבה כו'. וענין החקיקה מבפנים הוא ע\"י המצות הנק' חוקים שהם המצות שבלא טעם כלל ושרש מצות אלו הוא בבחי' עצם הרצון הנק' רעדכ\"ר<sup data-n=\"4749\">56</sup> שמצות אלו עושין חקיקה בנפש שתוכל לקלוט אור האלקי דאה' דבכל מאדך בתוכיות הלב כו' וד\"ל [ואח\"כ אמר ואת מצותי תשמורו ועשיתם אותם, מצוותי נק' עשיית המצות בפועל עי\"ז יהי' שמירת האור העליון שלא יהי' ממנו יניקה לחיצונים, ועשיתם עשי' היא מלשון הכרח<sup data-n=\"4750\">57</sup> כמו גט המעושה<sup data-n=\"4751\">58</sup> כו' והמשכות האור ע\"י המצות בבי\"ע מוכרח להיות בדילוג גדול וכן ראשית גילוי האור מן העצמו' בנאצלים מוכרח ג\"כ להיות ע\"י דילוג גדול לזה א' שתכריחו האור לבא בבחי' גילוי למטה וכ\"ז הוא ע\"י קבלת עומ\"ש שבמצות שעושה אותם ע\"י הנחת עצמותו כו' וד\"ל].\n<b>ואח\"כ</b> א'<sup data-n=\"4752\">59</sup> ונתתי גשמיכם בעתם, הנה פי' ונתתי בעצמי שלא ע\"י שליח כי הנה בגמ' פי'<sup data-n=\"4753\">60</sup> מה שנא' הנותן מטר ע\"פ ארץ<sup data-n=\"4754\">61</sup> ושולח מים ע\"פ חוצות דארץ הוא א\"י ושם א' הנותן בעצמו שלא ע\"י שליח ובחו\"ל נותן ע\"י שליח ולזה א' השולח מים ע\"פ חוצות שהוא ח\"ל כו', ולכאורה קשה<sup data-n=\"4755\">62</sup> דבגמ' חשיב ג' דברים שלא נמסרו לשליח<sup data-n=\"4756\">63</sup> וא' מהם מפתח של גשמים דמשמע שהגשמים לא נמסרו כלל לשליח. אך הענין יובן ע\"פ המבואר בפרקי דר\"א דבזמן שישראל ערש\"מ הארץ שותה מטר מן השמים<sup data-n=\"4757\">64</sup> שנא' למטר השמים תשתה מים<sup data-n=\"4758\">65</sup> כו' ובזמן שאין עושין רש\"מ היא שותה מי אוקיינוס ואז היא כאלמנה המזנה כו' וביאור ענין המשל הנ\"ל הנה באיש ואשה הגשמי' שכינה שרוי' ביניהם<sup data-n=\"4759\">66</sup> והנה עיקר כח ההולדה הוא מן האשה כמ\"ש אשה כי תזריע וילדה<sup data-n=\"4760\">67</sup> אך טיפת הדכר הוא פועל באשה כח ההולדה שתלד מפנימית עצמותה וכ\"ז הוא מצד כח הא\"ס הנותן בזכר כח שיפעול ההולדה באשה והיינו שתלד מפנימיות עצמותה, אך כ\"ז הוא היחוד באיש ואשה המיוחדים זה לזה אך",[["4749","56","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג. לקמן ביאור למאמר ד\"ה והתהלכתי תר\"ב על יד הערה 87. ד\"ה והתהלכתי תרכ\"ב על יד הערה 53."],["4750","57","<b>עשי' היא מלשון הכרח</b>: ראה גם אוה\"ת כאן כרך ד' ע' א'קסט. מאמרי אדה\"א קונטרסים ע' ח. וש\"נ. סה\"מ תרל\"ו ח\"ב ע' רפט. תרע\"ח ע' קכא. ע' קצב. תרצ\"ט ע' 191. לקו\"ש שופטים כרך כט ע' 100 הערה 42."],["4751","58","<b>גט המעושה</b>: גיטין פח, ב (במשנה)."],["4752","59","<b>ואח\"כ א'</b>: להבא להלן ראה אוה\"ת ויקרא כרך א ע' קצד ואילך (ס\"ד)."],["4753","60","<b>בגמ' פי'</b>: תענית י, א."],["4754","61","<b>הנותן מטר ע\"פ ארץ</b>: איוב ה, י."],["4755","62","<b>ולכאורה קשה</b>: ראה גם אוה\"ת עקב ע' תרטו. סה\"מ עטר\"ת ס\"ע תכח ואילך. בסה\"מ תרכ\"ו (ועוד — ראה הערה 1) כאן ע' ק: והקשו."],["4756","63","<b>ג' דברים. . לשליח</b>: תענית ב, א."],["4757","64","<b>בפרקי דר\"א דבזמן. . מן השמים</b>: ראה גם המשך מים רבים ע' קלו וע' קלז בשם הפדר\"א ובהערה לשם: ”לע\"ע לא מצאתיו. וראה פדר\"א ספ\"ה. ב\"ב כ\"ה, ב\". לקמן ביאור למאמר ד\"ה והתהלכתי תר\"ב על יד הערה 108. ד\"ה והתהלכתי תרכ\"ב על יד הערה 89. סה\"מ תרל\"ח ע' קס הערה 1060."],["4758","65","<b>למטר השמים תשתה מים</b>: עקב יא, יא."],["4759","66","<b>שכינה שרוי' ביניהם</b>: סוטה יז, א."],["4760","67","<b>אשה כי תזריע וילדה</b>: תזריע יב, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תר. וש\"נ. תו\"ח נח עב, א ובהערה 2. שמות ח\"א ט, ג. וש\"נ."]]],[4801940399,"אלמנה המזנה להיותה מתייחדת במשפיע שאינו מיוחד אלי' אין השכינה שרוי' ביחודם ולזאת אין כח במשפיע לעשות בה כח הולדה מפנימי' עצמותה רק מחיצוני' כו', כן הוא בארץ ושמים, הנה בארץ מלובש כח הא\"ס להצמיח עד אין שיעור במאמר תדשא הארץ<sup data-n=\"4761\">68</sup> כו' ועיקר כח הצמיחה הוא מצד הארץ<sup data-n=\"4762\">69</sup> רק המטר היורד מן השמים הוא רובע את הארץ ומולידה היינו שפועל שיתגלה בה כח הא\"ס להצמיח עד אין שיעור וזהו כאשר ירד הגשם<sup data-n=\"4763\">70</sup> מן השמים אז והרווה את הארץ והולידה והצמיחה כו'. משא\"כ כשהארץ שותה ממי אוקיינוס אז אין המים פועלים בה לגלות פנימי' כחה להצמיח עד אין שיעור רק נגלה חיצונית הכח שבה בלבד כו' ולכן נק' אז כאלמנה המזנה כו', וזהו הנותן מטר ע\"פ ארץ מטר הוא מלשון מטרוניתא<sup data-n=\"4764\">71</sup> והיינו כאשר השפע הולך מן המשפיע למקבל המיוחד אלי'<sup data-n=\"4765\">72</sup> שנק' בשם מטרוניתא אז הנתינה היא מעצמי' כח הא\"ס וזה נק' בשם מטר [וזהו מטרא בעלה דארעא<sup data-n=\"4766\">73</sup> כי הוא דייקא המוציא פנימי' כחה לבא לידי גילוי], משא\"כ כשההמשכה היא ממימי אוקיינוס אז הגם שנעשה צמיחה אבל לא מפנימית כח הארץ ואז לא נק' בשם מטר רק בשם מים וגם נמשך ע\"י שליח ולזה א' השולח כו'. ובזה יובן ענין הנ\"ל שבארץ שהיא<sup data-n=\"4767\">74</sup> בחי' מקבל המיוחד לעצמות הא\"ס [... כמ\"ש ארץ אשר ה' אלקיך<sup data-n=\"4768\">75</sup> דורש אותה עיני ה' אלקיך בה<sup data-n=\"4769\">76</sup> כו'. ..] לכן נותן ומשפיע שלא ע\"י שליח ואז נק' מטר כנ\"ל מלשון מטרוניתא ואז מוציאה הארץ מפנימי' כחה משא\"כ כל הארצות אינם בבחי' מקבל המיוחד אליו ולכן השפע נמשך בהם ע\"י שליח ואז לא נק' מטר רק בשם מים, וכן עד\"ז בארץ גופא כאשר אין ישראל עושין רש\"מ כו' ח\"ו [... כי עושין רצונו היינו שממשיכים בחי' רצון מעצמות כח הא\"ס שהוא למעלה מגדר רצון ובעה\"ר זה נק' נתינה שלא ע\"י שליח, משא\"כ כשאין ערש\"מ שאז אין מעוררים את העצמי' ממש כו' אז הנתינה ע\"י שליח כו' כמבואר במ\"א. ..]. ועם זה יובן מה שא' בגמ' דמפתח של גשמים לא נמסר לשליח בסתם היינו כי לא נק' גשם רק כשנמשך מעצמי' פנימי' הא\"ס משא\"כ כשלא נמשך מעצמי' ופנימי' אז נק' בשם מים ולא בשם גשמים כו'. והענין דכתי' יהי רקיע בתוך המים<sup data-n=\"4770\">77</sup> ויהי מבדיל בין מים למים ולכן כאשר נמשך ממים עליונים שמעל לרקיע אז נק' בשם גשמים וזה נק' מיין דוכרין משא\"כ כאשר נמשך מן המים אשר מתחת לרקיע אז לא נק' רק בשם מים והוא ענין מיין<sup data-n=\"4771\">78</sup> נוקבין<sup data-n=\"4772\">79</sup>",[["4761","68","<b>במאמר </b>[אבג: כמאמר]<b> תדשא הארץ</b>: בראשית א, יא."],["4762","69","<b>ועיקר כח הצמיחה הוא מצד הארץ</b>: ראה מאמרי אדה\"ז תקס\"ז ע' רפד. אוה\"ת בשלח ע' תקנה ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תקצד ואילך."],["4763","70","<b>כאשר ירד הגשם</b>: ישעי' נה, י."],["4764","71","<b>מטר הוא מלשון מטרוניתא</b>: ראה גם לקו\"ת בהעלותך לו, ד."],["4765","72","<b>אלי'</b>: בג: אליו."],["4766","73","<b>מטרא בעלה דארעא</b>: תענית ו, ב. ראה גם אוה\"ת בחוקותי כאן ע' א'קעא."],["4767","74","<b>שהיא</b>: אבג: שהוא."],["4768","75","<b>ארץ אשר ה' אלקיך</b>: עקב יא, יב [בדילוג]."],["4769","76","<b>עיני ה' אלקיך בה</b>: א: ליתא."],["4770","77","<b>יהי רקיע בתוך המים</b>: בראשית א, ו."],["4771","78","<b>מיין דוכרין. . מיין נוקבין</b>: זהר בראשית יז, סע\"ב. יח, רע\"א. ראה גם בענין מ\"ד ומ\"נ מאמרי אדה\"ז תקס\"ג ח\"א ע' קפג ואילך."],["4772","79","<b>והוא ענין מיין נוקבין</b>: אב: ליתא. ג: מים נוקבין."]]],[4801940442,"כו' וד\"ל.\n<b>והנה</b> כן הוא בענין התו' שנק' בשם גשם<sup data-n=\"4773\">80</sup> ומים<sup data-n=\"4774\">81</sup> וכמ\"ש בפ' כאשר ירד הגשם כו' כן יהי' דברי אשר יצא מפי כו', שיש בזה ב' בחי' כי הנה ידוע שמתחילה שמעו עשה\"ד מפי הקב\"ה<sup data-n=\"4775\">82</sup> בעצמו ואח\"כ אמרו למשה דבר אתה עמנו<sup data-n=\"4776\">83</sup> כו' ואח\"כ כשהרגישו שמצד זה נמשך אליהם השכחה בקשו שידבר עמהם הקב\"ה בעצמו וזהו ישקני מנשיקות פיהו<sup data-n=\"4777\">84</sup> והשיב להם אין זה עתה כ\"א לע\"ל כו'. והענין כי מתחילה קבלו פנימי' התו' מפי הקב\"ה בעצמו ובפנימי' אין שכחה כו' אך אח\"כ ירדו ממדריגתם ולא נמשך להם רק חיצוני' התו' ע\"י ממוצע בחי' משה<sup data-n=\"4778\">85</sup>, וכן עכשיו נמשכה קבלת דור אחר דור ממשה ליהושע<sup data-n=\"4779\">86</sup> כו' הכל ע\"י ממוצעים ובחיצוניות שולט השכחה, ועיקר הענין כי פנימי' התו' הוא השפע מא\"ס שלא ע\"י התלבשות בכלים ולבושים משא\"כ בחי' חיצוני' התו' הוא השפע מא\"ס המתלבשת בכלים דאצי' כו'. והנה פנימיות התו' נק' גשם וזהו הגילוי דלע\"ל וחיצוני' התו' נק' מים שהוא התו' דעכשיו כו', וזהו ההבטחה דכאשר בחקתי תלכו ונתתי גשמיכם בעצמי שלא ע\"י שליח הן בשפע דהשתלשלו' הן בשפע התו', ושפע זאת נק' גשם ולא מים כנ\"ל וד\"ל.\n<b>ונתנה</b> הארץ יבולה, הנה יבולה הוא פנימי' שבה להצמיח צמיחה פנימי' כי הנה יש צמיחה חיצוני' כמו תדשא הארץ דשא עשב, ולמעלה בארץ העליונה שהיא בחי' המל'<sup data-n=\"4780\">87</sup> דאצי' יש ב' בחי' מלאכים המתהווים מאין ליש הא' אותן המלאכים שהם בבחי' קטנות המוחין שבטלי' ונכללי' בכ\"י בפי בהמה רבה<sup data-n=\"4781\">88</sup> שהוא בחי' המל' כו' ועליהם נאמר יוצר משרתים כו', ויש מלאכים שנתהוו בבחי' גדלות המוחין והם חיים וקיימים משי\"ב ועליהם נא' ואשר משרתיו<sup data-n=\"4782\">89</sup> כו', וב' בחי' אלו נק' דשא עשב<sup data-n=\"4783\">90</sup> כי דשא הוא צמיחה קטנה והן המלאכי' שהם בבחי' קטנות המוחין כנ\"ל ועשב הוא צמיחה גדולה שהם המלאכים שהם בבחי' גדלות המוחין כנ\"ל וכ\"ז הוא צמיחה חיצוני' כו' אבל פנימי' הצמיחה הוא מ\"ש כי תהיו אתם לי ארץ חפץ<sup data-n=\"4784\">91</sup> כו' [... והוא גילוי פנימי' רצון ועונג הנעלם שבעצמו' שהי' לנשמות",[["4773","80","<b>התו' שנק' בשם גשם</b>: ראה ערכי הכינויים לבעל סדה\"ד מערכת גשם. מאמרי אדה\"א דברים ח\"ד ע' א'תמה."],["4774","81","<b>התו' שנק'. . ומים</b>: ראה ערכי הכינויים לבעל סדה\"ד מערכת מים. תניא פ\"ד. מאמרי אדה\"א שמות ח\"א ע' קפג. וש\"נ."],["4775","82","<b>שמעו עשה\"ד מפי הקב\"ה</b>: ראה שהש\"ר פ\"א, ב ד."],["4776","83","<b>דבר אתה עמנו</b>: יתרו כ, טז. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' רסט ואילך (נו\"א). מאמרי אדה\"א במדבר ח\"ב ע' תרכח ואילך."],["4777","84","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["4778","85","<b>ממוצע בחי' משה</b>: ראה גם תו\"ח תצוה ח\"ב שכג, ג. וש\"נ."],["4779","86","<b>ממשה ליהושע</b>: אבות רפ\"א."],["4780","87","<b>בארץ. . המל'</b>: ראה זהר תוספתא בראשית לא, ב."],["4781","88","<b>ונכללי' בכ\"י בפי בהמה רבה</b>: ראה גם לעיל ע' רס ובהערה 73."],["4782","89","<b>יוצר משרתים. . ואשר משרתיו</b>: ראה גם לעיל ע' רסא ובהערה 86."],["4783","90","<b>מלאכים. . דשא עשב</b>: ראה זהר בראשית יח, ב. אוה\"ת בראשית לג, ב. לה, ב. סה\"מ תרכ\"ח ע' ג. ע' קסט. ע' קצא. סה\"מ תרכ\"ט ע' קח. תר\"ל ע' קנה. מים רבים תרל\"ו ע' קעא."],["4784","91","<b>כי תהיו אתם לי ארץ חפץ</b>: מלאכי ג, יב [בהוספת תיבת: לי — ראה לעיל ע' קלא ובהערה 44]."]]],[4801940480,"בגופים בקיום התומ\"צ שלהם וכמ\"ש<sup data-n=\"4785\">92</sup> בשם הרה\"מ נ\"ע<sup data-n=\"4786\">93</sup> בענין במי נמלך<sup data-n=\"4787\">94</sup> בנשמתן של צדיקים כו' וד\"ל. ..], והכח להצמיח צמיחה זאת נק' יבולה כו', וזהו ונתנה הארץ יבולה שתוציא כל פנימי' כחה מהעלם אל הגילוי אחרי ונתתי גשמיכם שלא ע\"י שליח וכנ\"ל דגשם זה שהוא מן השמים דייקא הוא המוציא פנימי' הכח במקבל להיותו מבחי' המים שמעל השמים כו' כנ\"ל וד\"ל.\n<b>ועץ</b> השדה יתן פריו, הנה פריו הוא מל' בן פרת יוסף<sup data-n=\"4788\">95</sup> והיינו נשמות שהם במדריגת יוסף כי יש נשמות שהם במדריגת שבטים [... ויש כמה מדריגות בענין השבטים שבטים דבריאה ושבטים אשר שרשם במדות דאצי'<sup data-n=\"4789\">96</sup> ויש בחי' אשר שרשם באו\"א<sup data-n=\"4790\">97</sup> ויש בחי' ששרשם בבחי' הכתר<sup data-n=\"4791\">*98</sup> וכמ\"ש ששם עלו שבטים<sup data-n=\"4792\">98</sup> שבטי י\"ה עדו\"ת לישראל שזהו ששרשם בבחי' הכתר הנק' עדות<sup data-n=\"4793\">99</sup> כו'. ..], אך כל אלה הם נשמות אשר שרשם בבחי' אא\"ס המלובש בבחי' הקו\"ח אבל יש בחי' נשמות חדשות<sup data-n=\"4794\">100</sup> אשר שרשם בבחי' אא\"ס שלא בא עדיין להאיר בבחי' הקו\"ח כו' וזהו בחי' יוסף וזהו בחי' עלי עין<sup data-n=\"4795\">101</sup> אור שלמעלה מהשתלשלות אשר שרשם בעי\"ן רבתי כנ\"ל<sup data-n=\"4796\">102</sup>, וע\"ז אומר ועץ השדה יתן פריו כי עץ השדה הוא בחי' עה\"ח ויתגלו ע\"י נשמות חדשות הנ\"ל שלא נמדדו בבחי' הקו\"ח רק הם בבחי' א\"ס כו'. ועוד יש לפרש בענין ועץ השדה יתן פריו היינו שבהעץ יהי' טעם הפרי<sup data-n=\"4797\">103</sup> ולא כמו בתחילה שהוציאה הארץ עץ עושה פרי בלבד כו' והענין הוא כי העץ הוא החומר והפרי הוא הצורה וכן בנשמות החומר שבהם נק' עץ והצורה שהיא הנשמה עצמה נק' פרי ולע\"ל יתגלה אא\"ס בבחי' הנשמה והגוף ביחד עד שהגוף ירגיש בחי' אא\"ס כמו הנשמה ממש [... וכמ\"ש וכל קרבי את שם קדשו<sup data-n=\"4798\">104</sup> וכמ\"ש יקימנו ונחי'<sup data-n=\"4799\">105</sup> שנינו הגוף והנשמה לפניו ממש כו'. ..] וזהו ועץ השדה יתן פריו העץ עצמו שהוא החומר כו', וכ\"ז יהי' כאשר בחקתי תלכו ומצותי תשמורו כו'<sup data-n=\"4800\">106</sup> ועשיתם אותם כו'<sup data-n=\"4801\">107</sup> אז ונתתי כו' שתזכו לכל אלו הבחי' כו' וד\"ל.",[["4785","92","<b>[והוא. . וכמ\"ש</b>: ג: והוא. . [וכמ\"ש."],["4786","93","<b>בשם הרה\"מ נ\"ע</b>: ראה גם לעיל ע' סח ובהערה 12."],["4787","94","<b>במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. לקו\"ש פ' החודש כרך טז ע' 487 בהערה."],["4788","95","<b>בן פרת יוסף</b>: ויחי מט, כב."],["4789","96","<b>שבטים דבריאה. . דאצי'</b>: ראה גם לעיל ע' שכח ובהערות 32־ 37."],["4790","97","<b>שבטים. . באו\"א</b>: ראה גם תו\"א וישב כח, ג. ביאוה\"ז במדבר פה, ד. תו\"ח וישב ריב, ב."],["4791","*98","<b>שבטים. . הכתר</b>: ראה גם לקו\"ת פקודי ז, ג."],["4792","98","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["4793","99","<b>הכתר הנק' עדות</b>: ראה גם לקו\"ת פקודי ז, ב ואילך. תו\"ח פקודי ח\"ב תמג, ג ואילך."],["4794","100","<b>נשמות חדשות</b>: ראה גם בענין נשמות חדשות לעיל מאמר ד\"ה אם בחוקותי הא' על יד הערה 121. ע' כז ובהערה 101."],["4795","101","<b>עלי עין</b>: המשך הכתוב בן פרת."],["4796","102","<b>כנ\"ל</b>: בריש המאמר."],["4797","103","<b>שבהעץ יהי' טעם הפרי</b>: רש\"י בראשית א, יא."],["4798","104","<b>וכל קרבי את שם קדשו</b>: תהלים קג, א. ראה גם לעיל מאמר ד\"ה את שבתותי תקצ\"ח על יד הערה 103."],["4799","105","<b>יקימנו ונחי'</b>: ישעי' ו, ב."],["4800","106","<b>ומצותי תשמרו</b>: אבג: ושמרתם — קדושים כ, ח."],["4801","107","<b>אותם כו</b>: א: ליתא."]]],[4801940130,"<b>בס\"ד</b>\n<b>אם</b> בחוקותי<sup data-n=\"4802\">1</sup> תלכו<sup data-n=\"4803\">2</sup> כו' וארז\"ל הלואי בחוקותי תלכו<sup data-n=\"4804\">3</sup> כו'. הנה להבין ענין בחוקותי שהוא ל' חקיקה<sup data-n=\"4805\">4</sup> יש להבין מאמר הזה\"ק פ' אמור<sup data-n=\"4806\">5</sup> ת\"ח אורייתא סתים וגלייא<sup data-n=\"4807\">6</sup> וישראל סתים וגלייא כמו דשמא קדישא סתים וגלייא. והנה ביאור סתים וגלייא דתורה היינו מה שניתנה התורה בבחי' חרות על הלוחות עשרת הדברים [... כי עשרת הדברות כוללי' כל התורה<sup data-n=\"4808\">7</sup> כו'. ..] שהוא בבחי' חקיקה ועוד ניתנה בבחי' כתיבה בס\"ת ע\"י משה שזהו בחי' גלייא [... וזהו בד\"כ אך בד\"פ יש בזה ששה מדריגות, כי הנה התורה היא בבחי' חכמה למע' מאותיות ויש בחכ' שתי מדריגות סתים וגלייא [ע\"ד שכל הנעלם מכל רעיון<sup data-n=\"4809\">8</sup> שהיא עצמי' כח השכל ומה שבכחו לבוא לידי גילוי] ואח\"כ כשניתנה בבחי' אותיות ניתנה מתחילה בבחי' חקיקה שזהו ענין סתים בד\"כ אבל בד\"פ יש בזה סתים וגלייא שהוא ענין שתי לוחות לוח הא' בבחי' סתים והשני בבחי' גלייא [וע\"ד הקבלה שני לוחות הוא בחי' לאה ורחל אותיות המח'<sup data-n=\"4810\">9</sup> ואותיות הדיבור<sup data-n=\"4811\">10</sup> ושרשן בפנימי' הכתר וחיצונית הכתר כמשי\"ת] ואח\"כ כשניתנה בבחי' כתיבה שהוא ענין גלייא בד\"כ כנ\"ל אבל בפרט יש בזה סתים וגלייא, כי תושב\"כ נחשב לסתים כי נעלם המכוון באותיות עד שלא יוכלו להורות כלל מזה אם לא ע\"י תושבע\"פ דייקא שממנה הוראה יוצאה איך להורות הלכה למעשה שזהו עיקר הגלייא בסוף כל המדריגות, ונעוץ תחילתן בסופן<sup data-n=\"4812\">11</sup> שהוא ענין סתים דתורה דחכ' שלמעלה מאותיות בסופן שהוא ענין גילוי דתשבע\"פ, כי מי שיודע עומק המכוון דייקא יוכל לפרש ולבאר הדבר היטיב, לכן חכמים מקור דתושבע\"פ ידעו לפרש ולבאר את התורה מצד עומק הביטול שלהם בפנימי' ועצמי' א\"ס כמ\"ש מלובש בתו' הפנימי' שהוא ענין סתים דחכ' כנ\"ל וכמשי\"ת בענין לבו דואג בקרבו.",[["4802","1","<b>אם בחוקותי</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה לקו\"ת ביאור לד\"ה אם בחוקותי מה, ד ואילך. מאמרי אדה\"ז כתובים ח\"א ע' עא ואילך. אוה\"ת בחוקותי כרך ג ע' תתקלב ואילך."],["4803","2","<b>אם בחוקותי תלכו</b>: בחוקותי כו, ג."],["4804","3","<b>הלואי בחוקותי תלכו</b>: ראה גם לקו\"ת בחוקותי מח, רע\"א. מאמרי אדה\"ז תקס\"ו ע' קסג. ע' קסו. תו\"כ כאן ובפי' הראב\"ד וקרבן אהרן. ע\"ז ה, סע\"א."],["4805","4","<b>בחוקותי שהוא ל' חקיקה</b>: ראה גם לעיל מאמר ד\"ה אם בחוקותי הא' ובהערה 53."],["4806","5","<b>מאמר הזה\"ק פ' אמור</b>: ראה שם פ' אחרי עג, א. עא, ב."],["4807","6","<b>אורייתא סתים וגליא</b>: ראה גם ש\"א ב, ב הערה 24."],["4808","7","<b>עשרת הדברות כוללי' כל התורה</b>: ראה תניא פל\"ו. פנ\"ג ובמ\"מ הגהות והע\"ק להנ\"ל. תו\"ח שמות ח\"א יא, ג. וש\"נ."],["4809","8","<b>שכל הנעלם מכל רעיון</b>: ראה פיוט אל מסתתר. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' עתר ובהנסמן במ\"מ לשם. מאמרי אדה\"א בראשית ע' ח. וש\"נ."],["4810","9","<b>לאה. . המח'</b>: ראה סידור שחרית ס, ג. סט, א. מאמרי אדה\"א נ\"ך ע' קג. וש\"נ. לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 126."],["4811","10","<b>ורחל. . הדיבור</b>: ראה ע\"ח שער אח\"פ ש\"ד, פ\"א. סידור שם. מאמרי אדה\"א ויקרא ח\"א ע' רכז. וש\"נ. לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 144."],["4812","11","<b>ונעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."]]],[4801940194,"<b>ועד\"ז</b> יש ששה מדריגות בישראל כי ישראל מתקשראן באורייתא<sup data-n=\"4813\">12</sup> ואותי' התורה המה שרשים לנש\"י<sup data-n=\"4814\">13</sup> ולכן מושרשים המה בכל פרט ופרט מששה מדריגות דתו' הנ\"ל רק שההפרש הוא דתורה היא בחי' חסד<sup data-n=\"4815\">14</sup> דא\"ס כח הירידה שבו ממהו\"ע עד שנעשה מקור בקירוב להתהוות העולמות מאין ליש [שזהו ע\"י ששה מדריגו' דתו' כו' כמשי\"ת וזהו באורייתא ברא קוב\"ה עלמא<sup data-n=\"4816\">15</sup> ולכן נק' התורה תורת חסד על לשונה<sup data-n=\"4817\">16</sup> כו' וד\"ל]. אבל נש\"י הוא בחי' גבורה היינו שאחר התהוות העולמות ע\"י התורה מאין ליש המה פועלים ביטול העולמות מאין ליש ולמע' מע' עד אין האמיתי שהוא בחי' עצמי' אוא\"ס ב\"ה כמשי\"ת וזהו הי' עיקר המכוון בראשית ההשתלשלות ענין התגלות אא\"ס בחיצוני' העולמות שזהו דייקא ע\"י ביטולם מיש לאין, ושלימות הגילוי הזה יהי' לעתיד דכתיב וימלא כבוד ה'<sup data-n=\"4818\">17</sup> את כל הארץ שהוא התגלות שם הוי' דייקא בחיצוני' העולמות הנק' ארץ כו' וכמ\"ש וראו כל בשר יחדיו<sup data-n=\"4819\">18</sup> כי פי הוי' דיב\"ר התגלות<sup data-n=\"4820\">19</sup> הוי' בדיבור שהמה אותיות שנבראו בהם שו\"א חיצונית העולמות ולא כעכשיו שמקבלים חיותם משם אלקים שהוא ענין הצמצום<sup data-n=\"4821\">20</sup> וההסתר, וזהו דייקא ע\"י ישראל שמקיימי' את התורה בששה מדריגו' הנ\"ל כמשי\"ת מחדשי' אור התורה ממקורא דכולא<sup data-n=\"4822\">21</sup> עד שנעשית תורה אור להאיר בהשתלשלות בגילוי דייקא ולכן נאמר בשביל התורה ובשביל ישראל<sup data-n=\"4823\">22</sup>, כי פנימי' המכווון של הבריאה הי' בשביל שניהם ביחד דייקא שהמה יקיימו את התורה [וכמ\"ש ע\"פ שניים עדים יקום דבר<sup data-n=\"4824\">23</sup> שהקימה לדבר שהמה צירופי אותיות שנבראו בהם שו\"א הוא בחי' התגלו' אוא\"ס בחיצוני' העולמות כנ\"ל הוא ע\"פ שניים עדים דייקא אורייתא וישראל בחי' חסדים וגבורות כו', שניים עדים דייקא מגלים האמת בלי ספק, וכן למע' אורייתא וישראל שניהם ביחד דייקא המה מגלים אמת ה' לעולם<sup data-n=\"4825\">24</sup> כו' וד\"ל] אבל באורייתא ברא קוב\"ה עלמא, באורייתא בלבד, כי התהוות העולמות בבחי' העלם והסתר אא\"ס הוא ע\"י אורייתא הנק' תורת חסד בלבד כו' וד\"ל. ..].\n<b>וזהו</b> פי' מאמר הזה\"ק כמו דשמא קדישא סתים וגלייא כי שמא קדישא הוא קוב\"ה כמשי\"ת הוא סתים בבחי' סדכ\"ס<sup data-n=\"4826\">25</sup> פי' שהוא סתים ונעלם אפי' מבחי' סתים דחכ' דאורייתא שלמע' מאותיות כמ\"ש עושה פלא<sup data-n=\"4827\">26</sup>, שבחי' פלאות חכ'<sup data-n=\"4828\">27</sup> כעשי'",[["4813","12","<b>ישראל מתקשראן באורייתא</b>: ראה זהר אחרי עג, א."],["4814","13","<b>ואותי' התורה המה שרשים לנש\"י</b>: ראה גם שע\"ת פג, ג ובהנסמן במ\"מ לשם."],["4815","14","<b>דתורה. . חסד</b>: ראה בסמוך הערה 16."],["4816","15","<b>באורייתא ברא קוב\"ה עלמא</b>: ראה זהר בהקדמה ה, א. שמיני לה, ב."],["4817","16","<b>תורת חסד על לשונה</b>: ראה גם לעיל ע' רפא ובהערה 85."],["4818","17","<b>וימלא כבוד ה'</b>: שלח יד, כא."],["4819","18","<b>וראו כל בשר יחדיו</b>: ישעי' מ, ה."],["4820","19","<b>התגלות</b>: תיבה זו הוכפלה בהכת\"י."],["4821","20","<b>אלקים. . הצמצום</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["4822","21","<b>ממקורא דכולא</b>: זהר בראשית לג, א."],["4823","22","<b>בשביל התורה ובשביל ישראל</b>: ראה רש\"י בראשית א, א. תו\"ח בראשית מד, א הערה 6."],["4824","23","<b>ע\"פ שניים עדים יקום דבר</b>: פ' שופטים יט, טו [ושם שני. בדילוג — ראה סוטה לא, ב. מאמרי אדה\"א שמות ח\"ב ע' תרנ. וש\"נ]."],["4825","24","<b>אמת ה' לעולם</b>: תהלים קיז, ב."],["4826","25","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["4827","26","<b>עושה פלא</b>: בשלח טו, יא."],["4828","27","<b>פלאות חכ'</b>: ראה גם לקו\"ת שה\"ש כז, ד. מאמרי אדה\"א נ\"ך ע' קנו. וש\"נ. תו\"ח שמות ח\"א כא, ב. וש\"נ."]]],[4801940251,"יחשב לגבי, והגליא שבו הוא ענין הגילוי שלו בחיצוני' העולמות מאין ליש [שזהו ג\"כ גלייא דקוב\"ה דייקא כי הוא לבדו בכחו ויכולתו לברוא מאין ליש בלתי עילה אחרת קודמת ליש הזה כמבואר באגה\"ק<sup data-n=\"4829\">28</sup> בענין איהו וחיוהי חד], ולא יוכל להיות ירידת הגלייא מסתים שבו שהמה רחוקים בערך אם לא ע\"י ששה מדריגות דתורה שזהו כמו אמצעי לחבר סתים דקוב\"ה להיות יורד ונמשך בבחי' גלייא דחיצוני' העולמות ולכן נצרך להיות התורה כלול משני מדריגות כדרך כל ממוצע המחבר שמוכרח להיות כלול משני דברים<sup data-n=\"4830\">29</sup> המתחברים כו', וכן ישראל שהמה מחברים בחי' הגלייא שכבר נגלה למקורו ושרשו שהוא בחי' סתים בדרך העלאה שעי\"ז נעשה התגלות אא\"ס כנ\"ל מוכרח להיות ג\"כ שיהי' בהם משני המדריגו' דסתים וגלייא, וזהו מאמר הזה\"ק כמו דשמא קדישא סתים וגלייא פי' זהו נתינת טעם למה אורייתא וישראל המה סתים וגלייא מצד שהמה מחברים בחי' סתים וגליא דשמא קדישא בב' אופנים דירידה ועלי' כנ\"ל לכן מוכרח להיות בהם ג\"כ משני בחי' הנ\"ל כו' וד\"ל. ..].\n<b>ולהבין</b> כל הנ\"ל ע\"פ משלים איך שלא הי' יכול להיות התגלות אוא\"ס בחיצוני' העולמו' אם לא ע\"י ששה מדריגו' דתו' הנ\"ל דייקא, הנה יש להבין מתחילה ההפרש בד\"כ בין אותיות הכתובי' לאותיות החקוקי' כי הנה אותיות הכתובים בקלף המה מדבר נבדל מהקלף שהוא הדיו רק אעפ\"כ מתאחדים בקלף כאלו הם דבר א' מתחילת הוויתם כי אין ממשות באותיות הכתובים רק ציור בלבד, אך אע\"פ שהם מתאחדים בתכלית מ\"מ מצד שמהותם הוא מדבר נבדל מסתירים המה על עצם הציור שיהי' נגלה באופן אחר ולא כמו שהי' כלול הציור הזה בתחילה בכח היולי דלבנונית הקלף, אך אותיות החקוקי' באבן הנה נגלה הציור שהי' כלול בתחילה בחומר האבן בבחי' היולי עתה בא להתגלות כמ\"ש מצד שהציור לא נעשה מדבר נבדל רק מיני' ובי', והנה עד\"מ גשמי הזה יובן ג\"כ עוד משל רוחני יותר מבחי' הנפש שיש בה ב' מיני אותיות בד\"כ חקוקי' וכתובים [ובפרט יש כמה מדריגו' באותיות הנפש כמשי\"ת בעז\"ה] ומבשרי אחזה<sup data-n=\"4831\">30</sup> ומזה יובן למעלה אמיתית אלקות בענין סתים וגליא דתו' כו' כמשי\"ת.\n<b>דהנה</b> אותיות הדיבור בנפש נק' אותיות הכתובים להיות שמבואר למעלה בענין אותיות הכתובים שהמה מדבר נבדל המתאחד ולא יחוד בעצם מתחילת הוויתו כ\"ה באותיות הדיבור כשמגלי' איזה שכל או איזה מדה הנה מקורם הוא מהבל הלב<sup data-n=\"4832\">31</sup> שזהו נה\"ט החיונית שבאדם בחי' חי שבמדבר ושכל ומדות מקורם מנפש השכלי' [... כי מה שמבואר בלק\"א<sup data-n=\"4833\">32</sup> נפש הטבעיות הוא כלול משתי נפשות",[["4829","28","<b>באגה\"ק</b>: ס\"כ קל רע\"ב."],["4830","29","<b>ממוצע. . כלול משני דברים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. סידור שער הל\"ג בעומר שו, ב. אוה\"ת בשלח ע' תקע ואילך."],["4831","30","<b>ומבשרי אחזה</b>: איוב יט, כו."],["4832","31","<b>באותיות הדיבור. . מהבל הלב</b>: ראה אגה\"ק ס\"ה."],["4833","32","<b>שמבואר בלק\"א</b>: ראה תניא פ\"א. פ\"ב."]]],[4801940304,"נפש השכלי' ונה\"ט כמבואר בתורה דאם בחוקתי<sup data-n=\"4834\">33</sup> מאדמו\"ר הזקן נבג\"מ] ונמצא שהמה נמשכות משני מקורים נבדלים, אך אעפ\"כ מתאחדים בתכלית כי הדיבור מתאחד הוא עם השכל בעת שמדבר דברי שכל ונעשה כמו חומר לגבי' שהוא מעין צורת השכל, אך מ\"מ כיון שהמה נבדלים בעצם מתחילת הוויתם לכן המה מסתירים על אור השכל עד שלא נגלה למקבל רק חיצוני' שבו שהוא הגשמת רוחני' אור השכל כו' ולכן לא קאים אדעתי' דרבי'<sup data-n=\"4835\">34</sup> כו', וכן אנו מוצאים באותיות המח' אעפ\"י שהמה אותיות נעלמי' בלתי התגלות לזולתו [ונק' לבוש מחובר<sup data-n=\"4836\">35</sup> בל' אדמו\"ר שליט\"א<sup data-n=\"4837\">36</sup> ] והמה רוחניי' יותר מאותיות הדיבור מ\"מ המה בחי' אותיות כתובים לגבי אור השכל, כידוע שעמקות השכל הוא בבחי' הברקה באותיו' קצרים על המוח בלתי התיישבות בחומר המוח ומה שנגלה ונתרחב ההברקה בהשגה שעי\"ז נעשה התיישבות בכלי המוח הגם שהמה מגלי' את השכל בחומר המוח מ\"מ המה מסתירים את העומק של השכל כי העומק לא יוכל להתיישב וע\"י העלמו והסתרו דייקא נעשה הגילוי בכלי המוח שהוא הארה בעלמא העלם<sup data-n=\"4838\">37</sup> מעצם עמקו ותמציתו כמ\"ש, והיינו מפני שהמח' חיצוני' נבדלת בעצם מהשכל ואין מקורה מהשכל [... כי אם הי' מקור המח' מהשכל לא הי' יכול לחשוב מח' בטילה רק מחשבת שכל כו'. ..] ולכן היא מסתרת על אור השכל ונק' אותיו' כתובים.\n<b>אך</b> יש עוד בחי' מח' הנק' מח' עיוני' והיינו האותיות של השכל בעצמו שבהם נתפס הברקת השכל ולכאורה המה אותיו' חקוקי' כי המה עם השכל בבחי' יחוד מתחילת הוויתו היינו בעת המשכתו ממקורו מכח המשכיל לא יוכל להתפס בבחי' מציאות דבר מה בלעדי האותיות ונמצא שיש בהם צד חקיקה, אך באמת גם המה נק' אותיות הכתובים לגבי עצם הנפש [... הגם שנק' אותיו' חקוקי' לגבי המשכת הנפש בכלי' שהוא חומר המוח וכן המשכתו בלב פועל אותיות המדות שהמה אותיות חקוקי' נחשבים לגבי אור וחיות הנמשך בהם כו'. ..], כי שכל הפרטי הוא הסתר והעלם עצמו' הנפש השכלי' המשכלת כל מיני שכל ושכל זה הפרטי הוא הארה בעלמא בלבד מעצם הנפש. ונמצא מובן מזה שאפי' שרש האותיות של השכל שנתפס בהם שמקורם בכח המשכיל למע' מן השכל כי המה הממשיכים אותן מהעלם אל הגילוי ומוכרח לומר ששרשם קדום בעצם כח המשכיל מהשכל הפרטי והמה מקורו אך אח\"כ כשבאים לידי גילוי נעשים כלי אלי' [וכידוע דשרש הכלים קדם<sup data-n=\"4839\">38</sup> וכ\"ה בכל פרט דשכל ומדות כו'], מ\"מ במקורם ושרשם בכח עצם הנפש השכלי' אותיו' כתובים יחשבו להיות שהמה מסתירים עצם אור הנפש שלא יתגלה כמ\"ש כ\"א הי' מתגלה כמ\"ש לא הי' מציאות התהוות שכל פרטי כו' וד\"ל. ..].",[["4834","33","<b>בתורה דאם בחוקתי</b>: ראה מאמרי אדה\"ז תקס\"ו ע' קסג. ע' קעט. לקו\"ת בחוקותי מז, ג. וראה גם לעיל מאמר ד\"ה אם בחוקותי תר\"י בתחילתו ובהנסמן לשם."],["4835","34","<b>לא קאים אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. לעיל ע' קצד ובהערה 15."],["4836","35","<b>המח'. . לבוש מחובר</b>: לקו\"ת בחוקותי כאן מו, א."],["4837","36","<b>אדמו\"ר שליט\"א</b>: הצ\"צ."],["4838","37","<b>העלם</b>: כ\"ה כהכת\"י."],["4839","38","<b>דשרש הכלים קדם</b>: ראה תו\"ח בראשית י, ד ובהערה 14."]]],[4801940354,"<b>אך</b> אמיתת אותיות החקוקי' בנפש עצמם יובן עפ\"י הקדמה להבין בשרש אותיות הדיבור מה עניינם שאינו כמו שנראה לכאורה שהמה נמשכים מהקול המתחלק במוצאות הפה אחה\"ע<sup data-n=\"4840\">39</sup> כו' ונמצא לפ\"ז שמקורם הכללי הוא הקול ומקור הפרטי דכל אות הוא הגרון או השפתיים כו' שא\"כ הי' צריך להיות הבהמה יכולה לדבר וכן התינוק כיון שיש להם המוצאות, ועוד איך הי' יכול להיות התחלקות שתי אותיות ממוצא אח\"ד כו' וד\"ל. ועוד ראי' ברורה שא\"כ הי' צריך להיות רצון הנפש בעת שנצרך לדבר אות ב' להניע השפתיים באופן שיתגלה אות הנ\"ל וכן בכל האותיות, וע\"ד הכאת העץ בכינור<sup data-n=\"4841\">40</sup> ותנועת האצבעות שהמה מקורי' לקולות הנולדים מהם, אנו רואים שהנפש מכוונת ברצונה לתנועת האצבעות והכאת העץ והקולות מתהוווין ממילא, אבל באותיות הדיבור אנו רואי' שאינו כן שאין הנפש מכוון כלל איך להניע המוצאות ואינו יודע כלל אופן תנועתם רק הוא מכוון לדבר האותיות והאותיות נמשכים ממילא ומתלבשים במוצאות להניע אותם כפי הצורך, ומכ\"ז הוא ראי' ברורה שהתהוות האותיות הוא קדום למוצאות הפה והבל הלב, וא\"א לומר שמקורם מהשכל להיות שאנו רואים בתינוק אעפ\"י שאין בו שכל יוכל לדבר וע\"כ לומר ששרשם למע' מהשכל בעצם הנפש וכמ\"ש ויהי האדם לנפש חי' לרוח ממללא<sup data-n=\"4842\">41</sup>, אך א\"כ למה לא יוכל התינוק לדבר בתחילת לידתו כיון שיש בו נפש המדברת, אך הענין שיש למציאות האותיות בנפש<sup data-n=\"4843\">42</sup> מ\"מ לא יוכלו לבוא לידי גילוי רק ע\"י כח החכ' הכלולה בעצם הנפש הנק' קדמות השכל<sup data-n=\"4844\">43</sup> שנק' מצרף לחכ'<sup data-n=\"4845\">44</sup> והוא אינו בא לידי גילוי רק בתשלום היניקה שאז נעשה בתינוק שלימות המוחין להיות שורה בו מציאות כח קדמות השכל בדרך השראה בלבד ולא בגילוי ולא לא<sup data-n=\"4846\">45</sup> יוכל להשכיל מאומה ואעפ\"כ הוא יכול לדבר כו' וד\"ל.\n<b>וזהו</b> בחי' אמיתת אותיות החקוקי' שהוא בחי' שרש אותיות הדיבור הקבועי' בנפש עצמה [... ומה שמבואר למע' שאותיות הדיבור הוא אותיות הכתובים היינו חומר האותיות שהוא הקול דהבל הלב שבו מתלבשים האותיות להיות נשמעי' ע\"י במורגש ואעפי\"כ לא יוכלו להתקבל בנפש השומע אם לא ע\"י התחלקות במוצאות הפה כו' אבל צורת האותיות היינו עצמי' האותיות קבועי' בנפש עצמה למע'",[["4840","39","<b>אחה\"ע</b>: ס\"י פ\"ב, מ\"ג. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."],["4841","40","<b>הכאת העץ בכינור</b>: ראה סה\"מ תרל\"ג ח\"ב ע' שנז."],["4842","41","<b>ויהי האדם. . לרוח ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["4843","42","<b>למציאות האותיות בנפש</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. שער היחוד והאמונה פי\"א. אגה\"ק ס\"ה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרלט וע' תשל ובהנסמן במ\"מ לשם. שעה\"י קלה, ב. מאמרי אדה\"א במדבר ח\"א ס\"ע שט. תו\"ח בראשית כח, א ואילך. בשלח ח\"א קמ, ג. קמח, א ואילך. לעיל ע' ריח."],["4844","43","<b>קדמות השכל</b>: ראה אגה\"ק ס\"ה. תו\"א מג\"א צא, ב. לקו\"ת כאן מו, ב. (הוספות לויקרא) נד, סע\"א. במדבר יג, א. תו\"ח בראשית כב, ג. שעה\"י קמד, א. סה\"מ תרל\"ב ח\"א ע' כט. ע' קמו ואילך. וש\"נ. תרנ\"ט ע' ח."],["4845","44","<b>מצרף לחכ'</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרכז ובהנסמן במ\"מ לשם. מאמרי אדה\"א נ\"ך ע' קכ. וש\"נ. דרושי חתונה ח\"ב ע' תקעב. קונטרסים ע' תקמז. וש\"נ. תו\"ח שמות ח\"א יב, א. מז, ב."],["4846","45","<b>לא</b>: כנראה מיותר."]]],[4801940400,"מאותיות השכל אפי' מכמו שהם בשרשם בנפש שאינם רק בחי' חיצוני' הנפש ולכן אינם פועלים רק גילוי הנפש במציאות שכל פרטי ולא התגלותו כמ\"ש אבל אותיות הדיבור חקוקי' המה בעצמי' הנפש ובכחם לפעול התגלות הנפש כמ\"ש, וראי' שהמה בדומה לפשיטות ועצמי' הנפש שהוא מקור לכל הפרטים דשכל ומדות ואפי' לשני הפכיים כמו מדות דחו\"ג וזה מורה על פשיטותו וכ\"ה באותיות הדיבור אע\"פ שהמה כלים המקבלים התגלות הכחות דשכל ומדות בתוכם מ\"מ המה כלים פשוטים לקבל כל מיני כחות דשכל ומדות ואפי' מדות הפכים, כי אין הפרש בין אותיות שמדבר דברים<sup data-n=\"4847\">46</sup> אה' לאותיות שמדבר דברי שנאה או שכל, וע\"כ לומר שזהו גילוי הנפש בעצמו כמ\"ש שמשנה בגדי' ממהות משפיע להעשות כלי מקבל לגלות כל הכחות לזולתו כו' וד\"ל. ..]. ולכן הפגם דברית הלשון<sup data-n=\"4848\">47</sup> שוה לפגם דברית המעור<sup data-n=\"4849\">48</sup> ששניהם פוגמים בכלל כל הנפש ולא באבר פרטי כשאר עשה ול\"ת שהמה נק' אברי הנפש בלבד כו' וד\"ל [... והנה עד\"ז יובן באותיות המח' חיצוני' הל' שאעפ\"י שהוא לבוש לבד אפי' לגבי אותיות עצמי' דשכל הנ\"ל שנק' מח' עיונית מ\"מ בשרשם המה מפנימי' ועצמי' הנפש כמו אותיו' הדיבור הנ\"ל בבחי' חקיקה בנפש כי גם בהם נמצא הכח לגלות כל הכחות לעצמו כמו גילוי השכל בכלי המוח או מדות הפכי' דאה' ושנאה תיכף עולה אל המוח להרהר בהם מזה נראה שהמה אותיות פשוטי' נמשכי' מפשיטות ועצמי' הנפש וכנ\"ל באותיות הדיבור, אך יש בהם כח יותר עמוק מאותיות הדיבור והוא במה שאנו רואים שהרצון לא יוכל למשול בהם כלל אבל בדיבור יוכל למשול הרצון בהם למנוע א\"ע שלא לדבר אבל לא יוכל להפשיט א\"ע ממח' כלל, ומוכרח לומר שבפנימי' ועצמי' הנפש יש בו שני כחות הא' כח הגילוי ונק' רצון וכמשי\"ת והוא מה שיכול להתגלות כמ\"ש ושם הוא שרש אותיות הדיבור ושרש כח המוליד ולכן מוליד נפש שלימה אך אעפ\"כ אינו נתפס בזה עד שלא יוכל להתפס במ\"א וראי' שיוכל להוליד כמה נפשות, אבל כח הב' הוא כח ההעלם שמלביש ומעלים כל עצמי' הנפש עד שלא יוכל להתפס במ\"א וזהו למע' מרצון שבנפש שאינו רק מרוצת הנפש כח הגילוי שבו וזהו שרש אותיות המחשבה ולכן לא יוכל להפשיט א\"ע ממח' כי לא יוכל למשול ברצונו עליהם מצד שהמה בפנימי' הנפש למע' מרצון שבנפש כו', ולכן הרהורי עבירה קשי' מעבירה<sup data-n=\"4850\">49</sup> להיותם מלבישים כל הנפש עד שלא יוכל להפשיט א\"ע מהם לדבק א\"ע באלקות כו', ולכן אמרו בשם הבעש\"ט נבג\"ם שבכל מקום שמחשבתו<sup data-n=\"4851\">50</sup> של אדם מתפשטת שם הוא בעצמו כו' וד\"ל. וזהו ענין שרש לאה ורחל ע\"ד הקבלה ששרשם בקו האמצעי וכמבואר ברמ\"ז פ' בחוקתי בתחילת הסדרה, ואפ\"ל ששרשם בפנימי' הכתר וחיצוני' וכנ\"ל וד\"ל. ..].",[["4847","46","<b>דברים</b>: כנצ\"ל: דברי."],["4848","47","<b>הפגם דברית הלשון</b>: ראה גם אוה\"ת בחוקותי כרך ג' ר\"ע תקלז [ושם: בספרים]. מאמרי אדה\"ז כתובים ח\"א כאן ע' עג."],["4849","48","<b>דברית הלשון. . דברית המעור</b>: ראה ס\"י פ\"א, מ\"ג. ספ\"ו. ראשית חכמה שער הקדושה פי\"א. פי\"ז. של\"ה שער האותיות אות ש (קח, א)."],["4850","49","<b>הרהורי עבירה קשי' מעבירה</b>: ראה יומא כט, א. לעיל ע' קפח."],["4851","50","<b>בשם הבעש\"ט. . שבכל מקום שמחשבתו</b>: ראה בן פורת יוסף פ' ויחי ד\"ה ביאור על קושיות הזוהר. . בפסוק ויחי יעקב. כתר שם טוב (קה\"ת) סנ\"ו. סער\"ה. לעיל ס\"ע שיא ובהערה 222."]]],[4801940443,"<b>והנה</b> ע\"ד המבואר באותיות הדיבור והמח' שמצד חומר שלהם המה בבחי' כתיבה ומצד צורתם המה בבחי' חקיקה כ\"ה בנקודות, ויובן דוגמא זאת בשני נקודות הראשונים דקמץ ופתח שהמה שרש כל הנקודות, דהנה מה שנק' קמץ ע\"ש שנע' ע\"י קמיצת השפתיים ופתח הוא מחמת שנעשה ע\"י פתיחת השפתיים אך באמת המה שני כחות רוחני' בעצמי' הנפש כי קמץ הוא בכתר<sup data-n=\"4852\">51</sup> ולכן בברכות ולמלשינים צריך לכוון בהוי' בניקוד קמץ<sup data-n=\"4853\">52</sup> מצד שהפגם שלהם מגיע בעצמו' הכתר וכמאמ' הפושעים בי בגופא דמלכא<sup data-n=\"4854\">53</sup> ור\"ת קמץ הוא קדמון מצוחצח צח<sup data-n=\"4855\">55</sup> כו' שהמה ג' אורות שבכתר וכמבואר בפרד\"ס<sup data-n=\"4856\">56</sup> שער הצחצחו'<sup data-n=\"4857\">54</sup> וד\"ל. ופתח הוא בחכמה<sup data-n=\"4858\">57</sup> וכמאמר פיה פתחה, בחכמה<sup data-n=\"4859\">58</sup> ולכן בברכות אתה חונן צריך לכוון בשם הוי' בניקוד פתח<sup data-n=\"4860\">59</sup> כו', אך שמתלבשים המה בלבד בקמיצת השפתיים ופתיחת השפתיים בכדי להשמע במורגש ולהתקבל בכלי המקבל וכנ\"ל באותיו' כו' וד\"ל. [... ופי' הדברי' דהנה אנו רואים באותיות הכתב שלא יוכל להיות התחלתם בלתי ציור הנקודה בתחילה כי הנקודה התחלת השטח דאותיו' עד שבלעדי הנקודה לא יוכלו לעשות שום ציור שטחי כלל, וכ\"ה באותיו' הדיבור לא יוכל להתגלו' שום אות ממוצאות הפה בלתי הנקודות וכמבואר בזהר דאתוין לקבל נקודין<sup data-n=\"4861\">60</sup> כגופא לקבל רוחא כי הנקודות המה חיות האותיות, וע\"כ לומר שגם באותיו' החקוקי' שבפנימי' ועצמי' הנפש אפי' באותיו' המח' דשם שהתחלת ציורם בנפש מתהווה ע\"י נקודות והיינו ע\"י קמץ ופתח כנ\"ל, כי הנפש הוא פשוט לגמרי מבחי' ציור אותיו' אך שנתעלם וחוזר ונפתח מהעלמו להתלבש בציור אותיות בעצמו, וההעלם הוא בחי' קמץ והוא שרש אותיו' המח' החקוקי' והפתח הוא שרש ציור אותיו' הדיבור הקבועי' בנפש כו', ולהיות ההעלם מעלים כל עצמי' הנפש כמשי\"ת לכן לא יוכל לפשוט א\"ע ממח' כו' וכנ\"ל. ונמצא שיש כאן ששה מדריגות בנפש עצמה היינו אותיות עצמי' דשכל ואותיות עצמי' דמדות שהמה חקוקי' לגבי החיות המלובש בהם וכתובים יחשבו לגבי עצמו' הנפש, ועוד שני בחי' אותיות החקוקי' בנפש עצמה והיינו שרש אותיו'",[["4852","51","<b>קמ\"ץ הוא בכתר</b>: ראה גם לעיל ע' קנו ובהערה 20."],["4853","52","<b>בברכות </b>[בברכת ]<b> ולמלשינים. . בהוי' בניקוד קמץ</b>: ראה פע\"ח שער העמידה ש\"ט, פי\"ט (בתחלתו ובמקומו). סידור קול יעקב במקומו. (שער הכוונות ענין כוונת העמידה דרוש ו וסידור חמדת ישראל — למהר\"ש וויטאל — במקומו). מאמרי אדה\"ז כתובים ח\"א כאן ע' עג. אוה\"ת ואתחנן ע' שפא. המשך תער\"ב ח\"ג ע' א'רי."],["4854","53","<b>הפושעים בי בגופא דמלכא</b>: ישעי' סו, כד. ראה זהר יתרו פה, ב. תו\"ח תצוה ח\"ב שמג, ב. וש\"נ."],["4855","55","<b>קדמון מצוחצח צח</b>: ראה ת\"ז ת\"ע קלה, ב. ספר הערכים חב\"ד ח\"ג מערכת אור קדמון, מצוחצח צח ע' תפב."],["4856","56","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט ובהערה 293."],["4857","54","<b>ור\"ת קמץ. . בפרד\"ס שער הצחצחו'</b>: פ\"ז. ראה גם לעיל ע' קנו ובהערה 19."],["4858","57","<b>ופתח הוא בחכמה</b>: ראה ת\"ז ת\"ע קכט, ב. ע\"ח שער השמות שער מ\"ד, פ\"א. מאמרי אדה\"א דברים ח\"ג ע' א'מב. וש\"נ. תו\"ח ויקהל ח\"ב שפז, ד. וש\"נ."],["4859","58","<b>פיה פתחה בחכמה</b>: משלי לא, כו."],["4860","59","<b>בברכות </b>[בברכת ]<b> אתה חונן. . הוי' בניקוד פתח</b>: ראה פע\"ח וסידור קול יעקב שם. (שעה\"כ וסידור חמדת ישראל שם). מאמרי אדה\"ז תקס\"ו ס\"ע כב ואילך. תקס\"ז ע' שצד. מארז\"ל ע' יד. כתובים שם. אמרי בינה פתח השער ח, סע\"ג. אוה\"ת בחוקותי כרך ג' ע' תתקלו. המשך תער\"ב ח\"ג ע' א'תמא."],["4861","60","<b>דאתוין לקבל נקודין</b>: ראה ת\"ז ת\"ה כ, ב."]]],[4801940481,"הדיבור ואותיות המח' שבנפש, ועוד שני בחי' נקודות החקוקי' בנפש עצמה שהמה מקור האותיות דמחו\"ד שבעצמי' הנפש והיינו קמץ ופתח כנ\"ל, וכ\"ז הוא מלבד אותיות המח' ואותיות הדיבור כמ\"ש מלובשים בחומר שהמה אינם נחשבים מעצמי' הנפש רק לבושי הנפש כו' וד\"ל. ..].\n<b>והנמשל</b> יובן למעלה דהנה א' בזה\"ק בריש הורמנותא דמלכא גליף גליפו בטה\"ע<sup data-n=\"4862\">61</sup> וידוע בסה\"ק דטה\"ע הוא בחי' הרשימו הנשאר אחר הצמצום<sup data-n=\"4863\">62</sup>, והצמצום הוא רק במדריגה אחרונה דאא\"ס שנק' מל' דא\"ס<sup data-n=\"4864\">63</sup> וזהו ותחת רגליו<sup data-n=\"4865\">64</sup> כמעשה לבנת הספיר וכעצם השמים לטוהר, ותחת רגליו הוא בחי' ומדריגה דאא\"ס כביכול שנעשה מקור לטוהר טה\"ע שהוא בחי' הרשימו ואח\"כ גליף גליפו הוא בחי' פנימי' הכתר וחיצוני' הכתר [כי ידוע שיש מחלוקת במקובלים<sup data-n=\"4866\">65</sup> אם הכתר הוא הא\"ס או שנחשב במנין הספי', והאריז\"ל מזכי שטרא לגבי תרי<sup data-n=\"4867\">66</sup> שמצד פנימיותו הוא הא\"ס ומצד חיצוני' שלו הוא נעשה שרש וראש לנאצלים וזהו ענין שתי גליפות הנ\"ל כו' וד\"ל].\n<b>ולהבין</b> ביאור כל הנ\"ל הנה מתחילה יש להבין פי' בחי' אחרונה דאא\"ס מה ענינו והאיך שייך לומר מדרי' באא\"ס שהוא אחד פשוט בתכלית כו' ויש להקדים המשל לזה מאור השמש המאיר לארץ שעצם השמש הוא מהות בריאה שיש בו בהירות והבריאה של השמש נק' מאור<sup data-n=\"4868\">67</sup> והבהירות שבו נק' אור עצמו ומה שהוא מאיר לארץ ולדרים זהו רק זיו בלבד כי מחמת שהוא דבר בהיר בעצם הוא מבהיק מזיוו לאחרים והזיו אינו שייך רק כשיש כלי לקבל הזיו אבל אם היינו יכולים לצייר שאין שום כלי לקבל הזיו לא הי' הזיו מתפשט כלל רק הי' ניכלל ובטל באורו העצמי, רק אעפ\"כ יש לזיו הזה במציאותו בשלימות בעצם האור אפי' כשלא הי' כלי לקבל וביתרון שלימות<sup data-n=\"4869\">68</sup> מהתפשטותו למטה כי ביכולתו להאיר כשהי'<sup data-n=\"4870\">69</sup> כלי לקבל",[["4862","61","<b>בריש. . גליף גליפו בטה\"ע</b>: במאמרי אדה\"ז על פרשיות התורה ח\"א ע' סז (בשולי הגליון) ועד\"ז בשע\"ת קי, א: בהקדמת הזהר (ראה הנסמן במ\"מ לשע\"ת שם). תקס\"ה ח\"ב ע' תרפט וע' תתיח: מאמר הראשון בזהר. בלקו\"ת בחוקותי כאן מו, ב בתחלת ספר זוה\"ק (בראשית ד' ט\"ו ע\"א)."],["4863","62","<b>דטה\"ע. . הרשימו הנשאר אחר הצמצום</b>: ראה גם לעיל ע' פה."],["4864","63","<b>במדריגה אחרונה. . מל' דא\"ס</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת ויקרא בהוספות נג, ב [וכן צ\"ל: בשעה\"י קמה, א הערה 10]."],["4865","64","<b>ותחת רגליו</b>: משפטים כד, י."],["4866","65","<b>מחלוקות במקובלים</b>: בלקו\"ת בחוקותי כאן מו, ג מציין לפרדס ש\"ג."],["4867","66","<b>והאריז\"ל מזכי שטרא לגבי תרי</b>: בלקו\"ת כאן מציין בע\"ח [שער דרושי אבי\"ע] שער מ\"א פ\"ג [ובדפו\"א שמ\"ב, פ\"א]. וראה גם לקו\"ת שה\"ש י, ב בע\"ח [שער מוחין דצלם] שער כ\"ב פ\"א [ובדפו\"א שכ\"ג, פ\"ה] אות ד. תו\"א מג\"א צא, ג ואילך. אוה\"ת מג\"א ע' צז ואילך. ביאוה\"ז להצ\"צ כרך א ע' ערה ואילך. המשך תרס\"ו ע' קסה ואילך."],["4868","67","<b>השמש נק' מאור</b>: ראה בראשית א, יד ואילך. ראה גם לקוטי ביאורים — קה\"ת — לשעה\"י קעד, ד. מאמרי אדה\"א נ\"ך ע' רמד. וש\"נ. תו\"ח תצוה ח\"ב שמז, ג."],["4869","68","<b>יש לזיו הזה. . וביתרון שלימות</b>: ראה גם שער היחוה\"א פ\"ג."],["4870","69","<b>כי ביכולתו להאיר כשהי'</b>: אוצ\"ל: כביכלתו להאיר כשיהי'."]]],[4801940515,"אותו כו'. וכן עד\"ז יובן באור רוחני שהוא מציאות השכל הנק' אור וכמו מאיר עיני חכמים<sup data-n=\"4871\">70</sup> כי השכל הוא מאיר שע\"י יוכל לראות דבר הנעלם דהיינו מה שעתיד להיות כמו איזהו חכם הרואה את הנולד<sup data-n=\"4872\">71</sup> ולהיפך הכסיל בחושך הולך<sup data-n=\"4873\">72</sup> ולכן נק' השכל בשם אור כי כשנמשך בכלי המוח הוא מאיר כל דבר נעלם כמו כשמכניסין נר בבית שרואה ע\"י כל שבבית שהי' מתחילה בהעלם בעת החושך, ונמצא שעצם השכל הוא כח הרוחני המשכלל<sup data-n=\"4874\">73</sup> כל שכל שיש בו בהירות בעצם להשכיל השכלות שונות, ומה שמאיר אור שמש<sup data-n=\"4875\">74</sup> פרטי זהו זיוו בלבד.\n<b>והנה</b> עם הנ\"ל יובן ענין בחי' אחרונה דאא\"ס כי הנה אנו אומרים אתה קדוש ושמך קדוש<sup data-n=\"4876\">75</sup> פי' לפי שאתה קדוש בעצם ומובדל מגדר המשכה פרטי' ואפי' מגדר ומקור למקור להמשכה פרטי' או כללי' כמשי\"ת לכן שמך קדוש כי אין שם אחר שיכיליהו, כי א\"א לקרותו חכים כיון שאינו מקור לחכ' בלבד, וגם א\"א לקרותו בשם כללי המכיל לכל ע\"ס כי אינו מקור בלבד לע\"ס רק מצדו הי' ביכולתו להאציל ריבוא רבבות ספי'<sup data-n=\"4877\">76</sup> ועולמות לאין קץ, ומה שלא האציל רק מספר ע\"ס בד' עולמות היינו מצד שעלה ברצונו כך ולא מצד העדר היכולת ח\"ו כו', לכן כשאנו שואלים מהות א\"ס מהו לא נוכל לו' רק שהוא קדוש ובשם אחר לא נוכל לקרותו כו' [ולכן כינו לו חז\"ל בשם הקב\"ה<sup data-n=\"4878\">77</sup> ], רק שאעפ\"י שהוא קדוש בעצם אין הכוונה שהוא מושלל מגדר השפעה עד שלא יוכל להיות ממנו השפעה וגילוי כלל [כי זהו דעת אוה\"ע אשר לא יבינו פעולת הוי' ולכן הוא מרומם אצלם מגדר גילוי וכמ\"ש רם על כל גוים הוי'<sup data-n=\"4879\">78</sup>, ואפי' אומות האחרונים ששבו והאמינו בחידוש העולם אינם מאמינים רק בהתהוות ממנו עולם שזה נק' השפעה מרחוק אבל אינם מאמינים בבחי' הגילוי שהוא ההתגלות שלו בעולם, ואפי' חסידי אוה\"ע המאמינים בגילוי שלו בעולם היינו גילוי מציאותו בלבד עד שמצד זה נמצא בהם הביטול מצד השכל אבל מהותו הוא מרומם ומובדל אצלם עד שלא יתכן בו הגילוי, זולת לעם ה' המאמינים בתו' ומצות שהמה למעלה באצי' כלים רוחני' [כי כל התומ\"צ נכללי' בע\"ס דאצי' כו'] המכלים<sup data-n=\"4880\">79</sup>",[["4871","70","<b>מאיר עיני חכמים</b>: ערובין יג, ב."],["4872","71","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א."],["4873","72","<b>הכסיל בחושך הולך</b>: קהלת ב, יד."],["4874","73","<b>המשכלל</b>: אוצ\"ל: המשכיל."],["4875","74","<b>שמש</b>: אוצ\"ל: שכל."],["4876","75","<b>אתה קדוש ושמך קדוש</b>: נוסח תפלת העמידה."],["4877","76","<b>להאציל ריבוא רבבות ספי'</b>: ראה גם לקמן מאמר ד\"ה להבין וכו' ונתתי משכני על יד הערה 36. מאמרי אדה\"א קונטרסים ע' ו. וש\"נ. ש\"א פב, ב ובהערה 12. תו\"ח בשלח ח\"א רכב, ד. אוה\"ת שה\"ש כרך ג ע' תתקסה ואילך. סה\"מ תש\"י ע' 132. מאמר ד\"ה והי' זרעך (יו\"ד כסליו) וד\"ה באתי לגני (יו\"ד שבט) תשכ\"ב. ד\"ה אתה הראת תשל\"ז פ\"ו [קונט' שמע\"צ ושמח\"ת תש\"נ — סה\"מ מלוקט ד ע' לז]. וראה גם מאה קשיטה — להרמ\"ע מפאנו — ס\"ה (ג, ד)."],["4878","77","<b>כינוי לו חז\"ל בשם הקב\"ה</b>: ראה ברכות ג, א. ב. בסמוך בפנים. תו\"ח תרומה ח\"ב שיז, ב ואילך. וש\"נ. וראה גם לעיל מאמר ד\"ה את שבתותי תרי\"ב ע' תז ואילך. וראה גם תו\"ח בא ח\"א קכב, ב."],["4879","78","<b>רם על כל גוים הוי'</b>: תהלים קיג, ד. ראה תו\"א מקץ לד, ד ואילך. סידור תפלת ר\"ה רלז, סע\"ב ואילך. מאמרי אדה\"א דברים ח\"ג ס\"ע א'לג ואילך וש\"נ. סהמ\"צ להצ\"צ ע' קנב."],["4880","79","<b>המכלים</b>: כנצ\"ל: המכילים."]]],[4801940545,"פנימי' ועצמו' אא\"ס להביאו לידי גילוי בעולמות בי\"ע בדרך מעבר, ועיקר הקביעות של דירה שלו הוא למטה בנפש שבגוף ע\"י כלי המצוות בגשמי' ועי\"ז נמשך בחי' הביטול בנפשם בקביעות לעצמו' ומהות אא\"ס שלמעלה מהשתלשלות לגמרי וכענין אנכי<sup data-n=\"4881\">80</sup> כו' ועיין בשער חג המצות<sup data-n=\"4882\">81</sup>, ולזה אנו קורים בשם גילוי אמיתי, ואפי' גילוי כזה אינו מושלל ממנו ויוכל להתגלות כמ\"ש בנשמות המוגבלים מאין ליש בגופים גשמי' שזה מורה על עומק יכולתו שהוא בבחי' א\"ס פי' שיוכל להתגלות בבחי' א\"ס ובמוגבל דייקא כו' וד\"ל] רק אדרבה מצד שהוא קדוש בעצם יוכל להתהוות ממנו כל מיני גילוי אפי' גילוי עצמו' בעולמות וכנ\"ל [כי השלילה מדבר מורה על גדרי<sup data-n=\"4883\">82</sup> ולכן הוא מושלל מדבר אחר אבל כיון שהוא קדוש בעצם ואינו בסוג וגדר כלל אינו מושלל משום דבר ויוכל להתהוות ממנו כל מיני השפעות וגילוי'].\n<b>וזהו</b> מש\"א וכל מאמיני' שהוא כל יכול<sup data-n=\"4884\">83</sup> וכמ\"ש<sup data-n=\"4885\">84</sup> לבדו הוא, כי הא בהא תליא מחמת שהוא לבדו לכן הוא כל יכול, וכענין מי כה' אלקינו המגביהי לשבת המשפילי<sup data-n=\"4886\">85</sup> כו'. והנה ב' בחי' אלו נק' בשם אור העצמי' וזיו העצם שהוא מה שביכולת אור העצמי להתגלות בהשתלשלות [שזה נק' זיו] וזהו המורה על קדושתו ביותר עד שאינו בסוג וגדר כלל ולכן יכול להיות נמצא ממנו הכל ומהות א\"ס הנושא וסובל ב' גילוי' אלו עד שאינם הפכיים בו כלל [ואין הכוונה שאינם הפכיי' רק מתאחדי', אלא שהמה דבר אחד ממש שהוא קדושתו העצמי, רק בבחי' הגילוי נבחן לשני בחי' במקבלי' כו' וד\"ל]. וזהו ענין שם הקב\"ה שקראו לו חז\"ל, כי קדוש הוא אורו העצמי וברוך הוא בחי' הזיו שבאור שהוא מה שביכולתו להתגלות כנ\"ל והוא הוא מציאות המאור הנושא וסובל שני גילויי' אלו שהמה בו גילוי'<sup data-n=\"4887\">86</sup> א' ממש וכנ\"ל וד\"ל]. וזהו מה שקראו המקובלים בחי' אחרונה דא\"ס שהוא כח ההתגלות שלו שאינו שייך לעצמו וע\"ד שם האדם כו' וזהו נק' מל' דא\"ס, ואוא\"ס הוא גילוי של העצמי' הנק' מאור [רק שבכאן הוא שם א\"ס בדרך השאלה בעלמא מצד שא\"א לקרותו באופן אחר אבל באמת לא יתכן בכאן שם א\"ס רק בבחי' הרשימו שאחר הצמצום וכמשי\"ת כו'].\n<b>ומעתה</b> יש להבין ענין הרשימו שנשאר אחר הצמצום שזהו בבחי' אחרונה דייקא וכמ\"ש המקובלים ונק' טה\"ע, וביאור הדברים יובן ע\"פ משל מהשפעת שכל הרב לתלמידו<sup data-n=\"4888\">87</sup> שבתחילה מוכרח שיתעורר בעצמו לבוא לכלל גילוי שפע במקבל במה שיפיע<sup data-n=\"4889\">88</sup> שכלו העמוק אלי', והתעוררות זאת נק' בשם רצון להשפיע,",[["4881","80","<b>אנכי</b>: יתרו כ, ב. ראה לעיל מאמר ד\"ה את שבתותי תקצ\"ח הערה 92."],["4882","81","<b>בשער חג המצות</b>: בסידור רפד, ג ואילך."],["4883","82","<b>גדרי</b>: אוצ\"ל: גדרו."],["4884","83","<b>וכל מאמיני' שהוא כל יכול</b>: חרוז בפיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["4885","84","<b>וכמ\"ש</b>: וכל מאמינים שהוא."],["4886","85","<b>מי. . המגביהי לשבת המשפילי</b>: תהלים קיג, ה. ו. ראה גם סידור שער תפלת ר\"ה רלז, ג. מאמרי אדה\"א דברים ח\"ג ר\"ע א'לה. תו\"ח ויחי רמד, סע\"ד, ואילך."],["4887","86","<b>גילוי'</b>: כנצ\"ל: גילוי."],["4888","87","<b>משל מהשפעת שכל הרב לתלמידו</b>: ראה גם פלח הרמון בשלח ע' קצו."],["4889","88","<b>שיפיע</b>: כנצ\"ל: שישפיע."]]],[4801940567,"וענין הרצון הזה הוא גילוי כח ההתפשטות שבשכל, והיינו מה שבטבע כל בר שכל וביכולתו להסביר שכלו לזולתו שזהו זיו שבאור השכל שדומה לאור העצמי שלו, כי כל כח שכלו יוכל להביאו לידי גילוי רק שכח ההתפשטות הוא בטל ונכלל בעצם האור של השכל, וכאן בא לידי גילוי מצד כשרון כלי המקבל הפועל נתינת עצמותו בהתפשטות דייקא, והוא הנותן כח בהתפשטות להיות נגלה היפך טבעה ליבטל וליכלל באור העצמי' כו'. וסיבת התעוררות הזה שהוא פניי'<sup data-n=\"4890\">89</sup> וסיבת הרצון הוא כשרון כלי המקבל, דהיינו מצד שמרגיש כלי המקבל שהוא כלי מוכן לקבל כל כח שכלו ונמצא שהוא ממצה כח עצמו במקבל, ומחמת זה יוכשר המקבל אצלו מאד עד שהוא מתקשר בעצמותו, וקשר זה נק' יחוד עצם המקבל עם עצם המשפיע בדרך עלי' [פי' במקום המשפיע כו'], וקשר ויחוד זה הוא מביא התעוררות של המשפיע ברצון להשפיע בכדי שיהי' נגלה יחוד וקשר זה של עצם המשפיע בעצם המקבל במקום המקבל כו'. ונמצא יש כאן ב' בחי', חיצוני' הרצון שהוא מקור האמיתי של ההשפעה כמשי\"ת, ופנימי' הרצון שהוא הסיבה לחיצוני' הרצון שאינו רצון להשפעה כלל רק להתייחד עם המקבל כו'.\n<b>והנה</b> הרצון להשפיע אע\"פ שהוא המקור להשפיע מ\"מ עדיין אינו מוגבל בו איכות ההשפעה ואופנה איך תהי', ויוכל להיות אופן סדר השפע בכמה אופנים שונים, ולכן צ\"ל עוד התעוררות חדשה בעצם המשפיע להביא הרצון לידי פ\"מ שזה לא יוכל להיות אם לא ע\"י הגבלתו באופן א' בלבד ובאופן אחר לא תוכל להתקבל השפע, והתעוררות זאת פועלת העלם כל כח גילוי אור שכלו כמ\"ש לעצמו עד שלא יתגלה רק נקודה פרטית לצורך השפעות המקבל, ופי' נקודה פרטי' אין הכוונה שכל הפרטים נעדרים ממנה, רק שהמה נמצאי' כולם בהעלם בנקודה פרטי' הזאת. ונמצא מה שאנו קורי' לה נקודה פרטי' הוא רק ע\"ש גילוי' באופן פרטי אבל באמת נכלל בהעלם נקודה זאת כל הרחבת אור שכל הרב כמ\"ש אצלו ממש ולא יחסר דבר ולא חצי דבר כלל וע\"ד דוגמא כמו ששנו חכמים בלשון המשנה<sup data-n=\"4891\">90</sup> שלא נחסר מקיצור המשנה כל האריכות שבתלמוד כו' וד\"ל [יעויין בבז\"ק פ' אחרי<sup data-n=\"4892\">91</sup> ]. ונמצא שיש כאן שני בחי', הא' בחי' גילוי האור של השכל שיש בו העלם וגילוי, דהיינו שנתעלם כל האור של הרחבת השכל עד שלא נגלה רק אופן פרטי [וזהו ענין קוש\"י ויוד עצמה וכמבואר בשם הרה\"מ נ\"ע<sup data-n=\"4893\">92</sup> שיש שם הוי' בהשפעת הרב לתלמיד כו' וד\"ל], והב' עצם השכל המתעלם באופן פרטי הזה שהוא עצמות השכל שנתעלם בהעלם אחר העלם הוא הוא עצמו הנגלה בנקודה להיות מקור לשפע דייקא ונמצא שעצם השכל הנמשך הוא הכולל העלם וגילוי כא' כו' וד\"ל.",[["4890","89","<b>פניי'</b>: תיבה זו איננה ברורה. ואצ\"ל: פנימי'."],["4891","90","<b>ששנו חכמים בלשון המשנה</b>: ע\"פ אבות רפ\"ו. ראה הקדמת הרמב\"ם לפיה\"מ ד\"ה אחר כן ראה."],["4892","91","<b>בבז\"ק פ' אחרי</b>: [ בביאור זהר הקדוש] ביאוה\"ז עו, ד. ראה גם שה\"א יד, ב. מאמרי אדה\"א הנחות תקע\"ז ע' קמג. וש\"נ. תו\"ח ויקהל ח\"ב תכד, א. המשך תרס\"ו ע' תא."],["4893","92","<b>בשם הרה\"מ נ\"ע</b>: מובא גם בפלח הרמון שם. ראה לק\"א — להה\"מ — סקס\"ו. או\"ת ר\"פ בלק."]]],[4801940582,"<b>והנה</b> אחר המדידה של צורך השפעת המקבל כשמתחיל להשפיע צריך מתחילה לסדר במחשבתו איך להרחיב נקודה זאת בכמה אופנים והסברים שונים כי בלעדי ההסבר לא יוכל לגלות תמצית הנקודה הנמדדת לצורך המקבל, כי כל מתמצית<sup data-n=\"4894\">93</sup> לא יוכל להתגלות בדיבור רק ע\"י ההסבר נתגלה אח\"כ תמצית השפע [לאחר מ' שנין דקאי' אדעתי' דרבי' כו'], ונמצא שזה נק' ה' ראשונה דשם הוי' והיוד כלול בה בהעלם בסוד וחכם בבינה<sup data-n=\"4895\">94</sup> והיינו תמצית המכוון כמ\"ש מלובש בכל פרטי ההסבר, אבל עצם החכ' שלמע' מבחי' בינה היינו בחי' תמצית השפע הנמדדת מתחי' לצורך השפעת המקבל בלתי התלבשות באו\"ר<sup data-n=\"4896\">95</sup> כו' וד\"ל, ואח\"כ כשמשפיע בקול ודיבור בפ\"מ זהו בחי' ו\"ה דשם הוי' כו' וד\"ל.\n<b>והנמשל</b> מכל הנ\"ל יובן למעלה כללי' סדר ההשתלשלות בדרך קצרה מראשית עליות הרצה\"פ בעצמו' אא\"ס עד סופא דכל דרגין שזהו במל'<sup data-n=\"4897\">96</sup> דאצילות בבי\"ע התהוות מאין ליש בפ\"מ ויובן מאמר הזה\"ק הנ\"ל דהנה מה שא' בריש הורמנותא דמלכא הנה מלכא הוא בחי' מדת המל' דאצילות אשר אין מלך בלא עם<sup data-n=\"4898\">97</sup> דייקא ובחי' עם היינו כאשר המה נפרדים ורחוקי' ממעלת המלך ואעפ\"כ המה בטלים כמו העבדים ע\"ז יתפשט דייקא מדת המלוכה ולא על בנים<sup data-n=\"4899\">98</sup> המתאחדים עמו ואפי' על שרים לא יתכן כ\"כ מדת המלוכה רק עיקר מדת המלוכה היא על עבדים הנק'<sup data-n=\"4900\">99</sup> דייקא, וכך הוא למע' מדת המלוכה עליונה אינו שייך כ\"א כאשר יתהווה הנבראים מאין ליש שהמה נפרדים לגמרי מאלקות וגם בהם יתפשט בחי' הביטול זהו עיקר מדת המלוכה, אשר לזה הי' הכוונה ורצה\"פ מתחילה דייקא שהוא לבחי' המל' סופא דכל דרגין ונק' מח' דאנא אמלוך<sup data-n=\"4901\">100</sup> כו' וזהו סוף מע' עלה במח' תחילה<sup data-n=\"4902\">101</sup> כו'. וזהו ג\"כ ל' המקובלים כשעלה ברצה\"פ להטיב לברואי'<sup data-n=\"4903\">102</sup> דייקא שיכירו גדולתו ויזכו להיות מרכבה להדבק בו ית' שזהו ענין הביטול בנבראים דייקא הנק' מרכבה שזה הי' תכלית הכוונה הנעלמה ברצה\"פ, וזהו בריש הורמנותא דמלכא דהיינו בראשית עליות הרצה\"פ בעצמו' הנק' הורמנותא דמלכא פי' שעיקר הרצון הוא למלוכה כו'.\n<b>והנה</b> ברצון הזה נעשה שרש ומקור לבחי' המל' סופא דכל דרגין שתהי' נמשכת מאין ליש בבי\"ע בשתי בחי' הא' להוות מאין ליש בבחי' נפרד [כי בזה אין",[["4894","93","<b>כל מתמצית</b>: כ\"ה בהכת\"י."],["4895","94","<b>וחכם בבינה</b>: ס\"י פ\"א, מ\"ד."],["4896","95","<b>באו\"ר</b>: באורך ורוחב."],["4897","96","<b>סופא דכל דרגין שזהו במל'</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["4898","97","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["4899","98","<b>העבדים. . מדת המלוכה ולא על בנים</b>: ראה שער היחוד והאמונה רפ\"ז."],["4900","99","<b>הנק'</b>: כ\"ה בהכת\"י. ואולי מיותר."],["4901","100","<b>מח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["4902","101","<b>סוף מע' עלה במח' תחילה</b>: ע\"פ פיוט לכה דודי."],["4903","102","<b>כשעלה ברצה\"פ להטיב לברואי'</b>: ראה ע\"ח שער הכללים בתחילתו. לעיל ע' לה הערות 62-3."]]],[4801940593,"הנמשל דומה למשל דמדת המלוכה למטה שהעבדים המה נתהווים מאנשים אחרים שהולידו אותם אבל למע' מדת המלוכה הוא מקור להתהוותם מאין ליש כו'], והב' בחי' הביטול הנמשך בהם מצד מדת המלוכה שזהו מיש שלהם לאין. והנה שני בחי' ההמשכה הנ\"ל דמדת המלוכה לכ\"ז<sup data-n=\"4904\">103</sup> נעשה שרש ומקור ברצה\"פ הנ\"ל, כי כאשר עלה במח' וכוונה הנ\"ל להיות מלך על עם שזהו הביטול דנפרדים דייקא בזה נעשה מקור להתהוות שלהם בבחי' הפירוד ושיהי' בטלים מבחי' הפירוד ונכללי' באלקות כו', וזהו שתי בחי' סתי' דאורייתא וסתים דישראל ירידה ועלי' חו\"ג בעצמו' רצה\"פ, והנה כוונה ורצון הנ\"ל נק' צמצום ופי' צמצום אין הכוונה הסתלקות והעדר ח\"ו רק הוא ע\"ד צמצם שכינתו<sup data-n=\"4905\">104</sup> כו' היינו להיות כל עצמותו שורה במקדש הוי' שהוא הביטול דנבראים, וזהו ג\"כ ענין הכוונה שהוא נתינת עצמות המשפיע להיות נמצא בסומ\"ע כו', והנה מחמת זה הצמצום נשאר בחי' הרשימו.\n<b>ויובן</b> ע\"ד הנ\"ל במשל הרב לתלמיד שנעשה רצון להשפיע מצד כשרון כלי המקבל שענינו הוא גילוי כח ההתפשטות של השפע הנק' זיו של השכל שמתחילה לא הי' בסוג וגדר התפשטות כלל מצד ביטולו בעצם אור השכל, כך יובן למעלה שצמצום הזה הוא ירידת ונתינת עצם המאור שמחמת זה ניתן כח כביכול בבחי' יכולתו לבוא לידי גילוי והתפשטות הי' נכלל כח ויכולת הנ\"ל בבחי' אור העצמי שהוא ענין התכללות הזיו בעצם האור כו' וזהו ענין השארת הרשימו שבכאן נדרש שם א\"ס באמת [כידוע בשם הרה\"מ ז\"ל נ\"ע לתרץ קושי' המקובלי' למה לא נק' בשם אין תחילה<sup data-n=\"4906\">105</sup> ותירץ כי באמת על העצם לא שייך לומר לא אין תחילה ולא א\"ס, כיון שאינו מגדר וסוג התפשטות כלל כי ל' תחילה וסוף לא יפול רק על דבר שהוא בגדר התפשטות רק על בחי' מל' דא\"ס יתכן לו' שם א\"ס להיות כי בחי' המל' היא בחי' כח ההתפשטות רק שא\"ס להתפשטותו כו' וד\"ל, ולא יתכן לו' אין תחילה כי התחילה התהוותו מן העצמו' כו' וד\"ל. והנה כוונתו אפשר הוא על מל' דא\"ס אחר הצמצום שהוא ענין הרשימו הנ\"ל, אבל בחי' מל' דא\"ס שקודם הצמצום הנק' מדרי' אחרונה שבאא\"ס שהוא בחי' הזיו אינו שייך עדיין לו' שם א\"ס כיון שאינו בגדר התפשטות עדיין מצד ביטולו בעצם האור וכנ\"ל וד\"ל].\n<b>והנה</b> מצד הרשימו הנ\"ל לא הי' יכול להיות נמשך בחי' עולמות כמ\"ש עכשיו בבחי' מספר ובבחי' גבול והכוונה הי' שיהי' נמצא ונמשך בחי' הביטול דא\"ס בנשמות שבגופים המוגבלים מאין ליש ובבחי' מספר [והיינו שיהי' נמצא כח הבב\"ג בבחי' הגבול ע\"י ביטולו לבחי' בב\"ג כו'] ולזה הי' צריך להיות העולמות כולם הממוצעי' ג\"כ בבחי' המספר שזהו עשר ספירות עשר ולא תשע<sup data-n=\"4907\">106</sup> כו' וגם",[["4904","103","<b>לכ\"ז</b>: לכל זה."],["4905","104","<b>צמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12. לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 18."],["4906","105","<b>בשם הרה\"מ. . אין תחילה</b>: ראה לעיל בהביאור על מאמר ד\"ה את שבתותי תשמרו תרי\"ב ובהערה 11."],["4907","106","<b>עשר ולא תשע</b>: ס\"י פ\"א, מ\"ג מהדורת מנטובא שכ\"ב."]]],[4801940600,"המה בבחי' כחות מוגבלי' [פי' שהמה עושים הגבול בבי\"ע אבל לא ח\"ו שהמה בבחי' גבול בעצם כו'], אשר לזאת נתברר כח הרשימו הנ\"ל ונמדד על איזה אופן שיהי' גילוי' באופן מוגבל דייקא, וזהו ענין גליף גליפו שהוא ענין פנימי' הכתר וחיצוניותו, ופנימי' הכתר הוא הא\"ס פי' העלם כל עצם כח הא\"ס להיות נתפס בהעלם ולא בגילוי, ומה שנגלה כחו העצמי להמצא באופן מוגבל זהו חיצוניותו ונק' חכ' שבכתר בחי' בוצינא דקרדוניתא קו המדה<sup data-n=\"4908\">107</sup> כו' וזהו שרש וראש לנאצלים כו' [והוא ע\"ד הנ\"ל במשל הב' ענין העלם אור השכל להיות נמצא צורך השפעת המקבל, ובמשל הא' הוא בחי' שרש אותיות המח' ואותיות הדיבור כמ\"ש חקוקי' בעצם הנפש והיינו אופן הציור בנפש על איזה אופן יהי' נמשך ונתגלה בגוף שמוכרח להיות ע\"י העלם כל אור הנפש [כי מצד עצם התפשטותו יכול להחיות כמה גופים באופנים אחרים כו' וד\"ל] ולהתגלות באופן פרטי שזהו נמשך מצד הרגשת הנפש שלימות ותועלת שיקבל מירידתו בגוף דייקא שזהו המביאו לידי התפשטות אור שזהו ענין שתי הנקודות דקמץ ופתח כו' וד\"ל. ..].\n<b>והנה</b> שתי החקיקות הנ\"ל שנק' גליף גליפו נק' אותיות החקוקי' כי אפי' בחי' חיצוני' הכתר הנק' חכ' שבכתר היינו מה שנמדד כח העצם על איזה אופן יתגלה, אך מה שבא אח\"כ לידי גילוי בחכ' ובינה להיות נק' חכים ומבין שזהו להעשות מקור לנבראי' כו' וכמאמר אנת הוא דאפיקת<sup data-n=\"4909\">108</sup> עשר תיקונין זהו בחי' אותיות הכתובים ונק' ס\"ת כי תורה הוא בחי' חכ' וספר הוא בחי' התגלות החכ' בבינה שזהו יחוד חו\"ב שנמשך מבחי' הכתר ע\"י שערות וזהו הכל תלוי במזל<sup data-n=\"4910\">109</sup> כו'. והנה מבחי' חו\"ב הנ\"ל לא הי' יכול עדיין להתהוות השתלשלות עד שנתצמצם מחו\"ב למדו' דייקא וכמאמר ששת ימים עשה ה'<sup data-n=\"4911\">110</sup> שית יומין עילאין דבהון דייקא עביד קוב\"ה שמיא וארעא. והנה ע\"ס דאצילות המה כמשל אותיות הכתובים שהמה נבדלי' ומתאחדי', כך למעל' ע\"ס דאצילות המה בריחוק נבדל מן העצמו' ובבחי' דילוג הערך לגבי עצמו' רק אעפי\"כ מתאחד כח העצמו' בהם בתכלי' להוות ע\"י נבראי' מאין ליש [יעוין באגה\"ק בענין איהו וחיוהי<sup data-n=\"4912\">111</sup> כי הוא לבדו כל יכול להוות בחי' יש מאין ואפס המוחלט בלתי עילה אחרת קודמת ליש הזה כו'], וזהו מ\"ש הרמב\"ם הוא היודע והוא המדע<sup data-n=\"4913\">112</sup> כו', וזהו ענין יחיד ואחד כי יחיד הוא בבחי' הכתר ואחד הוא בע\"ס דאצי' מחכ' ולמטה וכנ\"ל [... ולכן נמשלים ג\"כ לבחי' אותיו' השכל והמדות שיש בהם צד חקיקה מצד חיות הנפש הנמשך בהם רק למע'<sup data-n=\"4914\">113</sup> בבחי'",[["4908","107","<b>בוצינא דקרדוניתא קו המדה</b>: ראה זהר בראשית טו, א [ובמפרשים שם]. תו\"א מקץ לט, א. שמות קז, ד. מאמרי אדה\"א נ\"ך ע' עא. וש\"נ. אוה\"ת שלח ע' תצג ואילך."],["4909","108","<b>אנת הוא דאפיקת</b>: ת\"ז בהקדמה יז, א (סידור אדה\"ז סדר מנחת ערב שבת)."],["4910","109","<b>הכל תלוי במזל</b>: ראה זהר אד\"ר נשא קלד, א. דברים נחמדים ממהר\"ם שיף בתחלתן [נדפסו בסוף מס' חולין]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קכז ובהנסמן במ\"מ לשם."],["4911","110","<b>ששת ימים עשה ה'</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["4912","111","<b>באגה\"ק בענין איהו וחיוהי</b>: אגה\"ק ס\"כ קל, רע\"ב."],["4913","112","<b>הוא היודע והוא המדע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י."],["4914","113","<b>למע'</b>: תיבה זו איננה ברורה."]]],[4801940606,"אא\"ס המתצמצם בע\"ס דאצי' נאמר איהו וחיוהי וגרמוהי חד<sup data-n=\"4915\">114</sup> בתכלית אבל לא למע' מהאצי' יעויין בלק\"א בהג\"ה פ\"ב. ..].\n<b>והנה</b> מצד המדות דאצי' ג\"כ לא הי' יכול להיות נמשך ההשתלשלות בבחי' הפירוד אעפ\"י שהמה כח האמיתי דהשתלשלות, לכן נמשך אא\"ס ונתלבש בבחי' לבוש המל' בכדי להוות מאין ליש בבחי' נפרד [וג' לבושים<sup data-n=\"4916\">*115</sup> המל' היינו אותיות מח' ואותיות הדיבור ואותיות המעשה מקור עלמין סתימין ועלמין דאתגליין שהוא בריאה ויצי' ועשי' כו']. [... ובזה יובן ענין ששה מדרי' דתו' כי בחי' סתים דחכ' דתורה הוא בחי' הצמצום שהוא ענין עליות הרצה\"פ הנק' הורמניתא דמלכא בחי' כוונה נעלמה דהשתלשלות ובמשל המשכות חיות הנפש בגוף הוא בחי' נקודת קמץ החקוק בנפש ובמשל דרב לתלמיד הוא בחי' עליות כשרון כלי המקבל שגורם ירידת עצמו' שכל הרב ברצון להשפיע כו', ובחי' גליא דתורה הוא בחי' הרשימו שנגלה אחר הצמצום שהוא גילוי כח ההתפשטות דא\"ס הנק' מל' דא\"ס והוא נק' טה\"ע בלשון הזהר ובמשל המשכת חיות הנפש בגוף הוא בחי' נקודת הפתח שבנפש ובמשל הרב לתלמיד הוא בחי' רצון להשפיע שנגלה מצד עליות כשרון כלי המקבל כו', ובחי' שתי לוחות שבתו' שזהו ענין ירידת חכ' שבתורה בבחי' אותיו' רק שהמה אותיות חקוקי' עדיין שזהו מה שנמדד כח ההתפשטות דא\"ס להיות נמשך באופן פרטי דעשר ולא תשע וזהו מוכרח להיות ע\"י העלם וגילוי וכנ\"ל באריכות, שזהו ענין פנימי' הכתר וחיצוני' שבו ונק' גליף גליפו בל' הזהר וע\"ש דוגמא במשל חיות הנפש בגוף הוא ענין שרש אותיו' המח' ושרש אותיות הדיבור כמו שהמה חקוקי' בנפש שזהו מה שנמדד בעצמי' הנפש על איזה אופן יחי' בגוף זה וכנ\"ל ובמשל הרב לתלמיד הוא מה שמוצא נקודה פרטי' בשכלו צורך השפע' המקבל שיש בזה שתי' בחי' העלם וגילוי וכנ\"ל כו'.\n<b>וזהו</b> ענין שתי לוחות שזהו ענין ירידת אא\"ס בפנימי' הכתר וחיצוניותו ואח\"כ אותיות הכתובים דתו' שזהו ענין ירידת אא\"ס בבחי' חכ' הגלוי' ובינה ואח\"כ הירידה במדות הוא ענין תושבע\"פ שזהו גמר המשכת מקור התהוות העולמות, וכענין הנאמר בשם הרה\"מ נ\"ע דברו חכמים בהוה<sup data-n=\"4917\">115</sup> שמה שדברו במציאות הנבראי' בתושבע\"פ כמו החיטי' והזוני'<sup data-n=\"4918\">116</sup> כו' זהו עיקר התהוותן וע\"ד דוגמא במשל חיות הנפש בגוף הוא בחי' אותיות עצמי' דשכל ומדות ובמשל הרב לתלמיד הוא כאשר נתרחב ונתחלק נקודה פרטי' שהיא צורך השפעת המקבל בפרטי' שוני' בהסברי' ומשלים שוני' שמזה נעשה ונמשך עיקר השפע למקבל בקול ודיבור כנ\"ל ואח\"כ",[["4915","114","<b>איהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["4916","*115","<b>לבושים</b>: אוצ\"ל: לבושי."],["4917","115","<b>בשם הרה\"מ נ\"ע דברו חכמים בהוה</b>: משנה שבת סה, א סו, ב. ראה גם לקו\"ת שמע\"צ פו, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקפא (נו\"א). ס\"ע תתקפב ואילך (נו\"ש). סידור שער הק\"ש פז, ד. סהמ\"צ להצ\"צ נח, ב. מאמרי אדה\"א בראשית ע' תטו. שמות ח\"א ע' קע. ויקרא ח\"ב ע' תרלג. אוה\"ת במדבר ע' סט. תבוא ע' תתרמט. ישעי' כרך א ע' רכג. סה\"מ תרכ\"ז ע' שצג. תרל\"ב ח\"א ע' קעב. תער\"ב ח\"א ע' יד. ע' שמה. [ובכל הנ\"ל לא נזכר שמו של הה\"מ]."],["4918","116","<b>החיטי' והזוני'</b>: כלאים רפ\"א."]]],[4801940612,"אותיו' המח' ודיבור דמל' שזהו למטה מבחי' התו' רק מקור ההשתלשלות דבחי' הפירוד שלהם וזהו ענין ב' מיני מאמר מאמר סתום ומאמר פתוח<sup data-n=\"4919\">117</sup> וע\"ד דוגמא בנפש אותיו' הכתובים דחומר המח' והדיבור ובמשל הרב לתלמיד הוא השפעתו בקול ודיבור כו' וד\"ל. ..]. והנה כ\"ז הוא ירידת והמשכת אא\"ס ממדריגה למדריגה מראשית עלי' הרצה\"פ עד סופא דכל דרגין במל' דאצי' שזהו ענין חיבור סתים וגליא דקוב\"ה בדרך ירידה והעלם שהוא ענין בחי' הא' במל' להתהוות הנבראים בבחי' גילוי ופירוד שזהו ע\"י עד אחד דתורה בלבד הנק' תורת חסד כו' אך פנימי' הכוונה הי' שיהי' ביטול הנבראים מיש לאין ושיהי' ביטולם לבחי' העצמו' דייקא שזהו ענין נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"4920\">118</sup> לו בעצמו שזהו דייקא ע\"י שנים עדים שהמה י\"ש<sup data-n=\"4921\">119</sup> שמקיימין את התו' שמזה נעשה בחי' השני' דמדת המל' שהוא התפשטות לעשות ביטול הנבראים שזהו ע\"ד מדת המלוכה למטה וכנ\"ל.\n<b>והנה</b> בחי' ישראל שמקיימין התורה יש בהם ג\"כ שתי מדריגות דסתים וגליא בד\"כ, ובחי' סתים שבהם הוא מה שבכח כאו\"א מישראל להיות בטל לבחי' אא\"ס למע' מן הטעם ודעת לגמרי שזהו מצד שרשם בבחי' מדות שבכתר הנק' טורי חשוכא שלמע' מחכ' דאצילות עד\"מ הרים הגבוהים שאין אור השמש מאיר עליהם, ובחי' גליא שבהם הוא מה שיש בחוש הנפש שלהם להרגיש ביטול לאלקים חיים מצד הטעם ודעת שזהו מצד שרשם במדות דאצילות הנק' טורי נהורא<sup data-n=\"4922\">120</sup> שלמטה מחכ' כו'. וזהו מש\"א כה א' ה' בעבר הנהר<sup data-n=\"4923\">121</sup> ישבו אבותיכם וא' בזהר שם ההוא נהר דאשתמודע פי' שהוא בחי' בינה דאצי' והודיעם שרש נשמותיהם שהוא למע' מנהר דבינה<sup data-n=\"4924\">122</sup> מבחי' הכתר בבחי' המדות שבו הנק' טורי חשוכא וכנ\"ל וד\"ל [... וזהו עד השני דישראל שהמה בחי' גבו' והעלאה מלמטה למע' שהמה הגורמים ביטול דעולמו' מיש לאין עד אין האמיתי, וכ\"ז מצד שיש בהם משני הבחי' ביחד שהוא סתים שבהם שרשם בסתים דקוב\"ה וגליא שבהם מלובש בחיצוני' העולמו' הנק' גליא דקוב\"ה וכ\"ז ע\"י ביטולם לרצה\"ע המלובש בתורה דייקא, וזהו עפ\"י שניים עדים שהמה ממוצעי' לחבר סתים וגליא בבחי' גילוי ולא בהעלם כמו ע\"י ע\"א דתורה בלבד כו' וד\"ל.\n<b>אך</b> להבין בתוס' ביאור יש להבין ענין ששה מדריגו' בפרט בישראל ג\"כ כנ\"ל מצד שהמה מושרשים בתורה. ויש להקדים ענין ואהבת את ה' אלקיך בכל לבבך<sup data-n=\"4925\">123</sup> כו' כי הנה באה' דבכל לבבך יש שני מדריגות הא' בחי' לבבך והיינו מה",[["4919","117","<b>מאמר סתום ומאמר פתוח</b>: ראה מאמרי אדה\"ז תקס\"ט ע' קפד. מאמרי אדה\"א שמות ח\"א ע' ריג. וש\"נ. תו\"ח שמות ח\"א יב, ב ובהערה 543."],["4920","118","<b>נתאוה. . דירה בתחתונים</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. לקמן פיסקא אך הנה ידוע. סה\"מ תרל\"ח ע' לט הערה 138."],["4921","119","<b>י\"ש</b>: ישראל."],["4922","120","<b>טורי חשוכא. . טורי נהורא</b>: זהר פינחס כאן רמט, ב. ראה גם לעיל ע' קד ובהערה 42."],["4923","121","<b>כה א' ה' בעבר הנהר</b>: יהושע כד, ב [בדילוג]. זהר אמור צט, א."],["4924","122","<b>מנהר דבינה</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["4925","123","<b>ואהבת. . בכל לבבך</b>: ואתחנן ו, ה."]]],[4801940617,"שנתפעל בלבו מצד ההתבוננות שמתבונן באיכות גדולת והתפשטות אלקות להחיות עולמות לאין שיעור וכל ריבוי עולמות המה ריבוי צמצומים והעלמות שונים בירידה אחר ירידה בכדי להחיות נשמתו בגופו [כי כל אדם חייב לומר בשבילי נברא העולם<sup data-n=\"4926\">124</sup> כו' וד\"ל] וכ\"ז מורה על תוקף אה' ה' אלינו אזי כמים הפנים אל פנים<sup data-n=\"4927\">125</sup> יתעורר אהבתו בלבו לדבקה בו ית' ויסתעף מזה ההילוך בדרכי ה' כל היום בתו' ומצוות בבחי' חיות רב שהוא השמחה וטוב לבב והיינו להיות אהבתו אליו יתב' לכן ממילא יאהוב כל דבר שיש בו התפשטות והתגלות עצם אלקו' ית' שהוא ענין התומ\"צ. והנה הגם שאה' זאת נמשכת מצד ההתבוננות בשכל אנושי וההתפעלות ג\"כ אנושי' בנה\"ט היינו מצד שרש הנשמה בבחי' בבי\"ע<sup data-n=\"4928\">126</sup> בבחי' לבושי' הפנימי' דמל' שמצד זה יש בכח הנשמה להשיג גדולת הוי' ולהתפעל ולהיות נמשך במעשה כו' שזהו בחי' נר\"נ שאינם עצם הנשמה רק לבושי הנשמה [כי ענין הלבוש הוא דבר זר שהוא ענין פעולת הגילוי לזולתו שהוא הנה\"ט וכמאמר מבשרי אחזה שהכוונה להראות לנה\"ט בחי' התגלות אלקות וזהו ענין חלק האם שבנשמה [כידוע בענין שלשה שותפין באדם<sup data-n=\"4929\">127</sup> שהוא הנשמה כו'] שזהו מצד שרשם במל' דאצילות<sup data-n=\"4930\">128</sup> שמדת המל' היא ג\"כ לפעול התגלות אלקות בעולמות והנשמה בדומה אליה מצד שממנה לוקח, אך חלק האב שבנשמה הוא חוש הטבעי ועצמי שבנשמה להיות נדבק אחרי כח האלקי המלובש בהשתלשלות העולמות שהוא החיות שבעולמות ולא אחרי היש וכמאמר שאו מרום עיניכם<sup data-n=\"4931\">129</sup> וראו מי ברא כו', ובזה עיקר ההפרש בין ישראל לעמים שהמה תופסים היש לעיקר והיינו מצד שרשם בחיצוני' הדיבור שהוא חיצוני' לבושי המל' אחרי הפרסא אבל שרש נשמות ישראל לפני הפרסא בבחי' אצילו' בבחי' המדות דאצילות שהוא ענין שרשם בתושבע\"פ אשר מחמת זה בטבעם לדבוק אחרי אלקות וחיות שבעולמות ומזה מסתעף ההתבוננות דמח' ודיבור ומע' הנ\"ל שהוא להראות לנה\"ט ג\"כ גילוי אלקות כו'.\n<b>והנה</b> אה' זאת הטבעי' הוא מלובש בכלי הלב ונק' כסף הקדשים בלק\"א<sup data-n=\"4932\">130</sup> וזהו בחי' בכל לבבך, אך יש עוד אה' שהוא בבחי' מעלת הזהב על הכסף והוא מצד ההתבוננות במקור כח האלקי עצמו המחי' כל העולמות שהוא בחי' מדות דאצילות כנ\"ל המה ג\"כ בטלי' למקורם שהוא בחי' חו\"ב דאצילות שמובדלים בערך עדיין מבחי' התהוות מאין ליש בפ\"מ [וכנראה בחוש באדם התחתון שמשכלו לא יסתעף עדיין המעשה עד שיתפעל בלבו מחמת השכל שזהו ענין צמצום שני כו']",[["4926","124","<b>כל אדם חייב לומר בשבילי נברא העולם</b>: ראה סנהדרין לז, סע\"א (במשנה). תניא פמ\"א (נו, א). מאמרי אדה\"א נ\"ך ע' תקמב ואילך. אוה\"ת חנוכה כרך ה ע' תתקמז. לקו\"ש נח כרך ה' ע' 292 ואילך."],["4927","125","<b>כמים הפנים אל פנים</b>: ע\"פ משלי כז, יט."],["4928","126","<b>הנשמה בבחי' בבי\"ע</b>: מתחלה כתב: הנשמה בבי\"ע. ואח\"כ הוסיף תיבת בבחי' בין השיטין ולא מחק הב' מתיבת בבי\"ע."],["4929","127","<b>שלשה שותפין באדם</b>: נדה לא, א. ראה גם לקו\"ת שמ\"ע פט, ב. וראה גם ביאוה\"ז פינחס קיז, ב. תו\"ח בשלח ח\"א קלג, ד. וש\"נ."],["4930","128","<b>הנשמה. . שרשם במל' דאצילות</b>: ראה גם לעיל ע' קמג ובהערה 18."],["4931","129","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["4932","130","<b>כסף הקדשים בלק\"א</b>: פ\"נ."]]],[4801940622,"וכמשל ביטול המדות בשכל וזהו איך דכולא קמי' כלא חשיב<sup data-n=\"4933\">131</sup> [אבל התבוננות הראשון הוא איך שהוא עיקרא ושרשא דכולהו עלמין<sup data-n=\"4934\">132</sup> כו'] שמצד זה תתפשט האה' מלבושי' לא לחפוץ בשום דבר גשמי ורוחני רק להיות נכלל בבחי' עצמו' אלקות כטבע הניצוץ ליכלל בשלהבת וזהו בחי' רצוא וכמבואר בלק\"א<sup data-n=\"4935\">133</sup>, והנה חוש הזה שיש בנש\"י להרגיש בחי' מקור דחו\"ב שמובדלי' בערך מהיות מקור להשתלשלות בפ\"מ רק מקור למקור יחשבו, הוא מצד ששרש נש\"י הוא בתושב\"כ שהוא בחי' ס\"ת בחי' חו\"ב כנ\"ל וד\"ל. וזהו בחי' בכל לבבך כי כיון שהאה' אינה מוגבלת בכלי אזי נמשך כל כח הנפש שבאה' זאת להיות נכלל ובטל באחדות הוי' כו' משא\"כ כשהיא מוגבלת בכלי אזי לא נעשה המשכת כל כח האה' זאת ליכלל באלקו' וממילא מעורב כח לחפוץ ג\"כ עניני העולם כו'.\n<b>והנה</b> כ\"ז הוא אה' דבכל לבבך אבל אה' דבכל נפשך יש בה ג\"כ ב' בחי', נפשך ובכל נפשך. והענין הוא להיות אנו רואים שבטבע כל איש ישראל להיות סו\"מ במצות ל\"ת וע\"ט במ\"ע בבחי' טבעי' ועצמי' כאלו הוא דבר שא\"א לעבור על רצון ה', וזה יש אפי' בנש\"י ועמי הארץ שאינם יודעי' כלל מהתבוננות רק הרצון שלהם הוא למע' מן הטעם ודעת לגמרי, והנה כל רצון יש בו תענוג פנימי המקור אלי' אך מה שאנו רואי' שעושין בקרירות היינו מצד התעלמות היחידה בהם ולכן לא נגלה העונג רק הרצון כאלו נראה שאינו רק בדרך עקשות אבל באמת יש בזה עונג נעלם [וזהו כי עם קשה עורף למעליותא<sup data-n=\"4936\">134</sup> כו']. והנה בגדולי ישראל שפעלי'<sup data-n=\"4937\">135</sup> התגלות היחידה בנפשם נתגלה בהם בחי' העונג וזהו בצדיק וטוב כמו רשב\"י שהי' מיח\"ס ולכן א' בחד קטירא אתקטרנא<sup data-n=\"4938\">136</sup> כו'. והנה ב' בחי' אלו נק' נפשך ובכל נפשך, כי הרצון שלמעלה מן הטעם שבכללו' י\"ש<sup data-n=\"4939\">137</sup> שאינו נוגע רק למעשה בלבד הוא רק חלק וענף מן העונג הנעלם שבקרבם להתענג על הוי' על דייקא כו', משא\"כ בגדולי ישראל שנגלה העונג הפשוט בעצמו נק' בכל נפשך כו' וד\"ל. והנה זהו מצד שרשם בלוחות בחי' אותיות החקוקי' בחי' פנימי' הכתר וחיצוני' הכתר הנק' רצון ותענוג כו' וד\"ל, והוא ענין בעבר הנהר.\n<b>והנה</b> יש עוד בחי' בכל מאודך שהוא בחי' אחת כי העצם בלתי מתחלק<sup data-n=\"4940\">138</sup>, והענין יובן ע\"ד אין מוסרין ס\"ת<sup data-n=\"4941\">139</sup> אלא למי שלבו דואג בקרבו שזה הי' מן הסתם",[["4933","131","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. לעיל ע' רמט ובהערה 74."],["4934","132","<b>עיקרא ושרשא דכולהו עלמין</b>: ראה זהר בהקדמה יא, ב."],["4935","133","<b>בלק\"א</b>: פ\"נ."],["4936","134","<b>כי עם קשה עורף למעליותא</b>: תשא לד, ט. ראה שמו\"ר פמ\"ב, ט. תו\"ח תצוה ח\"ב שעט, ד. וש\"נ. סה\"מ תרכ\"ז ס\"ע עד ואילך. וש\"נ."],["4937","135","<b>שפעלי'</b>: כנצ\"ל: שפועלים."],["4938","136","<b>בחד קטירא אתקטרנא</b>: ראה זהר אד\"ז האזינו רפח, א. סידור ערב שבת קסג, א. שע\"ת נד, ד ובהערה 44."],["4939","137","<b>י\"ש</b>: ישראל."],["4940","138","<b>כי העצם בלתי מתחלק</b>: ראה פלח הרמון וירא נח, א בשם הבעש\"ט [ראה כש\"ט קה\"ת סקי\"א]. לעיל ע' מד ובהערה 132."],["4941","139","<b>אין מוסרין ס\"ת</b>: ראה חגיגה יג, א. מאמרי אדה\"ז תקס\"ד ע' סד. מאמרי אדה\"א ויקרא ח\"ב ע' תסא ואילך. וש\"נ. קונטרסים ע' קסח ובלקוטי ביאורים שם. שעה\"י קיג, ב."]]],[4801940627,"אפי' ברשב\"י אעפ\"י שהי' מתענג בעצמו' אלקות בבחי' עונג פשוט בגילוי מ\"מ התקשרות עצמי' ופנימי' נפשו בבחי' עצמו' אא\"ס ממש זה לא נגלה בנפשו רק בבחי' קו ההפכי שהוא ענין הדאגה עמוקה [וע\"ד בע\"ת שגבוהי' מצד\"ג<sup data-n=\"4942\">140</sup> להיות שהמרירות שלהם על ריחוקם עמוק יותר מהעונג של צד\"ג כו'], והיינו מצד שרש נש\"י בבחי' סתים דחכ' דתורה שהוא ענין סמ\"ע שעלה במח' תחילה היינו בבחי' ראשית עלי' רצה\"פ שהוא בחי' הצמצום פנימי' הרשימו כנ\"ל באריכות ועכשיו אינו מלובש רק בדאגה ולעתיד יתגלה והוא בחי' עונג הנעלם שאינו בא במורגש כלל. והנה עם זה יתפרש ענין אם בחוקתי תלכו, שבקשת הקב\"ה מכנ\"י הלוואי בחוקתי תלכו אתם מלמטה למע' שהוא ענין ב' חקיקות חקיקה ראשונה הוא בחי' אה' שמצד הטעם בבחי' מעלת הזהב על הכסף וחקיקה השני' הוא בחי' ביטול רצון למע' מן הטעם ואפי' למע' מן העונג שמזה נמשך קיום החוקי' דייקא שבלא טעם לגמרי שע\"י זה דייקא תתעלו לבחי' העצמי' דקוב\"ה ע\"י סתים דתורה ותוכלו להמשיך בחי' סתים דקוב\"ה בבחי' גליא דחיצוני' העולמות שזה הי' עיקר המכוון כו' וד\"ל.\n<b>אך</b> להבין ענין תלכו שהוא ענין ההילוך ממקום למקום והיינו למקום עליון ביותר למעלה ממקורו ושרשו הקדום ובאם לאו אינו נק' הילוך כלל, ויובן זה עם מה שית' אח\"כ שפי' ואקח את אביכם מעה\"נ ואולך אותו כו'. ..] אך לכאורה לפי הנ\"ל מה זה שא' ואקח את אביכם מעבר הנהר<sup data-n=\"4943\">141</sup> שהוא ענין טורי חשוכא מדות שבכתר ואולך אותו בכל ארץ כנען שהיא ההתלבשות של הנשמה במל'<sup data-n=\"4944\">142</sup> דאצילות ועי\"ז נמשכה בבי\"ע עד שנתלבשה בגוף ואיזה טובה יש בכאן לנשמה הלא מתחילה היתה מיוחדת בתכלית היחוד ואח\"כ ירדה ירידה גדולה כ\"כ [ובשלמא לפי פשוטו הטובה היא שלקח אותם מעבר הנהר ונתן להם ארץ נחלה אבל לפי שנתפרש למעלה ע\"ד הסוד אינו מובן לכאורה. אך הענין הוא דכנען הוא ל' סוחר<sup data-n=\"4945\">143</sup> וכמו הסוחר המפזר רכושו בריבוי מו\"מ אך המכוון הוא בשביל תוס' הרווחה שלא לפ\"ע כלל, כך הוא בענין ירידת הנשמה הכללי' במל' דאצילות עד שנתלבשה למטה בגוף שזהו ענין פיזור הנפש ברצונות רבים וזרים דנה\"ט, וכל עיקר המכוון דירידה זאת הוא לצורך עלי'<sup data-n=\"4946\">144</sup> שתתעלה עי\"ז הנשמה בעא\"ע<sup data-n=\"4947\">145</sup> עד אין שיעור שזהו תוס' הרווחה הבאה לנשמה ע\"י ירידתה והתלבשותה בגוף וכמשי\"ת כו'. ולהבין זה גם להבין ענין מה שאנו אומרים אתה בחרתנו מכל העמים<sup data-n=\"4948\">146</sup> מה רבותא יש בזה הלא אנו מובדלי' מהם",[["4942","140","<b>בע\"ת שגבוהי' מצד\"ג</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. אוה\"ת בחוקותי כרך ב ע' תרעה ואילך. לעיל ע' שפ. לקמן ביאור מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 33 ואילך."],["4943","141","<b>ואקח את אביכם מעבר הנהר</b>: יהושע כד, ג [בדילוג]."],["4944","142","<b>ארץ כנען. . במל'</b>: ראה גם קהלת יעקב מערכת כנען אות ב. לקו\"ת בחוקותי כאן מז, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפד. תו\"ח וישב קצח, ג."],["4945","143","<b>דכנען הוא ל' סוחר</b>: ראה פסחים נ, א. לקו\"ש נצבים כרך יד ע' 117 הערה 24. ויחי כרך ה ע' 269 בהערות. תו\"א ר\"פ וישב. דרושים שבהערה הקודמת."],["4946","144","<b>דירידה. . לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["4947","145","<b>בעא\"ע</b>: בעילוי אחר עילוי."],["4948","146","<b>שאנו אומרים אתה בחרתנו מכל העמים</b>: בתפלת העמידה ליו\"ט. ראה גם מאמרי אדה\"ז כתובים ח\"א כאן ע' עה. לעיל ע' שלג."]]],[4801940632,"מצד שרש נשמותיהם, כי שרש נש\"י הם בבחי' מח' הפנימי' ועצמי' [... עד רום המעלות בראשית עליות הרצון הפנימי' בעצמי' אא\"ס כנ\"ל במדריגה השישית דסתים דישראל כו'. ..] אבל שרש אוה\"ע הם בבחי' החיצוני'<sup data-n=\"4949\">147</sup> לגמרי אחר ההמשכה ע\"י ריבוי צמצומים ומסכים וא\"כ איזה רבותא יש בזה במה שבחר בנו.\n<b>אך</b> כל הענין הנ\"ל יובן בהקדים ענין התהו והתיקון מה ענינם דהנה מבואר בפרד\"ס שאפי' בחי' ע\"ס הגנוזות<sup data-n=\"4950\">149</sup> בהעלם העצמות המה ג\"כ בחי' כלים<sup data-n=\"4951\">148</sup>, וע\"ד דוגמא אותיות החקוקי' גורמי' ג\"כ חשכות קצת בעצם החומר אעפ\"י שאינם נפרדים ממנו אבל בחי' אא\"ס הוא למע' מבחי' כלים ואינו בגדר תפיסא אפי' בבחי' ע\"ס הגנוזות הנ\"ל שהמה כלי' עצמי' אבל בחי' אא\"ס הוא למע' מגדר כלי לגמרי ולכן נאמר בו אני הוי' לא שניתי<sup data-n=\"4952\">150</sup>, כי ענין אני הוא בחי' התגלות והיינו הגילוי שלו בבחי' אור ואעפ\"כ אפי' הגילוי הוא ג\"כ מובדל מגדר כלי ולכן יכול להיות אחליפו דוכתייהו<sup data-n=\"4953\">151</sup> שיהי' אור החסד מאיר בכלי הגבורה ואור הגבורה מאיר בכלי החסד, והנה בד\"כ זהו ענין תהו ותיקון כי ענין התהו הוא בחי' אורות בלי כלים וכמבואר בכתבי האריז\"ל שבעולם התהו הי' בחי' ריבוי האור ומיעוט הכלים<sup data-n=\"4954\">152</sup> וכיון שהכלי הוא בבחי' מיעוט ממילא הוא בבחי' ביטול והתכללות באור ונמצא שאין שם אלא בחי' אור אבל בעולם התיקון הי' בחי' מיעוט האורות וריבוי הכלים<sup data-n=\"4955\">153</sup> ונמצא שהכלי מעלים את האור והיא עקרי' ולכן נק' בשם כלי לבד, ונמצא שבחי' תוהו ותיקון הוא בחי' אורות וכלים והוא בחי' למעלה מהשתלשלות, וזהו מ\"ש בע\"ח הלשון לא יוכל הכלי לסבול את האור<sup data-n=\"4956\">154</sup> פי' מצד שהאור הוא בבחי' רוממות והבדלה עד שהכלי הוא בו בתכלית הביטול וההתכללות שזהו ענין מיעוט הכלי לכן לא הי' יכול להיות מבחי' אורות דתהו שום גילוי בדרך השתלשלות רק בדרך נפילה שהוא ענין שבירת הכלים, וענין הנפילה היינו ההתהוות בבחי' ריחוק הערך עד שנעשה שרש ומקור ליש נפרד שהוא ענין הרע דנוגה ששרשו הוא בבחי' התוהו",[["4949","147","<b>נש\"י. . מח' הפנימי'. . אוה\"ע. . החיצוני'</b>: ראה גם תו\"ח בשלח ח\"א קלה, א ובהערה 113."],["4950","149","<b>ע\"ס הגנוזות</b>: ראה פרדס שער סדר האצי' ש\"ה, פ\"ד. שער הצחצחות שי\"א. וראה שם פ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו־ לקו\"ב לשעה\"י — קה\"ת — קפט, ג-ד הערה 2."],["4951","148","<b>בפרד\"ס. . ע\"ס הגנוזות. . כלים</b>: ראה פרדס שער הצחצחות שי\"א, פ\"ו. סהמ\"צ להצ\"צ ר\"ע קפג."],["4952","150","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4953","151","<b>אחליפו דוכתייהו</b>: מובא בשם ע\"ח שער מטול\"ט. ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. ע' תשכג. תקס\"ה ח\"א ע' ח. תקס\"ו ע' יב. ענינים ע' סב ובהנסמן במ\"מ לשם. — נזכר באג\"ק מכ\"ק אדמו\"ר מהורש\"ב ח\"א ע' קא."],["4954","152","<b>התהו. . ריבוי האור ומיעוט הכלים</b>: ראה ע\"ח שער הכללים פ\"א. שער שביה\"כ ש\"ט, פ\"ו. מאמרי אדה\"א דברים ח\"ד ע' תעו ואילך. וש\"נ. פלח הרמון בשלח ע' קצו ואילך."],["4955","153","<b>התיקון. . מיעוט האורות וריבוי הכלים</b>: ראה מאמרי אדה\"א דברים שם ע' תפא ואילך (ובהנסמן שם ע' תעו). שער היחוד קלא, א ובהערה 4. פלה\"ר שם."],["4956","154","<b>בע\"ח. . לא יוכל הכלי לסבול את האור</b>: ראה ע\"ח שער הכללים פ\"א."]]],[4801940637,"ומזה נתהווה שרש נה\"ט להיות בבחי' יש נפרד, ונמצא שע\"י התלבשות נה\"א בנה\"ט לבררה ולהעלותה תתעלה לשרשה בבחי' אורות דתוהו ועי\"ז יגרום תוס' אור בבחי' נה\"א שהוא ענין תשו\"ע דבכל מאודך שהוא ענין ההילוך בנשמה בעא\"ע בבחי' עצמו' אא\"ס בלי שיעור וזהו בחי' מאוד שהוא ענין כליון ותשוקה שלא יכילנה הכלי [משא\"כ בכל נפשך שזהו מס\"נ מצד עצם הנה\"א שיכילנה הכלי למס\"נ זאת] שזהו דייקא מצד התלבשותה בגוף דייקא ובזה מובן ענין ירידה צורך עלי' הנ\"ל. ויובן ג\"כ ענין ונתתי לך מהלכים<sup data-n=\"4957\">155</sup> בין העומדים האלה.\n<b>אך</b> הנה ידוע דעיקר המכוון לא הי' בחי' התעוררות אורות דתוהו בלבד אלא פנימי' המכוון הי' שיאירו אורות דתוהו בבחי' כלים דתיקון והיינו ריבוי האורות בריבוי הכלים, וזהו נתאווה הקב\"ה להיות לו דירה בתחתונים כי לו הכוונה לו בעצמו שהוא בחי' אורו והתגלותו כמ\"ש למע' מהשתלשלות שהוא בחי' אורות דתוהו כנ\"ל ושיהי' גילוי זה בבחי' ההשתלשלות דייקא שהוא בחי' כלים דתיקון וזהו דירה בתחתונים, והנה המשכה זאת נמשך ע\"י התורה ומצות שאחר התשובה דבכל מאודך וזהו ענין יפה שעה אחת<sup data-n=\"4958\">156</sup> בתשובה ומע\"ט דייקא כו', ולכן אחרי בכל מאדך נאמר והי' הדברים האלה<sup data-n=\"4959\">157</sup> אשר אנכי כו' ושננתם<sup data-n=\"4960\">158</sup> וקשרתם<sup data-n=\"4961\">159</sup> כו', ועם זה יובן ענין אתה בחרתנו כו' שהרבותא הוא שנבחרו ישראל שיאירו בהם אורות דתוהו שלמע' [אעפ\"י שמצד אורות דתוהו יכולין להאיר אפי' באוה\"ע ואדרבה עיקר שרשם הוא משם וכמבואר במ\"א בענין כמה ארך אפיים לפניו<sup data-n=\"4962\">160</sup> ומה שישראל המה בבחי' פנימי' היינו מצד כלי' דתיקון ששרשם בבחי' חקיקה שהוא פנימי' ההשתלשלו' ואוה\"ע המה בבחי' חיצוני' אבל מצד אורות דתוהו יכולים לקבל השפעה ביותר ולמשול על ישראל וכענין רם על כל גויים ה' כו'] מהשתלשלות ויאירו אורות אלו בכלים דתיקון ואז יקבלו אותם ישראל דייקא ולאוה\"ע לא יאיר רק כפי מדתם עד עת קץ אשר שם לחשך<sup data-n=\"4963\">161</sup>, וזהו ענין אתה בחרתנו להאיר בנו מבחי' אורות דתוהו כו' וד\"ל.\n<b>ועם</b> כל הנ\"ל יובן ענין תקעו בחודש שופר<sup data-n=\"4964\">162</sup>, כי הנה תקיעת שופר הוא קול פשוט בצעקה פנימי' מנקודת הלב ומלובשת בשופר של איל<sup data-n=\"4965\">163</sup> דייקא שבזה מעוררי' מבחי' אורות דתוהו ע\"י שני דברים אלו דייקא, כי ע\"י שופר של איל שהוא בחי' חי ששרשו בבחי' התוהו שקדם לתיקון<sup data-n=\"4966\">164</sup> מעוררי' אורות מבחי' יותר",[["4957","155","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה גם לעיל מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 43."],["4958","156","<b>יפה שעה אחת</b>: אבות פ\"ד, מי\"ז. ראה גם המשך וככה תרל\"ז פי\"ז."],["4959","157","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה גם לעיל מאמר ד\"ה אם בחוקותי תר\"י ובהערה 32."],["4960","158","<b>ושננתם</b>: ואתחנן שם, ז."],["4961","159","<b>וקשרתם</b>: שם ו, ח."],["4962","160","<b>כמה ארך אפיים לפניו</b>: אבות פ\"ה, מ\"ב. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קמו. תו\"ח בשלח ח\"א קלה, א. פלח הרמון בשלח ע' קמה."],["4963","161","<b>קץ. . שם לחושך</b>: איוב כח, ג."],["4964","162","<b>תקעו בחודש שופר</b>: תהלים פא, ה."],["4965","163","<b>בשופר של איל</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."],["4966","164","<b>התוהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."]]],[4801940640,"עליונה, [... כי בחי' החי בעולם התוהו שרשו יותר נעלה ממדבר<sup data-n=\"4967\">165</sup> דשם, כי בחי' התוהו ההשתלשלות הוא מדומם לצומח עד שבחי' מדבר הוא בחי' יותר אחרונה וכמ\"ש אחור וקדם<sup data-n=\"4968\">166</sup> כו' אחור למע\"ב<sup data-n=\"4969\">167</sup> כו', ולכן מצד צעקת הנפש בתשובה מעומקא דליבא בלבד לא הי' מעורר רק בחי' מדבר דשם כו'. ..] ודייקא ע\"י תשובה מעומקא דליבא כי עי\"ז מתעלה לשרשו ולכן צריכין לזה בר\"ה שהוא בחי' תחילת מעשיך<sup data-n=\"4970\">168</sup> ממש שהוא בחי' המשכה חדשה ממקורא דכולא להיות נמשך חיות חדש על כל השנה הן ברוחני' דחיי הנשמות באור תורתם ועבודתם והן בחיות גשמי' שלהם עד שנמשך חיצוני' החיות להחיות אוה\"ע ג\"כ [וכידוע בפי' אמרו לפני מלכיות<sup data-n=\"4971\">169</sup> שתמליכוני עליכם שזהו ענין ישראל שמקבלי' ממלך הקדוש ואח\"כ מלך אלקי' על גויים<sup data-n=\"4972\">170</sup> כו'] וזהו כמו בתחילת ההשתלשלות ממש שהי' התחדשו' גמור מאין ליש לזה צריך לעורר בבחי' הפנימי' והעצמי' דאא\"ס למע' מכל עיקר מקור ההשתלשלות [שהוא בחי' הרצון ומח' דאנא אמלוך וכמבואר למע' בענין בריש הורמנותא כו'] ואז יומשך חיות חדש בהשתלשלות, וזהו כי חוק לישראל<sup data-n=\"4973\">171</sup> כו' חוק לישנא דמזונא<sup data-n=\"4974\">173</sup> וכמ\"ש הטריפני לחם חוקי<sup data-n=\"4975\">174</sup> והוא ענין תוס' אור וחיות בשרש הנשמה<sup data-n=\"4976\">175</sup> כמ\"ש בבחי' אותיות החקוקי' הנק' ישראל ואח\"כ משפט לאלקי יעקב שהוא ענין חלק הנשמה שבגוף<sup data-n=\"4977\">172</sup> הנק' יעקב י' עקב<sup data-n=\"4978\">176</sup> כו'.",[["4967","165","<b>החי בעולם התוהו. . ממדבר</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תתפד. וש\"נ. לעיל ע' קעח ובהערה 98."],["4968","166","<b>אחור וקדם</b>: תהלים קלט, ה."],["4969","167","<b>אחור למע\"ב</b>: ברכות סא, א."],["4970","168","<b>בר\"ה שהוא בחי' תחילת מעשיך</b>: ראה גם לקו\"ת נצבים מז, א. מאמרי אדה\"א דברים ח\"ג ע' תתמ ובהנסמן לשם. ס\"ע תתפט ואילך."],["4971","169","<b>אמרו לפני מלכיות</b>: ראה ר\"ה טז, סע\"ד. לד, ב."],["4972","170","<b>מלך אלקי' על גויים</b>: תהלים מז, ט."],["4973","171","<b>כי חוק לישראל</b>: תהלים פא, ה."],["4974","173","<b>חוק לישנא דמזונא</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'שנט. וש\"נ. תו\"ח ויקהל ח\"ב תמא, א."],["4975","174","<b>הטריפני לחם חוקי</b>: משלי ל, ח."],["4976","175","<b>בשרש הנשמה. . הנק' ישראל. . יעקב. . הנשמה שבגוף</b>: ראה גם מאמרי אדה\"א בראשית ס\"ע קט ואילך וש\"נ. הנחות תקע\"ז ע' שא."],["4977","172","<b>חוק. . הנשמה. . משפט. . הנשמה שבגוף</b>: ראה גם עטרת ראש ע' כב. מאמרי אדה\"א דברים ח\"א ע' פ."],["4978","176","<b>יעקב יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."]]],[4801940131,"<b>[פ' וישלח תר\"ב]</b>\n<b>והתהלכתי</b> בתוככם<sup data-n=\"4979\">1</sup> כו'<sup data-n=\"4980\">2</sup> ואולך אתכם קוממיות<sup data-n=\"4981\">3</sup> כו'<sup data-n=\"4982\">4</sup>. הנה יש ב' מיני הילוך הא' בבחי' אחורים וחיצוני' כמא' אחרי הוי' תלכו<sup data-n=\"4983\">5</sup> וכן במשה כתיב וראית את אחורי ופני לא יראו<sup data-n=\"4984\">6</sup>. והב' ההילוך בבחי' פנים שהוא בחי' פנימי' כמו באברהם כתיב התהלך לפני והיה תמים<sup data-n=\"4985\">7</sup> וכן ביעקב כתיב האלקי' אשר התהלכו אבותי לפניו<sup data-n=\"4986\">8</sup> וכן בחזקי' כתב אשר התהלכתי לפניך<sup data-n=\"4987\">9</sup> כו'. והנה להבין ענין ב' בחי' הילוך הנ\"ל מתחילה צ\"ל ענין ההילוך, כי הנה כתיב ונתתי לך מהלכים<sup data-n=\"4988\">10</sup> בין העומדים האלה שמלאכים נק' עומדים וכן בחי' הנשמות קודם בואם לגוף נק' עומדים וכמאמ' חי ה' אשר עמדתי לפניו<sup data-n=\"4989\">11</sup>, ותכלית הכוונה בבחי' הירידה שלהם בגוף הוא כדי שיבואו למדרגה מהלכים בין העומדים כמשי\"ת. וביאור הדברים צ\"ל ענין ב' בחי' שפע מאא\"ס בעולמות, הא' בחי' ממכ\"ע והב' בחי' סכ\"ע, רק<sup data-n=\"4990\">12</sup> בחי' ממכ\"ע הוא בחי' אור וחיות הבא בבחי' התלבשות בעולמות בחלוקי מדריגות בכל עולם ועולם לפ\"ע כמו עד\"מ בחי' שכל ומדות שבחי' המדות נולדים מן השכל<sup data-n=\"4991\">13</sup> שיש שכל שמראה לחסד ויש שכל שמראה לדין ויש שמראה לדין לרחם<sup data-n=\"4992\">*14</sup>, וכפי הוראת השכל כן נולדים המדות בלב, הנה שפע זאת הוא הבא בבחי' פנימי' ומתלבשת במדות כו'. ויובן בתוס' באור מבחי' חיות הנפש בגוף שבחי' שפע החיות מתלבש באברים ונמשך בהם בדרך חומר וצורה<sup data-n=\"4993\">14</sup> שהחומר מעין הצורה<sup data-n=\"4994\">15</sup> ולכן משתנה החיות לפ\"ע החומר המתלבש בו כמו במוחין בא השפע בדרך כללות לכלול כל פרטי החיות של כל האיברים בהעלם ואח\"כ הוא בא ונמשך מההעלם אל הגילוי בכל אבר ואבר בפרט כמו כח הראי' בעין וכח השמיעה באוזן כו'.",[["4979","1","<b>והתהלכתי בתוככם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה ד\"ה זה במאמרי אדה\"ז הנחות הר\"פ ע' קנו־ תקס\"ט ע' קלא־ ובארוכה במאמרי אדה\"א ויקרא ח\"ב ע' תשפה ואילך (ובהנסמן בהנ\"ל)־ אוה\"ת ויקרא כרך ב. לקמן ד\"ה והתהלכתי תרכ\"ב.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["4980","2","<b>והתהלכתי בתוככם כו'</b>: בחוקותי כו, יב."],["4981","3","<b>ואולך אתכם קוממיות</b>: בחוקותי שם, יג."],["4982","4","<b>כו'</b>: וכ\"ה גם לקמן במאמר ד\"ה זה דשנת תרכ\"ב בתחילתו."],["4983","5","<b>אחרי הוי' תלכו</b>: ראה פ' ראה יג, ה."],["4984","6","<b>וראית את אחורי ופני לא יראו</b>: תשא לג, כג."],["4985","7","<b>התהלך לפני והיה תמים</b>: לך יז, א."],["4986","8","<b>האלקי' אשר התהלכו אבותי לפניו</b>: ויחי מח, טו."],["4987","9","<b>כתב </b>[אוצ\"ל: כתיב]<b> אשר התהלכתי לפניך</b>: מל\"ב כ, ג. ישעי' לח, ג."],["4988","10","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה לעיל מאמר ד\"ה אם בחוקותי תר\"י ובהערה 43."],["4989","11","<b>חי הוי' אשר עמדתי לפניו</b>: מל\"ב ה, טז. ראה גם שע\"ת כ, ג ובהערה 31."],["4990","12","<b>רק</b>: אינו ברור בהכת\"י ואולי כתוב: כו'."],["4991","13","<b>המדות נולדים מן השכל</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שלא ואילך. תקס\"ט ע' טז. ע' קסז ואילך. ענינים ע' רעח ואילך. תו\"א יתרו עג, א. לקו\"ת שמיני יט, ב. שה\"ש מו, ב. סה\"מ תרכ\"ז ע' קה ואילך. ע' שנד. וראה גם לקמן בהביאור פיסקא והתירוץ הב'."],["4992","*14","<b>לדין לרחם</b>: כ\"ה בהכת\"י."],["4993","14","<b>חומר וצורה</b>: ראה מו\"נ ח\"א פי\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' קעו. שמות ח\"א ע' כג. סה\"מ תרכ\"ט ע' יז. וש\"נ."],["4994","15","<b>שהחומר מעין הצורה</b>: ראה גם שעה\"י קכט, א ובהערה 7."]]],[4801940195,"<b>וככה</b> יובן למעלה עד\"ז בבחי' התגלות החיות דממכ\"ע בעולמות שהוא בא בדרך כלל ופרט כמו תחלת התלבשות החיות הוא בהיכל שבכל עולם ועולם שהוא בחי' ראש ומוחין שבעולם ההוא ובו בא התלבשות החיות בדרך כלל ואח\"כ נמשך מהאה\"ג<sup data-n=\"4995\">17</sup> בפרט בבחי' ששה היכלות שבעולם ההוא<sup data-n=\"4996\">16</sup>, וכ\"ה בכללות העולמות דבי\"ע ראשית גילוי החיות בד\"כ הוא בהיכל דבריאה ואח\"כ מתחלק מהעלם אה\"ג בכל עולם בפרט, ובכל מדריגה שבעולם ההוא ג\"כ בפרט, ושפע זאת דממכ\"ע הוא הבא ע\"י צמצום אור האלקי שזהו ענין צמצם שכינתו בין שני בדי הארון<sup data-n=\"4997\">18</sup> כו' שכינה הוא בחי' מל'<sup data-n=\"4998\">19</sup> דאצי' שהוא בחי' אלקות ממש דאיהו וגרמוהי חד<sup data-n=\"4999\">20</sup> כמו כל הספי' דאצי' וע\"י צמצום בא אור האלקי בבחי' תפיסא והתלבשות בהיכל דבריאה שזהו ענין בין שני בדי הארון כו' וע\"ד גילוי שכינה בעוה\"ז שתחלת כללות הגילוי הי' בהיכל שבבהמ\"ק ומשם האיר לכל נש\"י לכאו\"א בפרט לפ\"ע וכמבואר בלק\"א פ'<sup data-n=\"5000\">21</sup> [... ובדרך כלל יותר הנה בחי' גילוי הקו המאיר ע\"י צמצום מבחי' מל' דא\"ס הנק' אא\"ס הוא בחי' ממכ\"ע והוא מאיר בתחלה בד\"כ בבחי' א\"ק שהוא בחי' מחה\"ק שצופה ומביט<sup data-n=\"5001\">22</sup> עד סוף כל הדורות בסקירה אחת והוא בחי' ראש ומוחין בכללות העולמות דאבי\"ע ואח\"כ קורא הדורות מראש<sup data-n=\"5002\">23</sup> בפרט מהאה\"ג כנ\"ל במא' יונתי<sup data-n=\"5003\">24</sup> כו'].\n<b>והנה</b> כ\"ז הוא בחי' ממכ\"ע אבל סוכ\"ע הוא בחי' אור ושפע שאינו בא בבחי' התלבשות בעולמות כלל רק בבחי' השראה בהעלם וכמו הנשמה המחי' את הגוף שכללו' החיות המאיר בגוף אפי' בבחי' המוחין שהוא בחי' חיות כללי אינו רק הארה בעלמא מעצמי' הנשמה אבל עצמי' נשאר בבחי' העלם ומקיף שזהו בחי' מזלא שבנשמה<sup data-n=\"5004\">25</sup> כו' כי אין האיברים מרגישים כלל חיות עצמי' הנשמה אעפ\"י שבאמת עיקר קיום חיות הפנימי הוא מבחי' המקיף השורה בהעלם מ\"מ אינו מורגש באברים כלל, כ\"ה למעלה בחי' עצמו' אלקות אינו בא כלל בבחי' הרגשה בעולמות אע\"פ שבאמת נמצא בכל העולמות עד דלית אתר פנוי מיני'<sup data-n=\"5005\">26</sup> והוא נמצא בכולם",[["4995","17","<b>מהאה\"ג</b>: מהעלם אל הגילוי."],["4996","16","<b>בהיכל שבכל עולם. . ואח\"כ. . ששה היכלות שבעולם ההוא</b>: ראה ע\"ח שער כסה\"כ שמ\"ו, פ\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתה."],["4997","18","<b>צמצם שכינתו. . הארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["4998","19","<b>שכינה. . מל'</b>: ראה זהר רע\"מ תצא רפא, ב. לעיל מאמר ד\"ה את שבתותי תרי\"ב ובהערה 115."],["4999","20","<b>דאיהו וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב)."],["5000","21","<b>בלק\"א פ'</b>: אינו ברור הנרשם כאן בהכת\"י. ראה פנ\"ב-ג."],["5001","22","<b>שצופה ומביט</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. תו\"ח שמות ח\"א מח, ב. וש\"נ."],["5002","23","<b>קורא הדורות מראש</b>: ישעי' מא, ד. ראה גם לעיל ע' עז ובהערה 27."],["5003","24","<b>כנ\"ל במא' יונתי</b>: פלח הרמון שה\"ש ע' מג."],["5004","25","<b>מעצמי' הנשמה. . מזלא שבנשמה</b>: ראה שעה\"ק להרח\"ו ח\"ג, ש\"ה. לקו\"ת במדבר טז, א ואילך. האזינו עא, ד. מאמרי אדה\"א דברים ח\"ד ע' א'קסט ואילך. וש\"נ. לעיל ע' רמח"],["5005","26","<b>דלית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."]]],[4801940252,"בהשוואה ומזה הוא אמיתת קיום חיותם והתהוותם מאין ליש מ\"מ אינו נמצא רק בהעלם ולא בגלוי כלל ולכן נק' סוכ\"ע ע\"ש שאינו בא בהרגשה התלבשות בעולמות רק בהעלם אבל באמת נמצא בכולם בהשוואה כנ\"ל. והנה בחי' סוכ\"ע א\"א להשיג כלל בשום דרך ואופן כי למת\"ב<sup data-n=\"5006\">27</sup> כו' רק ע\"י מצוות גורמים בחי' יחוד קובהו\"ש<sup data-n=\"5007\">28</sup> שזהו בחי' גלוי הסובב בממלא והיינו ע\"י מצוות שמקיים כ\"א מישראל דווקא בנשמתו המלובשת בגופו דווקא בזה ממשיכים יחוד סובב וממלא והיינו שיאיר בחי' הסובב בבחי' גלוי בממכ\"ע כו'.\n<b>ועם</b> זה יובן ענין עומדים ומהלכים כי המלאכים וכן הנשמות בהיותם בג\"ע הגם שנהנין מזיו השכינה<sup data-n=\"5008\">29</sup> בבחי' עונג האלקי הנמשך שם וגם עליהם נא' וקדושים בכ\"י יהללוך סלה<sup data-n=\"5009\">30</sup> בעא\"ע בלי הפסק אך כאו\"א הוא מרגיש אור האלקי שבמקורו אשר לוקח משם כמו מחנה מיכאל באה' מקבלים שפע וחיות מחסד שבמל' דאצי' המקור אליו ומקורו הוא גופא הוא בחי' אור המוגבל בכלי [... שהוא ענין ע\"מ<sup data-n=\"5010\">31</sup> שבמל' שהם בחי' כלים לאורות די\"ס שבמל' כו'], וכן הנשמות ג\"כ אינם מקבלים רק מבחי' אור המוגבל בכלי [... רק שמקבלים מפנימי' הכלים] שזהו בחי' ממכ\"ע, וההתפעלות זאת מוגבלת שזהו ענין אה' דבכל נפשך כו', אבל הנשמה ע\"י התלבשותה בגוף לקיים מצוות בעוה\"ז המלובשים בדברים גשמיי' המה מעוררים למעלה בחי' הסוכ\"ע בממלא ועי\"ז נק' מהלכים, כי ענין הילוך הוא בחי' התפשטות שהוא בחי' יציאה לחוץ מגבולו המגבילו וא\"כ ממילא הוא בל\"ג כו' והוא ענין אה' דבכל מאדך שבא מצד גילוי הסובב דווקא כו' וד\"ל. וזהו בכל יום יהי' בעיניך כחדשים<sup data-n=\"5011\">32</sup> שזהו דווקא כאשר הגלוי הוא מבחי' סוכ\"ע שהוא בחי' א\"ס למעלה מבחי' הגבלה בכלים ולכן בכי\"ו הוא התחדשות ואינו מתיישן כלל כנ\"ל במא' יונתי<sup data-n=\"5012\">33</sup> כו'.\n<b>והטעם</b> לזה שע\"י מצוות גשמי' שבעוה\"ז ממשיכים גלוי הסובב הנה ידוע בענין מה שעוה\"ב נק' עולם ברור<sup data-n=\"5013\">34</sup> והיינו מפני ששרשו נמשך מבחי' ממכ\"ע שהוא בחי' אור וחיות פנימי בבחי' התלבשות הכלים ולכן א\"א שיתהפך מן הקצה אל הקצה וא\"א לבוא למדריגתו בעוה\"ב כאשר פגם נשמתו כ\"א כאשר יזדכך בתחילה בגיהנום או בכף הקלע או בנה\"ד כ\"א לפי אופן הפגם שלו כו', משא\"כ בעוה\"ז אפשר להתהפך ע\"י תשובה ברגע א' מן הקצה אל הקצה דהיינו מבחי' רשע גמור",[["5006","27","<b>למת\"ב</b>: ראה ת\"ז בהקדמה יז, א."],["5007","28","<b>יחוד קובהו\"ש</b>: ראה גם אוה\"ת ואתחנן ע' רנה ואילך. כרך ו ע' ב'רעג ואילך (ס\"ב). מאמרי אדה\"א ויקרא ח\"א ע' רכ ואילך. תו\"ח תצוה ח\"ב שלא, א הערה 504."],["5008","29","<b>בג\"ע. . מזיו השכינה</b>: ראה תו\"א מקץ לב, ד. מאמרי אדה\"ז תקס\"ב ח\"א ע' קפה ואילך."],["5009","30","<b>וקדושים בכ\"י יהללוך סלה</b>: תפילת שמו\"ע."],["5010","31","<b>ע\"מ</b>: עשרה מאמרות."],["5011","32","<b>בכל יום יהי' בעיניך כחדשים</b>: ראה לקח טוב ואתחנן ו, ו. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. לעיל ע' קמב הערה 14."],["5012","33","<b>כנ\"ל במא' יונתי</b>: פלח הרמון שה\"ש ע' מא."],["5013","34","<b>שעוה\"ב נק' עולם ברור</b>: פסחים נ, א. ראה לקו\"ת פינחס עה, סע\"ב ואילך. עו, סע\"ד. סידור שחרית לב, ב. לה סע\"ד ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתכג ואילך. במדבר ח\"ה ע' א'תרכד ואילך. סהמ\"צ להצ\"צ לט, ב ואילך. קמב, ב ואילך."]]],[4801940305,"לבחי' צדיק גמור כמארז\"ל בענין המקדש את האשה<sup data-n=\"5014\">35</sup> כו', והטעם לזה כי שורש גשמי' העוה\"ז נמשך מבחי' כל יכול שהוא בחי' סוכ\"ע לכן בעוה\"ז דווקא יוכל להיות התהפכות כנ\"ל מצד הארת סוכ\"ע המאיר בו כו' והוא ג\"כ הטעם בעסק המצות שבעוה\"ז דווקא בגשמיות שיוכל עי\"ז להמשיך גילוי הסובב בממלא כנ\"ל וד\"ל. וזהו ענין מהלכים בין העומדים שע\"י ההילוך שנעשה מעסק המצוות שבעוה\"ז עי\"ז ממשיך גלוי אא\"ס הסובב כ\"ע גם בין העומדים שהוא בחי' נשמות ומלאכים שבג\"ע שמקבלים ג\"כ תוס' אור ושפע יתר מכפי המדה הקצובה להם משרש מקור חוצבם בממכ\"ע כו' וד\"ל.\n<b>ומעתה</b> י\"ל ענין ב' מיני הילוך הנ\"ל בבחי' אחורים ובבחי' פנים כו'. הנה ארז\"ל בברכות בפ' כ\"מ<sup data-n=\"5015\">36</sup> ארומיא דקראי דלפעמים א' ועמדו זרים ורעו את צאנם<sup data-n=\"5016\">37</sup> ולפעמים ואספת דגנך<sup data-n=\"5017\">38</sup> ותירצו כאן כשאין עושין רצונו ש\"מ וכאן כשעושין רצונו ש\"מ, והקושיא מבוארת דהלא ואספת דגנך הוא בפ' שני' דק\"ש ושם נאמר והי' אם שמוע<sup data-n=\"5018\">39</sup> תשמעו אל מצוותי וגם נא' בכל לבבכם ובכל נפשכם ואיך יתכן לומר שזה נק' אין עושין רצונו של מקום, וידוע התירוץ בשם הה\"מ נ\"ע שמפני שלא נא' כאן בכל מאודך לכן נק' אין עושין כו' משא\"כ בפ' ראשונה נאמר בכל מאודך<sup data-n=\"5019\">40</sup> לכן נק' עושין רצונו ש\"מ. ועדיין אינו מובן דמפני שלא נא' ובכל מאודך אף שמבטל א\"ע לאלקות בכל לב ונפש נק' אין עושין רצונו של מקום, אך הענין יובן בהקדם ענין מקום מהו כי הנה הקב\"ה נק' בשם מקום כמארז\"ל במשנה אין עומדים<sup data-n=\"5020\">41</sup> עד שיתכוונו<sup data-n=\"5021\">42</sup> לבם למקום, וכן אנו אומרים ברוך המקום<sup data-n=\"5022\">43</sup>, הענין הוא דהנה כי הנה מקום אתי<sup data-n=\"5023\">44</sup> וביאור ענינו הוא בחי' כח אלקי העושה בחי' מקום לכן נק' בשם מקום להיותו מקור לבחי' מקום וכמאמר הוא מקומו ש\"ע<sup data-n=\"5024\">45</sup> כו'. הנה ביעקב כתיב ויקח",[["5014","35","<b>המקדש את האשה</b>: קדושין מט, ב. ראה גם לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 41. לקו\"ת דברים א, ב. סה\"מ תרל\"ח ע' תקי ובהערה 89."],["5015","36","<b>בברכות בפ' כ\"מ</b>: ראה ברכות לה, ב. ע\"ד הלשון כאן (בנוסף להערה 1) ראה מאמרי אדה\"ז־ שע\"ת־ מאמרי אדה\"א־ אוה\"ת שהובאו לקמן הערה 40."],["5016","37","<b>ועמדו זרים ורעו את צאנם</b>: ישעי' סא, ה [ושם: ורעו צאנכם]."],["5017","38","<b>ואספת דגנך</b>: עקב יא, יד."],["5018","39","<b>והי' אם שמוע</b>: עקב יא, יג."],["5019","40","<b>בשם הה\"מ. . בכל מאודך</b>: ראה או\"ת עקב ד\"ה מפני מה (נג, סע\"ג ואילך). לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 69 ובהגהת ר' הלל שם. ד\"ה והתהלכתי תרכ\"ב על יד הערה 73. מובא גם בשם הה\"מ במאמרי אדה\"ז תקס\"ג ח\"ב ע' תרעט. שע\"ת קכה, ב. קלה סע\"ג ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' רפו. אוה\"ת עקב ע' תפא. מאמרי אדהצ\"צ תרט\"ו ע' קב. ע' רמט. ע' ערה. סה\"מ תרכ\"ט ע' קצז. ראה גם הנסמן בלקו\"ש אמור כרך יב ע' 98־ מאמרי אדה\"א וסה\"מ תרכ\"ט שם."],["5020","41","<b>הקב\"ה. . מקום. . במשנה אין עומדים</b>: ברכות רפ\"ד כגי' המשניות. ראה גם בהבא לקמן שיעור קומה להרמ\"ק ס\"כ. אוה\"ת בחוקותי כרך ב ע' תרמד ואילך. ע' תרנז ואילך. יחזקאל כרך א' ס\"ע תב ואילך. לעיל ע' שעט."],["5021","42","<b>שיתכוונו</b>: כ\"ה בהכת\"י."],["5022","43","<b>ברוך המקום</b>: מדות ספ\"ה."],["5023","44","<b>כי הנה מקום אתי</b>: תשא לג, כא [בהוספת תיבת כי — ראה גם שע\"ת קכה, ג].."],["5024","45","<b>הוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ. לקמן בהביאור על יד הערה 45. ד\"ה והתהלכתי תרט\"ו על יד הערה 77 ואילך."]]],[4801940355,"מאבני המקום<sup data-n=\"5025\">46</sup> ומבואר בזוהר שיש י\"ב מלאכים הנושאים את הכסא<sup data-n=\"5026\">47</sup> שהם ג' לסטרא מזרח וג' לסטרא דרום כו' ונמצא שהם בחי' מקום של כל העולמות כי מקום הוא מעלה ומטה ד' רוחות<sup data-n=\"5027\">48</sup> שהוא בחי' הגבלת כל נברא בכאו\"א לפ\"ע וכן יש הגבלה בזמן כו', אך מקור המקום והזמן הוא בחי' מל'<sup data-n=\"5028\">49</sup> דאצי' כידוע בענין ממכ\"ע הוא בחי' מקום הנק' עולם וממשלתך בכל דו\"ד<sup data-n=\"5029\">50</sup> הוא בחי' הזמן, וע\"ז נא' הנה מקום אתי שבחי' המל' מיוחדת בו ית' שהוא למעלה מגדר מקום וזמן וכמא' לך ה' הממלכה<sup data-n=\"5030\">51</sup> וכידוע דנהו\"ת קארי תדיר לנהורא עילאה<sup data-n=\"5031\">52</sup>, אך כדי שיתגלה יחוד זה בעולמות זהו ענין ויפגע במקום<sup data-n=\"5032\">53</sup> שהוא ענין יעקב תיקן תפילת ערבית<sup data-n=\"5033\">54</sup> והיינו שתיקנה שיתגלה בחי' מקום בחי' סוכ\"ע שהוא למע' מגדר מקום וזמן.\n<b>וזהו</b> ענין יין המשמח אלקים<sup data-n=\"5034\">55</sup> ולכאורה אינו מובן מהו שמחתו שמשמח את אלקים, אך הנה ידוע בענין הוי' ואלקי' ששם הוי' הוא למע' מגדר מקום וזמן כידוע דהוי' הוא הי' הווה ויהי' כא'<sup data-n=\"5035\">56</sup> אך בחי' אלקות<sup data-n=\"5036\">57</sup> הוא בחי' המל'<sup data-n=\"5037\">58</sup> שבניינה מהגבורות<sup data-n=\"5038\">59</sup> שפועלים צמצומים והסתר שיהי' בחי' מקום וזמן, ויין הוא המשמח אלקים שמגלה פנימיותו שהוא בחי' שם הווי' שלמעלה מגדר מקום וזמן המלובש במקום וזמן בהעלם וע\"י היין נתגלה כו', וזהו מה שמשמח אלקים כו', ומבואר למעלה שבחי' יחוד דסובב וממלא הוא ע\"י המצוות אך בזה יש ב' אופנים בחי' עושין רצונו כו' ואין עושין כו', כי הנה לפעמים אנו מוצאים שהמצות נק' בשם לבושים כמא' הזוהר ע\"פ ואברהם זקן בא בימים<sup data-n=\"5039\">60</sup> דמאן דגרע יומא חדא גרע לבושא חדא, וכן ביעקב נא' וירח את ריח בגדיו<sup data-n=\"5040\">61</sup> כו' שהוא בחי' כללו' המצוות הנק'",[["5025","46","<b>ויקח מאבני המקום</b>: ויצא כח, יא."],["5026","47","<b>י\"ב מלאכים הנושאים את הכסא</b>: ראה זהר ויצא קמז, ב ואילך. לקמן בהביאור על יד הערה 36 ואילך."],["5027","48","<b>מקום הוא מעלה ומטה ד' רוחות</b>: ראה שער היחוד והאמונה פ\"ז ובמ\"מ הגהות והע\"ק שם. לקו\"ת בחוקותי מח, ב. מאמרי אדה\"א שמות ח\"א ע' קסז (ובהנסמן בריש המאמר שם). שע\"ת קכה, ג."],["5028","49","<b>מקור המקום והזמן הוא בחי' מל'</b>: ראה שהיוה\"א שם. לעיל ע' רלא ובהערה 20."],["5029","50","<b>ממכ\"ע. . וממשלתך בכל דו\"ד</b>: תהלים קמה, יג. ראה תו\"א מקץ לז, א. לקו\"ת אחרי כז, ב. בהעלותך ל, א."],["5030","51","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."],["5031","52","<b>דנהו\"ת קארי תדיר לנהורא עילאה</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["5032","53","<b>ויפגע במקום</b>: התחלת הכתוב ויקח מאבני המקום — ויצא כח, יא."],["5033","54","<b>יעקב תיקן תפילת ערבית</b>: ברכות כו, ב."],["5034","55","<b>יין המשמח אלקים</b>: ס' שופטים ט, יג. ראה גם לעיל מאמר ד\"ה כי תבואו וגו' ושבתה תר\"ט על יד הערה 48."],["5035","56","<b>דהוי' הוא הי' הווה ויהי' כא'</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["5036","57","<b>אלקות</b>: כנצ\"ל: אלקים."],["5037","58","<b>אלקים הוא בחי' המל'</b>: ראה זהר בראשית כב, א. אחרי סה, א. תו\"ח וארא ח\"א עה, ב הערה 202."],["5038","59","<b>המל' שבניינה מהגבורות</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ. לעיל ע' רצא ואילך."],["5039","60","<b>ואברהם זקן בא בימים</b>: ח\"ש כד, א. ראה גם לעיל ע' רנב ובהערה 119."],["5040","61","<b>וירח את ריח בגדיו</b>: תולדות כז, כז. ראה סידור שער התפלה כז, ב. כח, ד. לקו\"ת שה\"ש לב, ב. לג, ב. ש\"א יא, ב. מאמרי אדה\"א דרושי חתונה ח\"א ע' קכא."]]],[4801940401,"בשם בגדים של נשמה הנק' בחי' יעקב, וכן אצל הינוקא נא' שהכיר בריחא דלבושייהו<sup data-n=\"5041\">62</sup>, ולפעמים אנו מוצאים שהמצוות נק' בשם פירות כמארז\"ל אצל עגלה ערופה שלא הניחוהו לעשות פירות מאי פירות מצוות<sup data-n=\"5042\">63</sup>.\n<b>וביאור</b> הענין יובן ע\"פ הנ\"ל שענין המצוות הוא בחי' גלוי הסובב בממלא אך בגילוי זה יש ג'<sup data-n=\"5043\">64</sup> אופנים, הא' הגלוי בבחי' מקיף שגם המקיף נק' אור ופועל בו קיומו כו' וכענין השמים המקיפים לארץ שעי\"ז מתקיים הארץ ובלא הנ\"ל לא הי' מתקיים כלל, והב' כאשר המקיף נגלה ונמשך בבחי' או\"פ ממש תוך הכלים וכענין השפע הבא משמים לארץ שהוא ענין טל ומטר הנכנס ומתלבש בתוך חלקי כדור הארץ ופועל בו צמיחה מאין ליש, כ\"ה בענין המצות שלפעמים מעוררים גלוי הסובב שיאיר בבחי' מקיף בלבד ואז המצוות נק' בשם לבושים כו' ולפעמים פועלים ע\"י המצוות שיתגלו בבחי' פנימי' ממש ואז נעשה בחי' מזון לנשמה ואז המצוות נק' בשם פירות<sup data-n=\"5044\">65</sup> כו' וענין זה תלוי בעושין רצונו כו' ואין עושין כו', כי הנה ענין עושין רצונו הוא כמו בנשמות הגבוהות שנגלה אצלם בחי' רעו\"ד שלמעלה משכל ומדות וכמו ברשב\"י שא' בחד קטירא אתקטרנא<sup data-n=\"5045\">66</sup> בי' בקב\"ה ואצלם הוא בחי' אתהפכא שהרע נהפך לטוב והוא בחי' ישראל כי שרית עם אלקים<sup data-n=\"5046\">67</sup> מצד שרואין אמיתת ביטול המקום הנמשך מבחי' שם אלקים לגבי שם הוי' שהוא למע' מבחי' מקום וזמן, ובחי' זאת הוא בחי' בן שעבודתו הוא בחי' תענוג שמתענגין על הוי', וזהו ולא ראה עמל בישראל<sup data-n=\"5047\">68</sup> כי אינם צריכים לעבודה ויגיעה רק עבודתם הוא בבחי' תענוג ממילא ומאיליו, וזהו עושין רצונו ש\"מ שממשיכין בחי' רצה\"ע בבחי' מקום<sup data-n=\"5048\">69</sup> ונעשה גלוי הסובב בממלא בבחי' או\"פ, משא\"כ נשמות שלמטה במדריגה שעבודתם הוא בחי' מעהמ\"צ ונק' בחי' יעקב ובחי' עבד כמ\"ש שמע אלי יעקב עבדי<sup data-n=\"5049\">70</sup> נק' אין עושין רצש\"מ מצד שאינם מגיעים לרצה\"ע ואינם פועלים רק גלוי הסובב בבחי' או\"מ ואז נק' המצוות בשם לבושים כו'.\n<b>וזהו</b> ענין ב' פרשיות דק\"ש כי פרשה ראשונה הוא בבחי' נשמות הגבוהות שנק' ישראל כמא' שמע ישראל<sup data-n=\"5050\">71</sup> ולכן נא' ובכל מאודך כי אצלם נגלה בחי' רעו\"ד, ובחי' זאת אור הגבורה כי גבורה אינו בחי' דין רק גבורות ממותקות<sup data-n=\"5051\">72</sup>",[["5041","62","<b>שהכיר בריחא דלבושייהו</b>: זהר ינוקא בלק קפו, א. ראה מאמרי אה\"ז הקצרים ע' שצט. מאמרי אדה\"א דרושי חתונה שם ע' קה. וש\"נ."],["5042","63","<b>מאי פירות מצוות</b>: ראה סוטה מו, סע\"א."],["5043","64","<b>ג'</b>: כ\"ה בהכת\"י."],["5044","65","<b>המצוות נק' בשם לבושים. . פירות</b>: ראה גם אוה\"ת בחוקותי כאן ע' תרסו. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 81."],["5045","66","<b>בחד קטירא אתקטרנא</b>: ראה זהר אד\"ז האזינו רפח, א. סידור ערב שבת קסג, א. שע\"ת נד, ד ובהערה 44."],["5046","67","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["5047","68","<b>ולא ראה עמל בישראל</b>: בלק כג, כא."],["5048","69","<b>עושין רצונו. . בבחי' מקום</b>: ראה גם שע\"ת קכה, ג (ובהנסמן בריש המאמר שם). אוה\"ת בחוקותי כאן ס\"ע תרסה ואילך."],["5049","70","<b>שמע אלי יעקב עבדי</b>: ישעי מד, א [בהוספת תיבת: אלי — וכ\"ה בלקו\"ת בלק ע, רע\"ג. מאמרי אדה\"ז תקס\"ד ע' קעד. אוה\"ת בלק ע' תתקצו]."],["5050","71","<b>שמע ישראל</b>: ואתחנן ו, ד."],["5051","72","<b>גבורה. . גבורות ממותקות</b>: ראה תו\"א נח ט, ג. לקו\"ש תולדות כרך ל ע' 108. וש\"נ."]]],[4801940444,"כענין הדם שהוא בחי' תוקף החמימות תוקף הגבורה והוא עיקר המחי' וכמו מי שנק' גבור שהוא ע\"ש תגבורת כחו לבא בבחי' גלוי, וזהו גלוי סובב בממלא לבוא בבחי' או\"פ כו', ובחי' פ' שני' דק\"ש כאשר אין נגלה אצלם בחי' רעו\"ד שלכן לא נא' בכל מאדך אז נק' אין עושין כו' ולכן אין פועלים גלוי הסובב רק בבחי' או\"מ, וזהו ההפרש בין מלאכתן נעשה ע\"י אחרים ובין מלאכתן נעשה ע\"י עצמן שע\"ז נא' ואספת דגנך, כי הנה פי' ואספת דגנך אינו העבודה לקבל הדגן בגשמי' כפשוטן רק הכוונה הוא ברוחני' מעשה המצוות<sup data-n=\"5052\">73</sup> שיש בחי' חרישא דמרפיא ארעא<sup data-n=\"5053\">74</sup> שהוא ענין ירגיז אדם יצ\"ט על יצה\"ר<sup data-n=\"5054\">75</sup> ולהכניע חומר הגוף הגס וכן עד\"ז כל העבודות ישנם ברוחני' ואח\"כ כאשר מקיים המצוות גורם בירור והעלאה למע' מע' ועי\"ז גורם המשכה מבחי' סובב בממלא שהוא בחי' ורב תבואות בכח שור<sup data-n=\"5055\">76</sup> ובחי' זאת נק' מלאכתן נעשה ע\"י עצמן, משא\"כ בנשמות הגבוהים שנהפך אצלם הרע אינם צריכים לחרטה כלל רק המשכת אלקות בבחי' תענוג [... וממילא נעשה הבירורים למטה כמ\"ש במ\"א ממשל האבוקה<sup data-n=\"5056\">77</sup> שממשיך אליו ממילא כל הניצוצים] ואז מלאכתן נעשה ע\"י אחרים ממילא ומאליו וזהו שא' רשב\"י אפשר אדם חורש<sup data-n=\"5057\">78</sup> כו'.\n<b>ומעתה</b> יובן ענין ב' מיני הילוך הנ\"ל כי הנה ההילוך בבחי' פנים הוא בחי' ההילוך מלמעלה למטה כי התחלת העבודה הוא מבחי' תענוג שמתענג על הוי' וממילא נמשך גילוי אלקות בבחי' שכל ומדות ואח\"כ בלבושים דמחדו\"מ וזהו ענין פ' ראשונה דק\"ש שמתחילה ההעלאה דבכל מאודך שהוא בחי' רעו\"ד הנ\"ל ואח\"כ נעשה המשכה מלמעלה למטה והיו הדברים האלה<sup data-n=\"5058\">79</sup> אשר אנכי מצוך היום על לבבך בבחי' שכל ומדות ואח\"כ בלבושים דמחדו\"מ וזהו ושננתם כו' ודברת בם<sup data-n=\"5059\">80</sup> כו' וקשרתם<sup data-n=\"5060\">81</sup> כו', ולכן נא' בפ' זאת מתחילה לימוד התורה והוא ענין ודברת בם ואח\"כ וקשרתם שהוא ענין מעהמ\"צ וזהו בחי' ואלי'<sup data-n=\"5061\">82</sup> שהוא בחי' ההילוך דנשמות הגבוהות, אבל בפ' שני' הוא ענין ההילוך בבחי' אחוריים וחיצוני' מצד שאין להם התגלות בחי' רעו\"ד שנק' מאוד רק התחלת העבודה הוא בבחי' אתכפיא במעה\"מ, אך בחי' זאת מעורר למעלה גלוי הסובב בממלא [... אך להיותו בבחי' מקיף לכן אין אצלם בחי' רעו\"ד בבחי' גלוי ולכן נא'<sup data-n=\"5062\">83</sup> בכל מאודך בפ'",[["5052","73","<b>ואספת דגנך. . מעשה המצוות</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' קלב. תו\"ח וארא ח\"א פב, א."],["5053","74","<b>חרישא דמרפיא ארעא</b>: ראה מועד קטן ב, ב. לקו\"ת האזינו עה, ד. שה\"ש לח, ד. שע\"ת סג, ב ואילך."],["5054","75","<b>ירגיז אדם יצ\"ט על יצה\"ר</b>: ברכות ה, א. ראה תניא פכ\"ט. לקו\"ת שלח מא, א. מאמרי אדה\"ז תקע\"א ס\"ע רצז ואילך. מאמרי אדה\"א קונטרסים ע' שמו. תו\"ח בשלח ח\"א רכו, ב ואילך. וש\"נ."],["5055","76","<b>ורב תבואות בכח שור</b>: משלי יד, ד."],["5056","77","<b>ממשל האבוקה</b>: ראה גם לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 205. ביאוה\"ז ויצא קלב, ג. לקו\"ת במדבר ג, ג ואילך."],["5057","78","<b>אפשר אדם חורש</b>: ברכות לה, ב."],["5058","79","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה גם לעיל מאמר ד\"ה אם בחוקותי תר\"י ובהערה 32."],["5059","80","<b>ושננתם כו' ודברת בם</b>: ואתחנן שם, ז."],["5060","81","<b>וקשרתם</b>: שם ו, ח."],["5061","82","<b>ואל'</b>: כ\"ה בהכת\"י. ואולי צ\"ל: ואולך [אתכם קוממיות]."],["5062","83","<b>ולכן נא'</b>: כנצ\"ל: ולכן לא נא'."]]],[4801940482,"זאת] ובחי' זאת נק' אור חוזר ולכן בפ' זאת נא' בתחלה וקשרתם ואח\"כ ולמדתם<sup data-n=\"5063\">84</sup> כו'.\n<b>והנה</b> כמו שעכשיו יש ב' מיני הילוך בדרך או\"י ואו\"ח שמעורר בחי' א\"ס להתגלות בנשמה שהוא בבחי' אוב\"כ<sup data-n=\"5064\">85</sup> שזהו ענין גלוי הסובב בממלא דווקא ונק' מהלכים בין העומדים כנ\"ל כך לע\"ל יתגלה ב' מיני הילוך מלמעלה למטה כנגד ב' מיני הילוך אלו ואז יהי' הגלוי מעצמו' אוא\"ס עד שההילוך דעכשיו נק' עומד לגבי ההילוך דלע\"ל. ובאור הענין הנה כל מיני הילוך דעכשיו הוא התגלות מאצי' שזהו ג\"כ נק' הילוך להיות שאצי' הוא בחי' א\"ס לגבי בי\"ע כידוע דבאצי' איהו וגרמוהי חד אך לע\"ל יתגלה מעצמו' אוא\"ס בנאצלים [... כי גם בחי' אצי' הוא בחי' אוב\"כ לגבי עצמיות ונק' עומדים לגבי הגלוי דעצמיות אא\"ס שנק' מהלכים כמא' ילכו מחיל אל חיל<sup data-n=\"5065\">86</sup> ואין להם מנוחה בעוה\"ב<sup data-n=\"5066\">87</sup> כו'] והגילוי יהי' ג\"כ בב' אופנים דאו\"י ואו\"ח כמו ההילוך דעכשיו אך הילוך דלע\"ל יתגלה ג\"כ בבחי' עומדים שהוא ההילוך דעכשיו להיות שההילוך דעכשיו הוא המעורר הגילוי דלע\"ל לכן בו יתגלה, וזהו והתהלכתי בתוככם והתהלכתי דווקא שהגילוי יהי' מעצמו' המאציל שלמעלה מבחי' הצמצום בשביל להאציל ע\"ס דאצי' [... שזהו ענין גלוי נשמות חדשות שיתגלו לע\"ל], והיכן יהי' ההילוך שלי בתוככם דווקא [... היינו שגילוי נשמות החדשות יתגלו בנשמות דעכשיו כו'], ואח\"כ אמר ואולך אתכם קוממיות הוא בחי' מאה אמה<sup data-n=\"5067\">88</sup> כי עכשיו אינו נחשב רק שבע היכלות כי הגילוי אינו רק מבחי' בינה ובה נכללי' ג\"ר<sup data-n=\"5068\">89</sup> בהעלם אבל לע\"ל יבואו כל הג\"ר מהעלם אל הגילוי כ\"א במדרגה בפ\"ע [... ויתגלה גם החכ' וכתר וזהו אראנו נפלאות ב'<sup data-n=\"5069\">90</sup> כתר וחכ' כו' וד\"ל] וכאשר כל הע\"ס וכ\"א כלול מי' זהו ענין הקומה דמאה אמה, אך גלוי זה מעוררים עכשיו במאה ברכות שחייב אדם לברך<sup data-n=\"5070\">91</sup> בכל יום וכמבואר בזוהר שיש שם הוי' ברבוע בחי' מקום<sup data-n=\"5071\">92</sup> כי היוד בכפל עם ו\"ד בגי' קוף<sup data-n=\"5072\">93</sup> וזהו מעוררים<sup data-n=\"5073\">94</sup> ה' פ\"ה הוא כ\"ה אתוון דיחו\"ע שמע\"י ובה' אחרונה ג\"כ כנ\"ל הוא כ\"ד אתוון",[["5063","84","<b>וקשרתם. . ולמדתם</b>: עקב יא, יח. יט."],["5064","85","<b>אוב\"כ</b>: (תיבה זו איננה ברורה בהכת\"י) אור בכלי."],["5065","86","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["5066","87","<b>ואין להם מנוחה בעוה\"ב</b>: ראה ברכות בסופה. ראה גם תו\"ח שמות ח\"א ד, ג. וש\"נ."],["5067","88","<b>מאה אמה</b>: ב\"ב עה, א. סנהדרין ק, א. ראה גם לקו\"ש בחוקותי כרך ז ע' 198 ואילך."],["5068","89","<b>שבע היכלות. . ג\"ר</b>: ראה ע\"ח שער כסא הכבוד שמ\"ו, פ\"א. פ\"ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתה (ובנו\"ש ע' תתו) ואילך."],["5069","90","<b>אראנו נפלאות ב'</b>: ראה גם לעיל ע' עח. פלח הרמון יתרו ע' רנה. תו\"ח שמות ח\"א כא, א. וש\"נ."],["5070","91","<b>במאה ברכות שחייב אדם לברך</b>: מנחות מג, ב. ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["5071","92","<b>בזוהר. . הוי'. . מקום</b>: באוה\"ת בחוקותי כאן ע' תרעו: בספרים. יחזקאל כרך א' ס\"ע תא: ת\"ז תכ\"ו [עא, ב]. ושם: י' עשר זמנין מאה, ה' חמש זמנין עשרים וחמש, ו' שית זמנין תליתן ושית, ה' חמש זמנין עשרים וחמש, בגימטריא מקום."],["5072","93","<b>כי היוד בכפל עם ו\"ד בגי' קוף</b>: כ\"ה בהכת\"י. ראה הערה שלפנ\"ז."],["5073","94","<b>וזהו מעוררים</b>: אולי תיבות אלו הם ע\"ד התיבות דשורה הבאה ונסרחו משם."]]],[4801940516,"דבשכמל\"ו<sup data-n=\"5074\">96</sup> עם הכולל הוא כ\"ה אתוון דיחו\"ת<sup data-n=\"5075\">95</sup>, ופ\"ו ל\"ו הוא שית ס'<sup data-n=\"5076\">97</sup> משנה<sup data-n=\"5077\">98</sup>, שבכ\"ז מעוררים לע\"ל שיתגלה שם הוי' שהוא למעלה מבחי' מקום בבחי' מקום וזהו ואולך אתכם קוממיות כו' וד\"ל.",[["5074","96","<b>דבשכמל\"ו</b>: פסחים נו, א."],["5075","95","<b>דיחו\"ע שמע\"י. . דבשכמל\"ו. . דיחו\"ת</b>: זהר בראשית יח, ב."],["5076","97","<b>ופ\"ו ל\"ו הוא שית ס' משנה</b>: אולי הכוונה ו'. . שית סדרי משנה. או ופ\"ו ל\"ו שכל סדר כלול מששה־ ל\"ו מסכתות — ראה תו\"ח פקודי ח\"ב תמט, ב."],["5077","98","<b>שית ס' משנה</b>: ראה זהר בראשית מב, א. במד\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. לקו\"ש בשלח כרך יא ע' 56 הערה 13."]]],[4801940132,"<b>[פ' וישלח תר\"ב]</b>\n<b>להבין</b> ענין המבואר לעיל<sup data-n=\"5078\">1</sup> שבמשה הי' בחי' אחוריים וחיצוני' כמאמר וראית את אחורי<sup data-n=\"5079\">2</sup> ובאברהם הי' הילוך פנימי כמאמר התהלך לפני<sup data-n=\"5080\">3</sup>, ואיך יתכן זה הלא בחי' משה הוא למעלה מבחי' אברהם כמאמר ושמי הוי' לא נודעתי להם<sup data-n=\"5081\">4</sup> ולמשה נתגלה ע\"י נתינת התורה. והנה קושיא זאת יתורץ בב' אופנים ושניהם אמיתים, הא' שיש הפרש בין הילוך לראי' כי<sup data-n=\"5082\">5</sup> הנה לכאורה יש לתמוה<sup data-n=\"5083\">6</sup> מה שמצינו בענין הנביאים שיחזקאל נדמה לבן כפר<sup data-n=\"5084\">7</sup> כו'<sup data-n=\"5085\">8</sup> נבואתו הי' בעולם היצירה<sup data-n=\"5086\">9</sup>, וישעי' לבן כרך<sup data-n=\"5087\">10</sup> מצד שנבואתו היתה בבריאה<sup data-n=\"5088\">11</sup> ונבואת משה הוא למעלה מכל הנביאים בזה הדבר<sup data-n=\"5089\">12</sup> כי",[["5078","1","<b>להבין ענין המבואר לעיל</b>: הנחת ר' הלל מדרוש הצ\"צ.\nמאמר זה הוא ביאור על המאמר שנדפס לפנ\"ז.\nלמאמר זה ראה ד\"ה והתהלכתי במאמרי אדה\"ז הנחות הר\"פ ע' קנח־ תקס\"ט ע' קמ־ מאמרי אדה\"א ויקרא ח\"ב ע' תתסו (ובהנסמן בראשי המאמרים שם)־ אוה\"ת ויקרא כרך ב ע' תרעג."],["5079","2","<b>וראית את אחורי</b>: תשא לג, כג."],["5080","3","<b>התהלך לפני</b>: לך יז, א."],["5081","4","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג."],["5082","5","<b>כי</b>: אולי כתוב: כו'."],["5083","6","<b>לכאורה יש לתמוה</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' רעז ואילך. ע' רפד ואילך. ס' המצות להצ\"צ ע' 344 ואילך. אוה\"ת תשא ע' ב'מא. ירמי' כרך ב' ע' תתפז. מאמרי אדה\"א הנחות תקע\"ז ע' כב ואילך ובהנסמן בריש המאמר שם. תו\"ח בא ח\"א צח, א ואילך (ובהנסמן בריש המאמר שם). המשך וככה תרל\"ז פנ\"ו ע' פד. סה\"מ תרמ\"ז ע' קכה ואילך."],["5084","7","<b>שיחזקאל נדמה לבן כפר</b>: חגיגה יג, ב. ראה גם המשך זאת חנוכת תר\"ם פ\"ג. וש\"נ."],["5085","8","<b>כו'</b>: אולי כ\"ה בהכת\"י."],["5086","9","<b>נבואתו הי' בעולם היצירה</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ב. מאמרי אדה\"א נ\"ך ע' קמא. וש\"נ. תו\"ח בא ח\"א קיד, סע\"ג. ובהערה 194. ולהעיר מויקהל משה [זאלקווא תקל\"ה ו, א — ראה אודותיו אוה\"ת בלק ע' תתקפה]. תו\"א משפטים עח, ב : בריאה."],["5087","10","<b>וישעי' לבן כרך</b>: חגיגה שם. המשך זאת חנוכת שם."],["5088","11","<b>וישעי'. . בבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. תו\"ח בא ח\"א קיד, סע\"ג. וש\"נ."],["5089","12","<b>ונבואת משה. . בזה הדבר</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. תו\"ח בשלח ח\"א קמד, ב הערה 29."]]],[4801940196,"נבואתו היתה באצי'<sup data-n=\"5090\">13</sup> אך לא הגיע מדריגת נבואתו רק לבחי' נו\"ה דאצי' וגם זאת ע\"י התלבשות בבריאה וא\"כ יש לתמוה איך שרשב\"י בזוהר גילה כל הפרצופים עליונים עד בחי' פרצופים שבכתר שהם בחי' עת\"י וא\"א, והאריז\"ל גילה עוד למעלה מן הכתר [שהוא בחי' א\"ק<sup data-n=\"5091\">14</sup>, ובוודאי לא הי' למעלה מבחי' מרע\"ה כו'. אך הענין הוא שיש הפרש בין ידיעה והשגה לבחי' ראי', שבחי' ידיעה והשגה אינו רק מציאת הדבר ולא מהותו משא\"כ הראי' הוא התגלות עצם המהות שנגלה לעין הרואה כו', וזהו ההפרש בין כל החכמים בפרצופים העליונים שבבחי' עולמות הנעלמים שאינם רק משיגים ויודעים רק המציאות, והיינו שמשיגים בשכלם שיש בחי' פרצופים כאלה אבל מהות הפרצופים לא נגלה אצלם כלל ולכן יכולים להשיג במקום יותר עליון מהנביאים, משא\"כ גילוי הנבואה הוא התגלות המהות וכמאמר ואראה את ה'<sup data-n=\"5092\">15</sup> וכן וירא אליו ומתרגמינן ואתגלי' לי'<sup data-n=\"5093\">16</sup>, ולכן לא הי' יכול להתגלות בכלים שלהם רק ממקום נמוך ביותר, ולכן חכם עדיף מנביא<sup data-n=\"5094\">17</sup> כי בחכמתו יכול להשיג במקום עליון יותר אבל בעצם מהות הגלוי אין ערך כלל מגלוי החכמה לגלוי הנבואה כי גלוי החכמה אינו רק השגת מציאות הדבר אבל הנבואה הוא בחי' גלוי המהות כנ\"ל וד\"ל. אך גם בידיעת המציאות יש ג\"כ ב' אופנים הא' בחי' הידיעה והשגת המציאות בלבד והב' בחי' הרגשת המציאות עד שנעשה לחיות בקרבו כמו איברי הגוף שאינם יודעים במהות הנפש רק במציאות הנפש, אבל ידיעת מציאות הנפש הוא בבחי' הרגשה בהם עד שהרגשה זאת הוא מחי' אותם ממש כו'.\n<b>ובזה</b> יובן ענין ההפרש בין הילוך דאברהם לבחי' ראי' דמשה כי ענין ההילוך דאברהם אינו בחי' ראי' והתגלות רק בחי' התעוררות שיתעורר מלמטה למעלה ועי\"ז יגיע לבחי' פנימי' להמשיך הפנימי' שלמעלה למטה בבחי' התגלות, וזהו התהלך לפני וענין התעוררות שלו הוא ע\"י ידיעת המציאות בבחי' אא\"ס כידוע דאא\"ס ידוע מציאותו ולא מהותו<sup data-n=\"5095\">18</sup>, אך ידיעה זאת נקלטה בבחי' הרגשה ממש עד שנתפעל מזה באהבה ותשוקה להתמשך אחרי אלקות בכל לב ונפש בתמידיות בלי הפסק כלל [כמאמר זכור אב הנמשך אחריך כמים<sup data-n=\"5096\">19</sup> כו'], והנה התפעלות זאת הוא בחי' אתעדל\"ת לעורר בחי' אתעדל\"ע<sup data-n=\"5097\">20</sup> מבחי' פנימי' ומטעם הנ\"ל דידיעת המציאות יכול להיות במקום עליון ביותר, אבל בחי' הראי' דמשה הי' בבחי' התגלות ממש,",[["5090","13","<b>ונבואת משה. . היתה באצי'</b>: ראה תו\"א בא ס, ב. לקו\"ש שמות כרך ו ע' 251 ואילך. וראה גם לקו\"ת נצבים מט, ב."],["5091","14","<b>א\"ק</b>: אוצ\"ל: א\"ק]."],["5092","15","<b>ואראה את ה'</b>: ישעי' ו, א."],["5093","16","<b>וירא. . ואתגלי' לי'</b>: וירא יח, א ובת\"א [ושם: ואתגלי]."],["5094","17","<b>חכם עדיף מנביא</b>: ב\"ב יב, א. ראה לקוטי הש\"ס להאריז\"ל סוף מס' יבמות. וראה גם לקו\"ת פקודי ו, ד. ויקרא ה, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. תו\"ח שמות ח\"א נט, א ובהערה 39. המשך וככה תרל\"ז פל\"ז ע' מד. פקפ\"ט ע' רטו."],["5095","18","<b>דאא\"ס ידוע מציאותו ולא מהותו</b>: ראה לקו\"ת בחוקותי נ, ג. מאמרי אדה\"א הנחות תקע\"ז ע' סח. מאמרי אדהצ\"צ ע' צד. ע' רה. המשך תער\"ב ח\"א ע' סח."],["5096","19","<b>זכור אב הנמשך אחריך כמים</b>: תפלת גשם [ושם: נמשך]. ראה גם המשך תער\"ב ח\"ג ע' א'רפט."],["5097","20","<b>אתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. תו\"ח שמות ח\"א מא, א ובהערה 189."]]],[4801940253,"והיינו גילוי כל הפרצופים העליונים דאצי' בבחי' המהות שלהם לזאת לא יכול להתגלות הפנימי' מהם רק בחי' החיצוני' שלהם, וזהו בחי' נה\"י דאצי' כו' כי נה\"י הוא לבר מגופא<sup data-n=\"5098\">21</sup> שאינו עצמות ומהות הדבר רק גלוי הדבר לזולתו אך הגלוי הזה הוא בחי' גלוי העצם וזהו וראית את אחורי ופני לא יראו כי הפנימי' לא יכול לבוא בבחי' התגלות המהות כו' וד\"ל.\n<b>והתירוץ</b> הב' הוא שיש כמה מדריגות בבחי' פנים עד שיכול להיות שמה שהוא פנים בבחי' מדריגה התחתונה הוא למטה מבחי' אחוריים וחיצוני' שבמדריגה עליונה [וכידוע דמבחי' חיצוני' שבעליון נעשה פנימי' לתחתון<sup data-n=\"5099\">22</sup> ע\"י צמצום]. וביאור הדברים הנה בחי' פנים הוא בחי' מוחין והנה עצם המוחין הוא בראש ובהם משכן והשראת עצם החכמה ובינה ודעת שלמעלה מהיות מקור למדות, והנה גם בבחי' עצמיות השכל יש בחי' פנימי' ובחי' חיצוני' כו', בחי' פנימי' החכמה הוא עומק השכל כמ\"ש נמצא ממקורו שהוא כח המשכיל שהוא בחי' אין כמ\"ש והחכמה מאין תמצא<sup data-n=\"5100\">23</sup> כו' ובחי' חיצוני' החכמה הוא בחי' התגלותו במוח החכמה בבחי' יש בבחי' אותיו' קצרים, וכן בבחי' בינה עומק ההשגה הוא בחי' תמצית המושג הוא בחי' אין של היש דבינה זהו בחי' פנימי' שבה וחיצוני' שבה הוא כאשר מתגלית במוח ההשגה בבחי' התיישבות שזהו בחי' יש, והנה מעצמיות החו\"ב נעשה בחי' התפעלות במוח עצמו שזהו בחי' מדות שבשכל ומבחי' המדות שבשכל נמשך הארה בעלמא במדות שבלב ונק' בחי' מוחין שבמדות שזהו בחי' פנים לגבי מדות שבלב והמדות עצמן הם בחי' חיצוני' ואחוריים לגבי המוחין שבהם, ונמצא שבחי' אחוריים שבחו\"ב עצמן הן למעלה הרבה מבחי' הפנים שבמדות, וכן עד\"ז אנו מוצאין שמתפשט הארת השכל בידים, חסד דרועא ימינא<sup data-n=\"5101\">24</sup> כו', כי ידוע שבידים יש ג' פרקים<sup data-n=\"5102\">25</sup> ראשי אצבעות שביד הוא בחי' פרק העליון חב\"ד שבהם שזהו בחי' פנים לגבי בחי' חג\"ת ונה\"י שביד שהם פרקי הזרועות והכתפיים ולכן יכול לכתוב בהם דבר שכל ואעפ\"כ הפנימי שבהם הוא למטה הרבה אפי' מבחי' אחוריים וחיצוני' השכל שבמוח עצמם כו'.\n<b>והדוגמא</b> מזה יובן בענין ההפרש בין משה לאברהם שמה שנאמר באברהם התהלך לפני היינו בחי' פנימי' שבמדות כידוע דאברהם אע\"ה הי' עבודתו והילוכו בקודש בבחי' האהבה כמאמר הלוך ונסוע הנגבה<sup data-n=\"5103\">26</sup> והתפעלות שלו הי' מצד ההשגה בעילוי אחר עילוי בבחי' אא\"ס עד שמחמת נמשך<sup data-n=\"5104\">27</sup> ונדבק אחרי ה'",[["5098","21","<b>נה\"י הוא לבר מגופא</b>: ראה ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, רפ\"ד."],["5099","22","<b>חיצוני' שבעליון. . לתחתון</b>: ראה ע\"ח שער א\"א שי\"ד, פ\"ט. לקו\"ת שלח מא, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ח ח\"א ע' תלז ואילך."],["5100","23","<b>והחכמה מאין תמצא</b>: איוב כח, יד."],["5101","24","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה יז, א."],["5102","25","<b>שבידים יש ג' פרקים</b>: ראה זהר ויחי רמא, א. לעיל ע' שכח. ביאוה\"ז במדבר פה, א. שה\"א פנ\"ה פז, א ובהערה 16."],["5103","26","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר לך פ, א. פד, א. וראה גם לעיל ע' קמט הערה 4. ע' רצט."],["5104","27","<b>שמחמת נמשך</b>: אוצ\"ל: שמחמת זה נמשך."]]],[4801940306,"כנ\"ל, ונק' רחימא דמלכא<sup data-n=\"5105\">28</sup>, וזהו בחי' פנימי' הביטול שלו ומחמת זה הי' עסקו בחיצוני' בבחי' חסד להאכיל אפי' לערביים<sup data-n=\"5106\">29</sup> ולהודיעם שם ה' כמ\"ש ויקרא שם בשם ה'<sup data-n=\"5107\">30</sup> כו', וגם זה נמשך מבחי' השגה שלו באלקי' חיים עד שנעשה רחימא דמלכא לכן מדתו הי' להיטיב כו' [... כידוע דאהבה הוא בחי' פנימי' המדה בלב ומזה נמשך בחי' חסד בחיצוני' בדרועא ימינא להיטיב לכל כו'], ונמצא שבחי' פנים שלו הי' בחי' פנים שבמדות בפנימי' וחיצוני' הנק' חסד דרועא ימינא כו', וזהו ענין ההילוך שלו שהוא בחי' התעוררות שלו מלמטה למעלה כנ\"ל, ועז\"נ התהלך לפני שהילוך זה בחי' העלאה מלמטה למעלה נתעוררו ע\"י בחי' פנים העליונים שבבחי' אצי', אך לא הגיע רק עד בחי' המוחין שבמדות העליונים שבאצי' בפנימי' שלהם וגם בחיצוני' הנק' חסד דרועא ימינא, אבל מה שנאמר במשה רבינו ע\"ה וראית את אחורי היינו בחי' אחוריים וחיצוני' עצמי' החו\"ב דאצי' שזהו בחי' התורה שנתנה ע\"י כידוע דאורייתא מחכ\"ע נפקא<sup data-n=\"5108\">31</sup>, עילאה דווקא למעלה הרבה משרש ומקור המדות שהם מקור ההשתלשלות, ונמצא לפי חשבון זה גם בחי' הראי' דמשה שהייתה בחי' ראיית המהות הגיע למעלה ממדריגת ההילוך דאברהם הגם שלא היתה רק בחי' ידיעת המציאות בלבד כו'.\n<b>אך</b> להבין מהו בחי' פנים שנאמר גבי משה שעז\"נ ופני לא יראו<sup data-n=\"5109\">32</sup>, י\"ל ענין במקום שבע\"ת עומדין<sup data-n=\"5110\">33</sup> אין צדיקים גמורים יכולים לעמוד כידוע דבע\"ת משכין לי' בחילא יתיר<sup data-n=\"5111\">34</sup> כו'. ולהבין ההפרש בין מקום דבע\"ת למקום דצ\"ג ששניהם הם בבחי' מקום, רק שבע\"ת הם במקום יותר גבוה כו'. אך הנה ידוע שיש ב' בחי' בבחי' מקום הא' בבחי' ממכ\"ע שנק' בחי' מקום כידוע דמקום הוא בחי' מיצר המגביל למעלה ולמטה ולד' רוחות<sup data-n=\"5112\">35</sup> העולם מזרח ומערב צפון ודרום, והנה כ\"ה למעלה ברוחני' יש בחי' י\"ב מלאכים הנושאים את הכסא<sup data-n=\"5113\">36</sup> שהם ד' מחנות שכינה<sup data-n=\"5114\">37</sup> כ\"א כלול מג'<sup data-n=\"5115\">38</sup>,",[["5105","28","<b>רחימא דמלכא</b>: זהר ואתחנן רסב, ב. ראה מאמרי אדה\"א שמות ח\"ב ע' שמג. וש\"נ."],["5106","29","<b>להאכיל אפי' לערביים</b>: ראה ב\"מ פו, ב. תו\"ח לך פג, ד הערה 57."],["5107","30","<b>ויקרא שם בשם ה'</b>: וירא כא, לג."],["5108","31","<b>דאורייתא מחכ\"ע נפקא</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["5109","32","<b>ופני לא יראו</b>: המשך הכתוב וראית את אחורי — תשא לג, כג."],["5110","33","<b>במקום שבע\"ת עומדין</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. אוה\"ת בחוקותי כאן ע' תרעה ואילך. לעיל ע' שפ. לעיל מאמר ד\"ה אם בחוקותי הג' על יד הערה 140."],["5111","34","<b>דבע\"ת. . בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ. לעיל ע' קפח ואילך."],["5112","35","<b>דמקום הוא. . למעלה ולמטה ולד' רוחות</b>: ראה שער היחוד והאמונה פ\"ז ובמ\"מ הגהות והע\"ק שם. לקו\"ת בחוקותי מח, ב. מאמרי אדה\"א שמות ח\"א ע' קסז (ובהנסמן בריש המאמר שם). שע\"ת קכה, ג."],["5113","36","<b>י\"ב מלאכים הנושאים את הכסא</b>: ראה זהר ויצא קמז, ב ואילך (הובא בסמוך בפנים)."],["5114","37","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["5115","38","<b>ד' מחנות שכינה כ\"א כלול מג'</b>: ראה לקו\"ת צו יז, רע\"א. בלק סח, ג. ביאוה\"ז במדבר פה, א ואילך. שה\"א ע' פז ואילך."]]],[4801940356,"מחנה מיכאל לימין וכן פני ארי'<sup data-n=\"5116\">39</sup>, והימין זהו בחי' דרום, וכן מחנה גבריאל ופני שור<sup data-n=\"5117\">41</sup> להשמאל הוא בחי' צפון וכן ופני נשר<sup data-n=\"5118\">40</sup> כו' וזהו מש\"א בזוהר ויצא ע\"פ ויקח מאבני המקום<sup data-n=\"5119\">42</sup> שזהו ענין י\"ב מלאכים הנ\"ל. והנה מקור בחי' מקום הנ\"ל הוא בחי' כח האלקי המגביל שעושה בחי' מקום וזהו בחי' מל'<sup data-n=\"5120\">43</sup> דאצי' שהוא בחי' מקום האמתי [... וי\"ב מלאכים נק' אבני המקום כו', ולפע\"ד הוא בחי' פנימי' הכלים די\"ס דבי\"ע המגבילים את האור האלקי הבל\"ג שרשו ג\"כ בחי' אלקות כידוע דהמגביל לבחי' בלי גבול הוא כח הבלתי מוגבל<sup data-n=\"5121\">44</sup> כו', ומחמת זה ממילא נתהוו בחי' מקום בבחי' הנבראים כו']. ועז\"א רז\"ל הוא מקומו של עולם<sup data-n=\"5122\">45</sup> ובחי' זאת נק' ממכ\"ע שהוא בחי' כח המגביל לאור האלקי בכל עולם במדה ושיעור לפי\"ע כו', ובחי' הב' בבחי' מקום הוא בחי' סוכ\"ע<sup data-n=\"5123\">46</sup>.\n<b>וביאור</b> הדברים ע\"ד שאנו רואים במקום הגשמי בכלי גשמי' שמדת הכלי היא מקומה המגבילה אבל האויר המקיף הכלי ונושא וסובל אותה הוא בחי' מקום שהוא יתר ממדת הכלי וכמארז\"ל אמתא באמתא היכי יתיב<sup data-n=\"5124\">*47</sup> כו', ועד\"ז גם ברוחני' בחי' סוכ\"ע הוא המקיף לאור וחיות הממכ\"ע עם גוף העולמות והוא כח הנושא וסובל את כל העולמות עם האור וחיות שבהם והוא קיומם האמתי והוא בחי' בינה מקור כל המקיפים<sup data-n=\"5125\">47</sup> כו' [... ושמעתי מבנו<sup data-n=\"5126\">48</sup> שיחי' משמו שפ\"א אמר שלמעלה יותר הוא בחי' צמצום ומקיף<sup data-n=\"5127\">49</sup> ולפ\"ז מקום דממכ\"ע הוא בחי' הקו\"ח שעושה בחי' מעלה ומטה<sup data-n=\"5128\">50</sup> כמבואר בע\"ח כו'], ועל בחי' זאת אמר משרע\"ה אדני מעון אתה היית לנו<sup data-n=\"5129\">51</sup> כו' בטרם הרים יולדו<sup data-n=\"5130\">52</sup>, שהוא בחי' המדות דממכ\"ע שנק' בחי' הרים<sup data-n=\"5131\">53</sup> כו', ומעון אותיו' נועם<sup data-n=\"5132\">54</sup> שהוא בחי' בינה כו'. והנה זהו ההפרש בין צד\"ג לבע\"ת",[["5116","39","<b>מיכאל. . פני ארי'</b>: ראה זהר בראשית כג, ב. רע\"מ בא מב, א. צו לג, א. בהעלותך קנד, א. פינחס ריז, א. ת\"ז תכ\"א סב, ב. ת\"ע קכו, א. ז\"ח יתרו לא, ב. לב, סע\"ב. תז\"ח צה, ג."],["5117","41","<b>גבריאל ופני שור</b>: ראה זהר בראשית כג, ב. רע\"מ בא מב, א. נשא קכא, ב. בהעלותך קנד, ב. פינחס ריז, א. ת\"ז ת\"ע קכו, א. ז\"ח יתרו לא, ב. לב, סע\"ב."],["5118","40","<b>פני ארי'. . ופני שור. . ופני נשר</b>: יחזקאל א, י."],["5119","42","<b>בזוהר ויצא ע\"פ ויקח מאבני המקום</b>: קמז, ב ואילך. ויצא כח, יא."],["5120","43","<b>מקור בחי' מקום. . מל'</b>: ראה שער היחוד והאמונה פ\"ז."],["5121","44","<b>דהמגביל לבחי' בלי גבול הוא כח הבלתי מוגבל</b>: ראה גם תו\"ח מקץ רכא, ד ואילך."],["5122","45","<b>הוא מקומו של עולם</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2. לעיל בהמאמר הערה 45."],["5123","46","<b>ובחי' הב' בבחי' מקום. . סוכ\"ע</b>: ראה לקמן מאמר ד\"ה והתהלכתי בתוככם תרט\"ו פיסקא אך מבואר במ\"א ואילך."],["5124","*47","<b>אמתא באמתא היכי יתיב</b>: פסחים קט, ב כגי' התוס'."],["5125","47","<b>בינה מקור כל המקיפים</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["5126","48","<b>מבנו</b>: של כ\"ק אדמו\"ר הצ\"צ."],["5127","49","<b>ומקיף</b>: תיבה זו איננה ברורה בהכת\"י."],["5128","50","<b>הקו\"ח. . מעלה ומטה</b>: ראה ע\"ח שער עגו\"י ש\"א, ענף ב. שעה\"י קכ, ב הערה 9."],["5129","51","<b>אדני מעון אתה הייתה לנו</b>: תהלים צ, א."],["5130","52","<b>בטרם הרים יולדו</b>: תהלים שם, ב."],["5131","53","<b>המדות. . הרים</b>: ראה זהר סבא משפטים קט, ב ובמפרשים שם. תו\"ח שמות ח\"א יד, ד הערה 642."],["5132","54","<b>ומעון אותיו' נועם</b>: ראה לקו\"ת להאריז\"ל לתהלים שם. מאמרי אדה\"א ויקרא ח\"א ע' רא וש\"נ. תו\"ח נח נה, ב ובהערה 16."]]],[4801940402,"ששניהם הם בבחי' עושין רצונו של מקום, אך בחי' צדיקים גמורים עושין וממשיכין מבחי' רצה\"ע שהוא בחי' סוכ\"ע בממכ\"ע הנק' בחי' מקום, ונמצא שכל עבודתם הוא לפעול בחי' גלוי הסובב בממלא, והם<sup data-n=\"5133\">55</sup> עושין וממשיכין בחי' עצמיות אוא\"ס שלמעלה מבחי' סובב וממלא להאיר בבחי' מקום דסובב וממלא שזהו בחי' אור חדש לגמרי שאינו בבחי' כלל ופרט עדיין [... והיינו משום דבע\"ת הם בבחי' מאנין תבירין לכן בבחי' הכלים שלהם שהוא בחי' מקום שלהם שורה בחי' מקום הב' דסוכ\"ע וכמאמר מדורא דקוב\"ה באינון מאנין תבירין<sup data-n=\"5134\">56</sup> והאור העצמי' כו'].\n<b>וזהו</b> אנכי אנכי<sup data-n=\"5135\">57</sup> הוא מוחה פשעיך למעני כי בצ\"ג נאמר אשר אנכי מצווך היום<sup data-n=\"5136\">58</sup> שע\"י האהבה דבכל מאודך שהוא בחי' אהבה שלמעלה מבחי' הכלי שלהם בזה עושין רצונו כו' ומעוררים בחי' סוכ\"ע שלמעלה מבחי' אוב\"כ<sup data-n=\"5137\">59</sup> להאיר בבחי' הכלי' כנ\"ל בתו'<sup data-n=\"5138\">60</sup>, וזהו אנכי בחי' סוכ\"ע מצווך לבא בבחי' צוותא והתחברות<sup data-n=\"5139\">61</sup> להאיר בכלים והוא ע\"י אהבה דבכל מאודך שהזכיר מקודם, אך בבע\"ת נאמר אנכי אנכי שהוא בחי' המשכה מבחי' אנכי ה\"א שהוא בחי' עצמות אא\"ס להאיר באנכי הב' דבחי' סוכ\"ע בבחי' אור חדש ועי\"ז הוא מוחה פשעיך עד שזדונות נעשו כזכיות<sup data-n=\"5140\">62</sup> כו' וד\"ל. וזהו ג\"כ שלום שלום לרחוק ולקרוב<sup data-n=\"5141\">63</sup> לרחוק שנעשה קרוב<sup data-n=\"5142\">64</sup> כו', קרוב הוא בחי' ממכ\"ע שנושא וסובל כל העולמות כנ\"ל משא\"כ בחי' העצמיות הוא למעלה מגדר עולמות לגמרי נק' רחוק כמאמר אחכמה והיא רחוקה ממני<sup data-n=\"5143\">65</sup> ובחי' זאת נעשה קרוב להאיר בסו\"מ כו' ולכן ארז\"ל דרשו ה' בהמצאו<sup data-n=\"5144\">66</sup> זהו עשי\"ת ואז קראוהו בהיותו קרוב מצד התשובה מעומקא דלבא שבימים ההם כו', וזהו שלום שלום כפולה כי שלום הוא בחי' יסוד<sup data-n=\"5145\">67</sup> שנק' צדיק<sup data-n=\"5146\">68</sup> דאחיד בשמיא וארעא<sup data-n=\"5147\">69</sup> לחבר ההעלם דסוכ\"ע לידי גלוי דממכ\"ע ונק' טוב<sup data-n=\"5148\">70</sup> וכמאמר אמרו צדיק כי טוב<sup data-n=\"5149\">71</sup> כו' אבל שלום הב' הוא בחי' בע\"ת שזהו לרחוק שנעשה קרוב והוא המייחד ומחבר בחי' העצמי' בסוכ\"ע וממכ\"ע כו' וד\"ל.",[["5133","55","<b>והם</b>: הבע\"ת."],["5134","56","<b>מדורא דקוב\"ה באינון מאנין תבירין</b>: ראה זהר ויקהל ריח, א. ש\"א צא, ב."],["5135","57","<b>אנכי אנכי</b>: ישעי' מג, כה."],["5136","58","<b>אשר אנכי מצווך היום</b>: ואתחנן ו, ו."],["5137","59","<b>אוב\"כ</b>: אור בכלי."],["5138","60","<b>כנ\"ל בתו'</b>: בפיסקא וביאור הענין יובן ואילך."],["5139","61","<b>מצווך. . צוותא והתחברות</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתפ ואילך. תו\"ח נח סג, ב ובהערה 28."],["5140","62","<b>שזדונות נעשו כזכיות</b>: ראה יומא פו, ב."],["5141","63","<b>שלום שלום לרחוק ולקרוב</b>: ישעי' נז, יט."],["5142","64","<b>לרחוק שנעשה קרוב</b>: ראה ברכות לד, ב. אוה\"ת ישעי' כרך א ע' רעג."],["5143","65","<b>אחכמה והיא רחוקה ממני</b>: קהלת ז, כג."],["5144","66","<b>דרשו ה' בהמצאו</b>: ישעי' נה, ו. ר\"ה יח, א."],["5145","67","<b>שלום הוא בחי' יסוד</b>: ראה זהר בחוקותי קטו, ב. במדבר קיח, א ובהגהות מהרח\"ו שם. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקמ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' רכו. וש\"נ. תו\"ח וישלח קצד, ב."],["5146","68","<b>יסוד שנק' צדיק</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ח מערכת צדיק. מאו\"א מערכת צדיק אות ז."],["5147","69","<b>דאחיד בשמיא וארעא</b>: ראה דהי\"א כט, יא. זהר בראשית לא, א. ת\"ז תמ\"ז פד, א: ותרגום יונתן. מאמרי אדה\"א ויקרא ח\"ב ע' תשמב. וש\"נ."],["5148","70","<b>יסוד. . טוב</b>: ראה זהר נח ס, א. מאמרי אדה\"א קונטרסים ע' רכד. וש\"נ."],["5149","71","<b>אמרו צדיק כי טוב</b>: ישעי' ג, י."]]],[4801940445,"<b>ועם</b> כל הנ\"ל יובן ענין ההפרש בין שבת ליו\"ט, כי יו\"ט הוא בחי' אחת עם צד\"ג ולכן נק' יום טוב שטוב הוא בחי' התחברות מבחי' סוכ\"ע לממכ\"ע כנ\"ל והיינו מלמעלה מן הזמן בבחי' הזמן שהוא בחי' יומין דחול [כי שרש הזמן הוא ג\"כ בבחי' ממכ\"ע וכמבואר למעלה במ' של הפרש בין שבת ליו\"ט<sup data-n=\"5150\">72</sup> ], אבל בחי' שבת אותי' תשב<sup data-n=\"5151\">73</sup> הוא בחי' אחת עם בע\"ת כי שבת נק' קודש<sup data-n=\"5152\">74</sup> בעצם שלמעלה מבחי' קדוש<sup data-n=\"5153\">75</sup> והוא בחי' סוכ\"ע בעצם שלמעלה מבחי' הגלוי דסובב בממלא, ויש בחי' שבת שבתון<sup data-n=\"5154\">76</sup> שהוא בחי' הארה מבחי' העצמיות לבחי' הסוכ\"ע. כי כמו שביו\"ט יש כמה מדריגות עד רום המעלות, והיינו בחי' אותם במועדם ומתורגם בזמניהן<sup data-n=\"5155\">77</sup> כו' והוא בחי' המשכה מבחי' המדות לבחי' מל', ויש בחי' מועדי הוי'<sup data-n=\"5156\">78</sup> שהוא ההתחברות מחכ' לבינה ובחי' אלה הם<sup data-n=\"5157\">79</sup> הוא בחי' ההתחברות ממדות שברצון שלמעלה מן החכמה הנק' ימי קדם<sup data-n=\"5158\">80</sup> לבחי' חכ', וזהו עושין רצש\"מ<sup data-n=\"5159\">81</sup> מבחי' רצה\"ע שלמעלה מן החכ' לבחי' מקום שהוא בחי' המל', אך כל בחי' המשכות דיו\"ט הוא מבחי' מדות שברצון, כ\"ה בבחי' החכמה בעצם שהוא בחי' שבת יש בחי' חכמה הגלויה ויש בחי' חכמה נעלמה בעצמי' הרצון שזהו בחי' שבת שבתון וההמשכה מבחי' זאת הוא בחי' תשובה כו' כי התשובה אינו מן החטא דווקא<sup data-n=\"5160\">82</sup> רק כאשר הרוח תשוב אל האלקים<sup data-n=\"5161\">83</sup> כו' וע\"ד דמלכא משיחא אתא לאתבא<sup data-n=\"5162\">84</sup> לצדיקיא בתיובתא כו' [... והנה זהו רק הארה מבחי' שבת שבתון אבל בחי' שבת שבתון בעצם הוא בחי' יוה\"כ<sup data-n=\"5163\">85</sup> שנק' קדוש ה'<sup data-n=\"5164\">86</sup> כו' והוא בחי' עצמיות הרצון בחי' רעדכ\"ר<sup data-n=\"5165\">87</sup>",[["5150","72","<b>במ' של הפרש בין שבת ליו\"ט</b>: נדפס לעיל — ראה שם ע' רמד ואילך."],["5151","73","<b>שבת אותי' תשב</b>: ראה אגה\"ת ספ\"י. מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ. לעיל ע' רמח ובהערה 63."],["5152","74","<b>שבת נק' קודש</b>: תשא לד, יא. טו. ראה זהר אמור צד, א. שעה\"י קכח, א ובהערה 12."],["5153","75","<b>קודש שלמעלה מבחי' קדוש</b>: ראה גם לעיל מאמר ד\"ה את שבתותי תרי\"ב ובהערה 57. לקו\"ת אמור לג, ב ואילך. תו\"ח תשא ח\"ב שפב, ב. סה\"מ תרכ\"ז ע' שמ בהערה."],["5154","76","<b>שבת שבתון</b>: ויקהל לה, ב. ראה גם בענין שבת שבתון לעיל ע' רסג ובהערה 108."],["5155","77","<b>אותם במועדם ומתורגם בזמניהן</b>: אמור כג, ד בת\"א. ראה גם לעיל ע' רנב."],["5156","78","<b>מועדי הוי'</b>: אמור כג, ב. ד. ראה גם לעיל שם."],["5157","79","<b>אלה הם</b>: אמור כג, ב."],["5158","80","<b>ממדות שברצון. . ימי קדם</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שכח. תקס\"ט ע' טז. מאמרי אדה\"א ויקרא ח\"ב ע' תתנא."],["5159","81","<b>עושין רצש\"מ</b>: ברכות לה, ב."],["5160","82","<b>התשובה אינו מן החטא דווקא</b>: ראה חובת הלבבות שער עבודת אלקים פ\"ג (ד\"ה והחמישי כי מצות). תו\"א ויחי מה, א. מאמרי אדה\"א נ\"ך ע' רו. וש\"נ. הנחות תקע\"ז ע' צה. וש\"נ. סה\"מ תרכ\"ט ע' קד.ע' קכא. ע' קעט. תרצ\"ז ע' 235. וש\"נ."],["5161","83","<b>הרוח תשוב אל האלקים</b>: קהלת יב, ז."],["5162","84","<b>דמלכא משיחא אתא לאתבא</b>: ראה זהר רע\"מ בהעלותך קנג, ב. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 88. פלח הרמון בשלח ע' שיב בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' רפא וש\"נ. תו\"ח בראשית ז, א ובהערה 34. שמות ח\"א מא, ב. וש\"נ. סה\"מ תרכ\"ט ע' קד. וש\"נ."],["5163","85","<b>שבת שבתון. . יוה\"כ</b>: אחרי טז, לב. אמור כג, לב. ראה גם הנסמן בתו\"ח בא ח\"א צד, ב."],["5164","86","<b>יוה\"כ שנק' קדוש ה'</b>: ראה ישעי' נח, יג. שבת קיט, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלא."],["5165","87","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג. לעיל מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 56."]]],[4801940483,"שלמעלה מבחי' חכמה הנעלמה בו כידוע שאין טעם לרצון<sup data-n=\"5166\">88</sup> אפילו טעם הכמוס וכמשי\"ת<sup data-n=\"5167\">89</sup> וד\"ל]. ועם הנ\"ל יובן ג\"כ ההפרש בין ההיכל הנק' קודש שזהו בחי' מקום דסוכ\"ע בעצם שלמעלה מגילוי הסובב בממלא ובין בחי' קה\"ק שזהו בחי' הארת העצמיות בבחי' הסוכ\"ע וזהו בחי' תשובה דווקא, ולכן ביוה\"כ שהוא יום התשובה אז כה\"ג נכנס לפני ולפנים<sup data-n=\"5168\">90</sup> כו' וד\"ל [ושמעתי מבנו שי' ששמע פ\"א ממנו שבקה\"ק עצמו יש הפרש בין כל קה\"ק שהוא המשכת העצמיות בבחי' הסוכ\"ע ובין מקום ארון עצמו שהוגבה המקום דסובב בבחי' העצמיות ממש ולכן הוא בבחי' מקום דווקא מודד עשר אמה מכל צד ואע\"פ<sup data-n=\"5169\">92</sup> אינו מן המדה<sup data-n=\"5170\">91</sup> כו' וד\"ל].\n<b>ועם</b> כל הנ\"ל יובן ההפרש בין בחי' משה לבחי' אברהם בתוס' ביאור ויובן ג\"כ ענין וראית את אחורי ופני לא יראו בבחי' משה עצמו כי הנה עבודת אברהם הוא ע\"ד מועדי ה' שהוא בד\"כ גלוי הסובב בממלא ולכן ג' אבות כנגד ג' מועדי ה'<sup data-n=\"5171\">93</sup> פסח בחי' האהבה דאברהם שבועות הוא בחי' היראה דיצחק כו' וסוכות הוא בחי' מדות הרחמנות דיעקב וכמאמר ויעקב נסע סוכותה<sup data-n=\"5172\">94</sup> כו', וכ\"ז הוא בחי' גלוי הסובב בממלא כנ\"ל משא\"כ בחי' משה הוא בחי' שבת שהוא קדש דחכמה בעצם עצם הסוכ\"ע ולכן הי' משה כבד פה ולשון<sup data-n=\"5173\">95</sup> ע\"ד השבת דקי\"ל בו דבור אסור<sup data-n=\"5174\">96</sup> ובקושי התירו לדבר בו אפילו ד\"ת<sup data-n=\"5175\">97</sup> להיותו בבחי' נקודה למעלה מבחי' האותיות, וזהו שאנו אומרים בשבת ישמח משה<sup data-n=\"5176\">98</sup> במתנת חלקו כו', ולכן נאמר ג\"כ אצל משה כי המקום אשר אתה עומד עליו אדמת קודש הוא<sup data-n=\"5177\">99</sup> עצם הסוכ\"ע כו', אך כ\"ז הוא בחי' אחוריים וחיצוני' לגבי הארת העצמות דבע\"ת [... שזהו בחי' משיח] וזהו כתירוץ הב' דבחי' אחורים וחיצוני' דגבי משה הוא גבוה מבחי' הפנימי' דאברהם שזהו עצם הסוכ\"ע וזהו גלוי הסובב בממלא כו', אך גם תירוץ הא' אמת דופני לא יראו בבחי' ראיית המהות אבל בא בבחי' ידיעת המציאות והיינו ע\"פ הידוע דבשבת מאיר מעין<sup data-n=\"5178\">100</sup> שע\"ל<sup data-n=\"5179\">101</sup> ומעין יו\"כ<sup data-n=\"5180\">102</sup> הנק'",[["5166","88","<b>שאין טעם לרצון</b>: ראה של\"ה בית ה' ד, ב בהגה. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. תו\"ח בא ח\"א פט, ד. וש\"נ."],["5167","89","<b>וכמשי\"ת</b>: כ\"ה בהכת\"י."],["5168","90","<b>ביוה\"כ. . לפני ולפנים</b>: ר\"פ אחרי."],["5169","92","<b>ואע\"פ</b>: אוצ\"ל: ואעפ\"כ."],["5170","91","<b>מקום ארון. . אינו מן המדה</b>: יומא כא, א."],["5171","93","<b>ג' אבות כנגד ג' מועדי ה'</b>: ראה זהר רע\"מ פינחס רנז, ב. סה\"מ תרל\"ג ח\"ב ע' תסד. וש\"נ. הנסמן במאמרי אדה\"א נ\"ך ע' שפא־ במדבר ח\"ג ע' א'תרנו. הנחות תקע\"ז ע' ריז."],["5172","94","<b>ויעקב נסע סוכותה</b>: וישלח לג, יז."],["5173","95","<b>הי' משה כבד פה ולשון</b>: שמות ד, י."],["5174","96","<b>השבת. . דבור אסור</b>: שבת קיג, רע\"ב."],["5175","97","<b>ובקושי התירו. . ד\"ת</b>: ראה ירושלמי שבת פט\"ו, ה\"ג. רבינו יונה בס' היראה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסט. ובהנסמן במ\"מ לשם. מאמרי אדה\"א נ\"ך ע' קנו. וש\"נ. תו\"ח יתרו ח\"ב שפב, ב. תורת לו\"י תענית ע' ג."],["5176","98","<b>שאנו אומרים בשבת ישמח משה</b>: בתפלת העמידה."],["5177","99","<b>כי המקום. . אדמת קדש הוא</b>: שמות ג, ה."],["5178","100","<b>דבשבת מאיר מעין שלע\"ל</b>: ראה תו\"ח שמות ח\"א לג, ג. וש\"נ."],["5179","101","<b>שע\"ל</b>: אוצ\"ל: שלע\"ל."],["5180","102","<b>דבשבת מאיר מעין. . יו\"כ</b>: ראה לקו\"ת האזינו עב, ג."]]],[4801940517,"שבת שבתן והיינו במנחה דשבת שאז זמן רעדכ\"ר<sup data-n=\"5181\">103</sup> כו' אבל בחי' מעין הוא רק גילוי המציאות ולא בחי' המהות וע\"ד<sup data-n=\"5182\">104</sup> ג\"כ בבחי' משה מאיר מעין הארה דיום שכולו שבת שזהו בחי' גלוי המציאות וזהו ופני לא יראו לפי תירוץ הא' הנ\"ל שאינו בא בבחי' גלוי המהות רק ידיעת המציאות ולא בחי' גלוי המהות כו' וד\"ל.\n<b>להבין</b> עוד בענין המבואר למעלה דמאמר דוהתהלכתי כו' שיש ב' בחי' עושין רצונו של מקום ואין עושין כו', שע\"י בחי' עושין רש\"מ ממשיכין גלוי הסובב בממלא בבחי' פנימי' וכשאין עושין רש\"מ ממשיכין גלוי הסובב רק בבחי' מקיף ולכאורה קשה דהלא פרשה שניה מיירי כשאין עושין כו' שלכן נאמר שם ואספת דגנך<sup data-n=\"5183\">105</sup> וא\"כ איך נאמר שם ונתתי מטר ארצכם<sup data-n=\"5184\">106</sup> שמטר הוא בחי' המשכת הסובב בממלא בבחי' או\"פ כמבואר ג\"כ במא' הנ\"ל<sup data-n=\"5185\">107</sup>. וביאור התירוץ לזה ממאמר בפר\"א שכשישראל עושין<sup data-n=\"5186\">108</sup> רש\"מ אז שותין ממטר השמים כו' וכשאין עושין כו' אז שותין מימי אוקיינוס ובאור הדברים שיש ים ויבשה שהם ב' בחי' עלמין, עלמין סתימין דלא אתגליין ועלמא דאתגלי'<sup data-n=\"5187\">109</sup> אבל בחי' שמים הם בבחי'<sup data-n=\"5188\">110</sup> מקיפים שאינו בגדר עלמין כלל, ולכן פ' שני' מיירי כשאין עושין רש\"מ לכן א' ונתתי מטר ארצכם שהוא המשכה מימי אוקיינוס, והיינו המשכת ההעלם דעלמין סתימין לבא לידי גילוי בבחי' או\"פ אבל לא המשכת המקיפים שאינם מאירים רק בבחי' או\"מ, אבל כשעושין רש\"מ כמו בפ' ראשונה אז גם המקיפים דשמים באים בבחי' או\"פ הנק' מטר ועז\"נ למטר השמים תשתה מים<sup data-n=\"5189\">111</sup> כו' וד\"ל.",[["5181","103","<b>במנחה דשבת. . רעדכ\"ר</b>: ראה זהר יתרו פח, ב. אד\"ר נשא קכט, א. אד\"ז האזינו רפח, ב. רצג, סע\"א."],["5182","104","<b>וע\"ד</b>: אוצ\"ל: ועד\"ז."],["5183","105","<b>ואספת דגנך</b>: עקב יא, יד."],["5184","106","<b>ונתתי מטר ארצכם</b>: עקב שם."],["5185","107","<b>שמטר. . במא' הנ\"ל</b>: ד\"ה וביאור הענין בין הערות 64-65."],["5186","108","<b>ממאמר בפר\"א שכשישראל עושין</b>: ראה גם לעיל מאמר ד\"ה אם בחוקותי תר\"י ובהערה 64."],["5187","109","<b>ים ויבשה. . עלמין סתימין. . דאתגלי'</b>: ראה גם לעיל ע' פב ובהערה 2."],["5188","110","<b>בבחי'</b>: אוצ\"ל: בחי'."],["5189","111","<b>למטר השמים תשתה מים</b>: עקב יא, יא."]]],[4801940133,"<b>יום ג' ערב שבועות תרט\"ו</b>\n<b>והתהלכתי</b> בתוככם<sup data-n=\"5190\">1</sup> והייתי לכם לאלקים ואתם תהיו לי לעם<sup data-n=\"5191\">2</sup> כו'. הנה לעיל מיני' אמר ונתתי משכני בתוככם<sup data-n=\"5192\">3</sup> כו' וא\"כ מה יוסיף באמרו והתהלכתי בתוככם. אך יובן עם מאמר המדרש (הובא בילקוט שמעוני ע\"פ זה<sup data-n=\"5193\">4</sup> ) משל למלך<sup data-n=\"5194\">5</sup> שבא אצל אריסו והי' האריס ההוא מיטמר מלפניו והמלך א\"ל לאריס<sup data-n=\"5195\">6</sup> מה לך שאתה מיטמר מלפני הריני כיוצא בך כך המקום עתיד<sup data-n=\"5196\">7</sup> לטייל בין הצדיקים וצדיקים מזדעזעין לפניו והמקום אומר לצדיקים<sup data-n=\"5197\">8</sup> מה לכם שאתם מזדעזעין מלפני הריני כיוצא בכם כו'<sup data-n=\"5198\">9</sup>, או<sup data-n=\"5199\">10</sup> לפי שאני כיוצא בכם יכול לא תהא מוראי עליכם ת\"ל והייתי לכם לאלקים ואתם תהיו לי לעם, עכ\"ל המדרש. ועם זה יובן ענין הנ\"ל דבמש\"א והתהלכתי בתוככם הוסיף לומר הריני כיוצא בכם כו'. אך להבין ענין<sup data-n=\"5200\">11</sup> זה האיך שייך לומר התדמות להקב\"ה עם הצדיקים (... גם מהו ההפרש בין מזדעזעים שלא יהיו צריכים להזדעזע מלפניו כו'<sup data-n=\"5201\">12</sup> ובין מוראי שאמר אח\"כ שאעפ\"כ יצטרכו לירא מלפניו כו'. ..). גם להבין מה שדימה הקב\"ה והצדיקים לאריס עם מלך כו', הלא באריס המלך נוטל חלק מחצה או יותר בשדה כי המלך בעצמו חסר שלימות וצ\"ל נשלם ע\"י השדה כמאמר מלך לשדה נעבד<sup data-n=\"5202\">13</sup>, משא\"כ למעל'<sup data-n=\"5203\">14</sup> באוא\"ס אינו שייך לומר שהוא נשלם ע\"י מעשה התחתונים כי הוא שלימותא דכולא<sup data-n=\"5204\">15</sup> ואינו צריך לשלימות זולתו וכמאמר אם חטאת מה תפעל לו<sup data-n=\"5205\">16</sup> ואם צדקת מה תתן לו<sup data-n=\"5206\">17</sup> וא\"כ אין הנמשל דהקב\"ה עם הצדיקים דומה כלל למשל דמלך ואריס כו'.\n<b>והנה</b> להבין כל הנ\"ל צריך להקדים מתחלה שיש ב' מיני הילוך, הילוך בבחי' פנים כמו שנאמר באברהם התהלך לפני<sup data-n=\"5207\">18</sup> כו', והילוך בבחי' אחוריים",[["5190","1","<b>והתהלכתי בתוככם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס באוה\"ת ויקרא כרך ב ע' תרנד ואילך. קיצור עם תוספות והגהות נדפס שם בכרך ד ע' א'קעו ואילך. ובמהדורת תשנ\"ג בכרך ב ע' תשכג ואילך. וע' תשכט ואילך. ג' הנחות אחרות נדפסו במאמרי אדמו\"ר ה”צמח צדק\" תרט\"ו ע' צט. וש\"נ. ע' קה וע' קיד."],["5191","2","<b>והתהלכתי. . ואתם תהיו לי לעם</b>: בחוקותי כו, יב."],["5192","3","<b>ונתתי משכני בתוככם</b>: בחוקותי שם, יא."],["5193","4","<b>ע\"פ זה</b>: ניתוסף ע\"פ דה."],["5194","5","<b>משל למלך</b>: בילקו\"ש: משל למה הדבר דומה למלך."],["5195","6","<b>א\"ל לאריס</b>: ד: א'. ה: אמר. ו: אומר לאריס. ובילקו\"ש: אומר."],["5196","7","<b>המקום עתיד</b>: בילקו\"ש: עתיד המקום."],["5197","8","<b>לצדיקים</b>: בילקו\"ש: להם לצדיקים."],["5198","9","<b>כו'</b>: דהו ובילקו\"ש: ליתא."],["5199","10","<b>או</b>: הו: אי. בילקו\"ש: [אי]."],["5200","11","<b>ענין</b>: דה: ליתא."],["5201","12","<b>כו'</b>: דהו: כביכול."],["5202","13","<b>מלך לשדה נעבד</b>: קהלת ה, ח."],["5203","14","<b>למעל'</b>: ניתוסף ע\"פ דהו."],["5204","15","<b>באוא\"ס. . שלימותא דכולא</b>: ראה עבודת הקודש ח\"א רפ\"ח. דרך אמונה להנ\"ל מהדורת קה\"ת ע' יג ובהנסמן שם. לקו\"ת עקב טז סע\"א. הלשון שלימותא דכולא — ראה ת\"ז בהקדמה (יז, ב)."],["5205","16","<b>אם חטאת מה תפעל לו</b>: איוב לה, ו [ושם: בו — ה: לך]."],["5206","17","<b>ואם צדקת מה תתן לו</b>: איוב שם, ז [ושם: אם — ראה מאמרי אדה\"א נ\"ך ע' תמז. לעיל ע' רז. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 44]."],["5207","18","<b>התהלך לפני</b>: לך יז, א."]]],[4801940197,"וחיצוני' כמ\"ש אחרי הוי' תלכו<sup data-n=\"5208\">19</sup> כו' (... והגם שאפי' במשה שהי' בחינתו גבוה מאברהם נאמר וראית את אחורי<sup data-n=\"5209\">20</sup> כו', הנה יש הפרש בין בחי' ראי' שהוא בחי' גילוי המהות וזה לא יתכן רק בבחי' חיצוני' ואחוריים, אבל הפנימי' א\"א לבוא בבחי' גילוי המהות אפי' במשה, אבל בחי' ההילוך בא ע\"י ידיעת המציאות רק שאין הידיעה בבחי' השגה בלבד רק בדרך הרגשה להתפעל מזה וזה יכול להיות אפי' בבחי' הפנימי'. ולכן ההילוך דאברהם הגיע בבחי' פנים ומכ\"ש הילוך דמשה כמבואר במ\"א<sup data-n=\"5210\">21</sup> כו' וד\"ל. ..). והנה מתחילה י\"ל בד\"כ ענין ההילוך מהו ההפרש בין עמידה להילוך ואח\"כ יובן ענין ב' מיני הילוך. ויובן בהקדים ענין אשר אנכי מצוך היום<sup data-n=\"5211\">22</sup> בכ\"י יהיו בעיניך כחדשים<sup data-n=\"5212\">23</sup> שלכאורה אינו מובן איך יכול להיות בכל המצות כמו הנחת תפילין שמניחין בכל יום וכן לבישת הטלית בכל יום וכן ק\"ש קורא<sup data-n=\"5213\">24</sup> בכל יום נוסח אחד ואיך יכול להיות שיהיו כחדשים, וכן יקשה על ד\"ת שארז\"ל ע\"פ והודעתם כו'<sup data-n=\"5214\">25</sup> יום אשר עמדת<sup data-n=\"5215\">26</sup> לפני הוי' אלקיך בחורב כו' מה להלן באימה וביראה<sup data-n=\"5216\">27</sup> כו' איך יוכל להיות זה דבשלמא בשעת מ\"ת דיבר ה' פב\"פ<sup data-n=\"5217\">28</sup> בעצמו ולכן הי' באימה ויראה, אבל עכשיו שקוראין<sup data-n=\"5218\">29</sup> בספר איך יתכן להיות באימה ויראה כמו אז בשעת מ\"ת כו'.\n<b>אך</b> הנה ידוע שיש ב' בחי' ממכ\"ע ובחי' סוכ\"ע, בחי' ממכ\"ע הוא אור ושפע הבא בבחי' התלבשות בעולמות והיינו שהעולמות מרגישים שפעם וחיותם<sup data-n=\"5219\">30</sup> שהוא שופע בהם ועי\"ז מחי' ומהווה אותם מאין ליש והרגשה זאת נק' בשם הלבשה כו'. והנה שפע זאת באה במדה ושיעור היינו שבכל עולם נמדד השפע השופע בו לפ\"ע העולם המקבל החיות וממילא בא ונמשך החיות בחילוקי מדריגות רבות לפ\"ע ריבוי והתחלקות שבנבראים כו'<sup data-n=\"5220\">31</sup> וכמו עד\"מ חיות הנפש בגוף שבא בחילוקי מדריגות רבות כמו במוח החיות הוא רוחני יותר ובלב הוא מתגשם יותר לכן התפעלות הלב הוא מורגש יותר מגילוי השכל שבמוח כו', ואח\"כ כאשר נמשך החיות ביד ורגל מתגשם החיות יותר עד שנעשה ממנו תנועה והילוך כו'. כן בחיות האלקי בעולם הבריאה ששם הוא עולם הנשמות<sup data-n=\"5221\">32</sup> ונהנין מזיו השכינה<sup data-n=\"5222\">33</sup> שם החיות הוא רוחני יותר ואח\"כ בעולם היצי' מתצמצם החיות יותר עד שבא בהתפעלות במורגש ולכן חיות",[["5208","19","<b>אחרי הוי' תלכו</b>: ראה פ' ראה יג, ה."],["5209","20","<b>וראית את אחורי</b>: תשא לג, כג."],["5210","21","<b>ההילוך דאברהם. . כמ\"ש במ\"א</b>: ראה גם לעיל ע' תסח ואילך."],["5211","22","<b>אשר אנכי מצוך היום</b>: ואתחנן ו, ו."],["5212","23","<b>בכ\"י יהיו בעיניך כחדשים</b>: ראה לקח טוב ואתחנן ו, ו. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. לעיל ע' קמב הערה 14."],["5213","24","<b>קורא</b>: ניתוסף ע\"פ דו ועד\"ז ה."],["5214","25","<b>והודעתם כו'</b>: ניתוסף ע\"פ דה — ואתחנן ד, ט."],["5215","26","<b>יום אשר עמדת</b>: ואתחנן שם, י."],["5216","27","<b>מה להלן באימה וביראה</b>: ברכות כב, א. ראה גם לעיל ע' רנג ובהערה 127."],["5217","28","<b>בשעת. . פב\"ב</b>: ד: אז פב\"פ דיבר ה' — ואתחנן ה, ד."],["5218","29","<b>עכשיו שקוראין</b>: שם: הקורא."],["5219","30","<b>שפעם וחיותם</b>: שם: אור שפעו וחיותו."],["5220","31","<b>כו'</b>: ניתוסף ע\"פ דה."],["5221","32","<b>בעולם הבריאה. . עולם הנשמות</b>: ראה תניא פל\"ט. לקו\"ת ש\"ש סו, ג. המשך תרס\"ו ע' תנו. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 36."],["5222","33","<b>ונהנין מזיו השכינה</b>: ראה ברכות יז, א."]]],[4801940254,"הקדש בעולם היצירה<sup data-n=\"5223\">34</sup> מתפעלים ברעש גדול כו' עד שבעולם העשי' הגשמי נמשך החיות בתכלית הצמצום וההסתר כו', והנה בבחי' החיות<sup data-n=\"5224\">35</sup> דממכ\"ע אין שום התחדשות בשפע זאת כי כבר נמדד השפע בתחילת הבריאה כמה יהי' נמשך בכל יום ובאיזה אופן יומשך וכ\"ז נמשך<sup data-n=\"5225\">36</sup> בכל יום בלי שום שינוי כלל לא יוסיף ולא יגרע כו', ולכן אין כל חדש בשפע זאת, ומש\"א המחדש בטובו<sup data-n=\"5226\">37</sup> בכל יום מעשה בראשית היינו חידוש הישנות היינו שבכל נברא מתחדש חיותו בכל יום שיהי' חי' באופן שנמדד בו החיות בתחילת הבריאה אבל לא ישתנה מטבעו הראשון כו' (... וביאור ענין חידוש הישנות היינו כי כל מדה ושיעור שבא בגילוי בעולמות כבר נעשה מדידה זו בהעלם בבחי' עצמות המשפיע וכידוע שיש עשרה מאמרות הגלוים<sup data-n=\"5227\">38</sup> בגילוי בעולמות להוות אותם מאין ליש ונק' עשרה מאמרות שבדיבור (וענין הדיבור היינו ירידת המל' מל' כלים שבה<sup data-n=\"5228\">39</sup> בג' עולמות בי\"ע כו') (ועד\"ז יש עשרה מאמרות במח' והיינו בעצם המל' כמ\"ש בבחי' אצי' ושם נמדד בהעלם איכות כל פרטי ההשתל' הבאים אח\"כ בגילוי בדיבור<sup data-n=\"5229\">41</sup> והו\"ע ים ויבשה<sup data-n=\"5230\">40</sup> וכמארז\"ל כל מה שיש ביבשה<sup data-n=\"5231\">42</sup> יש בים, והנה ענין<sup data-n=\"5232\">43</sup> חידוש מעשה בראשית כי<sup data-n=\"5233\">44</sup> היינו שנתחדש בכל יום שפע החיות מהעלם המחשבה לבוא בגילוי בדיבור ונמצא שהנברא מאין ליש ע\"י הדיבור מתחדש חיותו ממקורו בהעלם במח' לכן אינו נק' שפע חדשה לגמרי מצד שגם במקורו במחשבה כבר בא השפע במדה ושיעור כו' וד\"ל. ..).\n<b>והנה</b> כל הנ\"ל הוא בבחי' ממכ\"ע כו' אבל בבחי' סוכ\"ע הוא אור ושפע שבא ונמשך בכל העולמות בעולם היותר עליון דבריאה עד דומם הגשמי דעשי' בהשוואה וכמאמר את השמים ואת הארץ אני מלא<sup data-n=\"5234\">46</sup> בהשוואה<sup data-n=\"5235\">45</sup> אך המשכתו הוא בהעלם ולא בגילוי כי לית מחשבה תפיסא<sup data-n=\"5236\">47</sup> בי' כלל כו'<sup data-n=\"5237\">48</sup>, אך כ\"ז הוא ע\"פ סדר ההשתל' אינו יכול להיות בחי' הסובב בגילוי בעולמות אבל ע\"י תומ\"צ ממשיכים אור הסובב בבחי' גילוי למטה בנש\"י שבגופים כו', והנה כאשר מאיר בחי' הסובב הוא בחי' אור חדש לגמרי להיותו למעלה מבחי' מדה ושיעור אפי' בהעלם כו', ולכן",[["5223","34","<b>חיות הקדש בעולם היצירה</b>: ראה ע\"ח שער פנו\"ח ש\"מ, דרוש יג. תו\"ח תצוה ח\"ב שמ, ג. וש\"נ."],["5224","35","<b>החיות</b>: ד: נסמן סימן למחיקה. אבל כ\"ה גם בהו."],["5225","36","<b>בכל יום. . וכ\"ז </b>[ו: וכ\"ה]<b> נמשך</b>: כ\"ה גם בו. דה: בכל עולם וכמה יהי' [ה: ליתא] נמשך."],["5226","37","<b>המחדש בטובו</b>: ע\"פ ברכת יוצר."],["5227","38","<b>הגלוים</b>: דהו: הבאים."],["5228","39","<b>המל' מל' </b>[דהו: בל']<b> כלים שבה</b>: ראה ע\"ח שער השמות שער מ\"ד, פ\"א-ב. לעיל ע' תד ובהערה 26."],["5229","41","<b>בדיבור</b>: דה: ע\"י הדיבור."],["5230","40","<b>במח'. . בדיבור והו\"ע ים ויבשה</b>: ראה גם לעיל ע' פ. ס\"ע שמח ואילך. שה\"א פד, ב. תו\"ח בשלח ח\"א קנג, סע\"ב ואילך."],["5231","42","<b>כל מה שיש ביבשה</b>: חולין קכז, א. ראה גם תו\"ח שמות יח, ג הערה 770."],["5232","43","<b>והנה ענין</b>: דה: כו' והו\"ע."],["5233","44","<b>כי</b>: דהו: ליתא."],["5234","46","<b>את השמים. . מלא</b>: ירמי' כג, כד. ראה גם לעיל ע' שצח ובהערה 85. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["5235","45","<b>וכמאמר. . בהשוואה</b>: ד: ליתא. וכנראה נשמט מפני תיבות הדומות: בהשוואה. . בהשוואה."],["5236","47","<b>לית מח' תפיסא</b>: ראה ת\"ז בהקדמה יז, ב."],["5237","48","<b>כו'</b>: ד: ליתא."]]],[4801940307,"אמרו בכל יום יהי' בעיניך כחדשים כי באמת כ\"ה שבכ\"י שעושה את המצוה הוא ממשיך אור חדש שלא המשיך אתמול נמצא שהמשכה הוא<sup data-n=\"5238\">49</sup> חדשה לגמרי מצד חיות החדש הנמשך בה וע\"י בנה\"א כו' (... כי הגם שגילוי הסובב הוא גילוי אור העצמי' כמ\"ש מ\"מ יכול להתגלות בע\"א<sup data-n=\"5239\">50</sup> עד אין שיעור כי אוא\"ס הוא בעילוי אחר עילוי בעצמותו ולכן ע\"י כל מצוה נמשך אור חדש לגמרי שלא נמשך מעולם עדיין כו' וד\"ל. ..). וכן ע\"י לימוד התורה בכל עת שלומד ממשיך אור חדש מבחי' סוכ\"ע כמו בשעת מ\"ת ממש ולכן אנו אומרים נותן התורה ל' הווה<sup data-n=\"5240\">51</sup> כי הנתינה הוא מחדש בכ\"י כי בכ\"י נמשך אור חדש מבחי' הסובב ע\"י לימוד התורה ולכן צריך להיות באימה ויראה כמו בשעת מ\"ת ממש, כי גם עכשיו הוא לומד בתורה בבחי' פב\"פ כו' וד\"ל.\n<b>ועוד</b> יתפרש תיבת היום לעשותם<sup data-n=\"5241\">52</sup> כי ענין המעשה דתומ\"צ להמשיך בחי' אור חדש דסוכ\"ע אינו רק בעוה\"ז הגשמי ולא בעולמות הרוחני' כי שם אינו נמשך רק מבחי' ממכ\"ע (... ואפי' זיו תומ\"צ שמקבלת הנשמה בג\"ע אחרי שהיתה בגוף אינו רק הארה מעצמות אור תומ\"צ שנעשה<sup data-n=\"5242\">53</sup> בעוה\"ז הגשמי ע\"י גוף המעשה, וכן ארז\"ל אשרי איש<sup data-n=\"5243\">54</sup> כו' במצותיו חפץ מאד ולא בשכר מצותיו וכנ\"ל במא' ויחי<sup data-n=\"5244\">55</sup> שעיקר קיבול השכר מעצם אור המצוה הוא לע\"ל ולא בג\"ע כו'. ..), וראי' לזה מענין התשובה שאינו רק בעוה\"ז הגשמי כידוע מארז\"ל המקדש את האשה<sup data-n=\"5245\">56</sup> ע\"מ שאני צדיק גמור אע\"פ שהוא רשע גמור מ\"מ מקודשת שמא הרהר תשובה בלבו, נמצא שע\"י הרהור תשובה בלבד יכול להתהפך מן הקצה אל הקצה מרשע גמור לצדיק גמור, משא\"כ בעוה\"ב לא יוכל להיות עלי' ממדריגה למדריגה כ\"א ע\"י ביטול והפשטה ממדריגה הראשונה ולכן כאשר נמשכה הנשמה אחרי תענוגי עוה\"ז לא תוכל לבוא בג\"ע להנות מזיו תענוג האלקי כ\"א כאשר תזדכך נפשו בתחילה ע\"י גיהנם ונהר דינור כו' (... וכן מגעה\"ת לגעה\"ע אע\"פ ששניהם הוא בבחי' עונג האלקי מ\"מ לא תוכל להתעלות מגעה\"ת לגעה\"ע כ\"א ע\"י העמוד<sup data-n=\"5246\">57</sup> המפשיטה ממהות תענוג הראשון לגמרי כו'. ..). והיינו מפני שבעולמות הרוחני' אינו נמשך רק מבחי' ממכ\"ע שהוא אור הבא בסדר והדרגה, לכן מי שהוא במדריגה התחתונה א\"א לו לקבל האור שבמדרגה העליונה הימנה כ\"א ע\"י ביטול והפשטה ממדריגה הראשונה",[["5238","49","<b>שהמשכה הוא</b>: דהו: שהמצוה היא."],["5239","50","<b>בע\"א</b>: שם: בעא\"ע בעילוי אחר עילוי."],["5240","51","<b>נותן התורה ל' הווה</b>: ראה גם של\"ה כה, א. קצב, א. מאמרי אדה\"א הנחות תקע\"ז ע' שז. וש\"נ. סה\"מ תרל\"ח ע' קצב הערה 1534."],["5241","52","<b>תיבת </b>[ד: היום ע\"ד]<b> היום לעשותם</b>: ואתחנן ז, יא."],["5242","53","<b>תומ\"צ שנעשה</b>: דהו: התורה הנמשך."],["5243","54","<b>אשרי איש</b>: תהלים קיב, א [בדילוג]. ע\"ז יט, א."],["5244","55","<b>וכנ\"ל במא' ויחי</b>: נדפס בפלח הרמון בראשית קטו, ד. סה\"מ תרכ\"ח ע' נ."],["5245","56","<b>המקדש את האשה</b>: קדושין מט, ב. ראה גם לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 41. לקו\"ת דברים א, ב. סה\"מ תרל\"ח ע' תקי ובהערה 89."],["5246","57","<b>ע\"י העמוד</b>: ראה תו\"א מג\"א ק, ב ושם: ע' זהר ויקהל ריא, א. ויחי ריט, א. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשעג. מאמרי אדה\"א נ\"ך ע' תעו. וש\"נ. לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 79."]]],[4801940357,"לגמרי, משא\"כ בעוה\"ז מאיר אור הסובב שאינו בא בסדר והדרגה להיותו למעלה מכל המדריגות לכן יכול להאיר ברשע גמור כמו בצדיק גמור רק שיהרהר תשובה בלבו כו' (... והטעם לזה שבעוה\"ז מאיר דוקא אור הסובב היינו כמבואר במ\"א שהתהוות הגשמי' מן הרוחני' א\"א להיות בסדר ההשתלשלות רק מבחי' כל יכול<sup data-n=\"5247\">58</sup> ונמצא שהתהוות עולם הגשמי הוא מבחי' הסובב דוקא רק שהסובב נמצא בו בהעלם עד שנראה ליש, אבל ע\"י המצוה מהפכים הדבר הגשמי' ממש לאין ועי\"ז נתגלה כח המהווה אותו שהוא בחי' הסובב כנ\"ל בבחי' גילוי במעשה המצות כו' וכן ע\"י התשובה כו'<sup data-n=\"5248\">59</sup> וד\"ל). וזהו הטעם דהיום לעשותם דוקא כו' (... משא\"כ בעולמות הרוחני' אין מעשה וחשבון וחכמה כו' וד\"ל. ..).\n<b>והנה</b> עם הנ\"ל יובן ההפרש בין בחי' עמידה לבחי' הילוך כו', שבחי' עמידה הוא בחי'<sup data-n=\"5249\">60</sup> שפע הבאה במדה ושיעור היינו ההשפעה דבחי' ממכ\"ע שכבר נמדד שפע זאת בהעלם המשפיע והגם שיש התחדשות בשפע זאת הוא רק מהעלם אל הגילוי ולכן נק' המקבל שפע זאת בחי' עומד עדיין<sup data-n=\"5250\">61</sup> להיות שהוא במדריגתו הראשונה רק שהמדריגה שלו נתחדשה בחיות חדש אבל לא נשתנה כלל ממהותו הראשון משא\"כ בחי' הילוך הוא בחי' השפעת הסובב שהוא למעלה מבחי' אדם<sup data-n=\"5251\">62</sup> אפי' בהעלם ולכן כאשר מאיר בחי' הסובב הוא בחי' אור חדש לגמרי ולכן נק' המקבל שפע זאת בשם מהלך להיות שהולך ממדריגתו לגמרי ונתעלה בבחי' א\"ס ממש (... ולכן נק' המלאכים בשם עומדים וכן הנשמות קודם בואם לגוף רק הנשמות המתלבשים בגופים ומקיימים תומ\"צ בגשמיות נק' מהלכים כמשי\"ת לקמן במאמר אם בדרכי תלכו<sup data-n=\"5252\">63</sup> יעו\"ש. ..).\n<b>ומעתה</b> י\"ל איך שבבחי' הילוך שלמעלה מבחי' עמידה יש ב' בחי' הא' בחי' הילוך בבחי' אחוריים והב' בחי' הילוך<sup data-n=\"5253\">64</sup> בבחי' פנים כנ\"ל. ויובן בהקדים המאמר דרשב\"י (ברכות דל\"ה ע\"ב) אפשר אדם חורש כו' אלא בזמן שישראל עושין רצונו ש\"מ מלאכתן נעשית ע\"י אחרים שנאמר ועמדו זרים ורעו צאנכם<sup data-n=\"5254\">66</sup> כו' ובזמן שאין ישראל עושין רש\"מ מלאכתן נעשית<sup data-n=\"5255\">65</sup> ע\"י עצמן כו'. והקושי' מפורסמת דהלא ואספת דגנך<sup data-n=\"5256\">67</sup> נאמר בפ' והיה אם שמוע ושם נאמר בכל לבבכם<sup data-n=\"5257\">68</sup> כו', ואיך יקראו בשם אין עושין רש\"מ כו', ותי' הרה\"מ נ\"ע דמחמת שלא נאמר בכל מאדך<sup data-n=\"5258\">69</sup> בפ'",[["5247","58","<b>שהתהוות הגשמי'. . כל יכול</b>: ראה תו\"א מג\"א צ, ב. לקו\"ת ראה כ, ד. אוה\"ת שמ\"ע ע' א'תשפב. מאמרי אדה\"א דברים ח\"ד ע' א'רפו ואילך."],["5248","59","<b>כו'. . כו'</b>: דה: כו'. ואולי נשמט מפני תיבות הדומות: כו'. . כו'."],["5249","60","<b>בחי'</b>: ניתוסף ע\"פ ד."],["5250","61","<b>עדיין</b>: ניתוסף ע\"פ ד."],["5251","62","<b>אדם</b>: שם: מדה."],["5252","63","<b>במאמר אם בדרכי תלכו </b>[שם: תלך]: יודפס בעז\"ה בספרו פלח הרמון. ג' הנחות אחרות מדרוש זה נדפסו במאמרי אדמו\"ר ה”צמח צדק\" תרט\"ו ע' קמט. וש\"נ. ע' קנז וע' רסח."],["5253","64","<b>הא' בחי'. . והב' בחי' הילוך</b>: ד: ליתא. . והילוך."],["5254","66","<b>ועמדו זרים ורעו צאנכם</b>: ישעי' סא, ה."],["5255","65","<b>ע\"י. . נעשית</b>: שם: ליתא. וכנראה נשמט מפני תיבות הדומות: ע\"י. . ע\"י."],["5256","67","<b>ואספת דגנך</b>: עקב יא, יד."],["5257","68","<b>והיה אם שמוע. . בכל לבבכם</b>: עקב שם, יג."],["5258","69","<b>ותי' הרה\"מ. . בכל מאדך</b>: ראה או\"ת עקב ד\"ה מפני מה (נג, סע\"ג ואילך). לעיל ע' תסב ובהערה 40."]]],[4801940403,"שני', לכן נק' אין עושין רצונו של מקום כו' (... כי בכל מאדך הוא גילוי נקודת הלב שהוא הרצון שלמעלה מן הטעם לגמרי וזה דוקא נק' עושין רש\"מ, ועד\"ז תירץ בחידושי מהרש\"א<sup data-n=\"5259\">70</sup> ע\"ד הפשוט<sup data-n=\"5260\">71</sup> דבכל מאדך הוא בכל ממונך<sup data-n=\"5261\">72</sup> וכ\"ז שלא בא למדה זאת להפקיר ממונו ורכושו בשביל רצון ה' נק' אין עושין רש\"מ כ\"כ יעו\"ש. ..). אך גם זה אינו מובן וכי בשביל שלא נגלה נקודת הלב יקרא אין עושין רש\"מ הלא יש<sup data-n=\"5262\">73</sup> לו אהבה דבכל לבבכם ובכל נפשכם ומקיים כל המצות ושומר א\"ע מכל מיני רע מחמת אהבה זאת<sup data-n=\"5263\">74</sup>.\n<b>אך</b><sup data-n=\"5264\">75</sup> יובן בהקדם ענין ברוך המקום<sup data-n=\"5265\">76</sup> כי הנה ארז\"ל הוא מקומו של עולם<sup data-n=\"5266\">77</sup> והכוונה שהוא ע\"ד דוגמא דמקום הגשמי שמגביל את מהות הנברא דומם או צומח כו' בו\"ק מעלה ומטה וד' רוחות<sup data-n=\"5267\">78</sup> וכן ברוחני' מקום הרוחני הוא מגביל הנברא הרוחני בו\"ק רוחני' שנכללים בג' בחי' עומק ורוחב ואורך (... כמו עד\"מ בשכל שיש בחי' עומק ורוחב ואורך, עומק הוא עצמי' ההשכלה הפרטי' בראשית מציאותה מכח המשכיל הנקרא אין וכאשר מבריק בגילוי במוח נק' רוחב, והאורך הוא כח המדידה<sup data-n=\"5268\">79</sup> שבהשכלה להביאה בהסבר ההשגה כמבואר בשער היחוד פ\"א יעו\"ש<sup data-n=\"5269\">80</sup>. ..). כן עד\"ז למעלה אמיתית המגביל ומודד כל הנבראים הן בהתהוותם מאין ליש והן בקבלת חיותם שהוא בחי' הביטול הנמצא בהם הכל הוא מצד בחי' אלקות שנותן מדה וקצבה לכל נברא פרטי ובחי' זאת נק' מקום כו' (... והנה מקום זה הוא בחי' ממכ\"ע שהוא בחי' מל'<sup data-n=\"5270\">81</sup> דאצי' שבחי' ו\"ק<sup data-n=\"5271\">82</sup> שבמל' הם מגבילים לאור האלקי שיתלבש בכל עולם לפ\"ע להחיותו וכן הם מגבילים לבחי' העולם עצמו שהוא בחי' התהוות היש שלו באיזה אופן יהי' וע\"ז כיוונו רז\"ל באמרם הוא מקומו של עולם פי' שהוא עושה בחי' המקום בכל העולמות, הן בבחי' החומר להגבילו בששה קצוותיו והן בבחי' חיות האלקי לצמצמו שיתלבש בבחי' החומר בבחי' הרגשה כו'.\n<b>אך</b> מבואר במ\"א בביאור דוהתהלכתי<sup data-n=\"5272\">83</sup> ששמעתי בשנת תר\"ב פ' וישלח שיש בחי' ב' בבחי' מקום שהוא בחי' סוכ\"ע, וביאור הדברים ע\"ד שאנו רואים במקום",[["5259","70","<b>בחידושי מהרש\"א</b>: באגדות מהרש\"א לברכות שם ד\"ה שנאמר."],["5260","71","<b>ע\"ד הפשוט</b>: ד: ע\"פ הפשט."],["5261","72","<b>דבכל מאדך הוא בכל ממונך</b>: ואתחנן ו, ה. ברכות נד, א (במשנה). ראה גם סהמ\"צ להצ\"צ קלט, ב. ש\"א יא, א ובהנסמן במ\"מ לשם."],["5262","73","<b>יקרא. . יש</b>: דה: כיון שיש. וראה בהערה הבאה."],["5263","74","<b>זאת</b>: שם ניתוסף: איך יוכל לקרותו בשם אין עושין רצונו של מקום. וראה לעיל בפנים על יד הערה 73."],["5264","75","<b>אך</b>: שם ניתוסף: הענין."],["5265","76","<b>ברוך המקום</b>: מדות ספ\"ה."],["5266","77","<b>הוא מקומו של עולם</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2. לעיל ע' תסב הערה 45."],["5267","78","<b>וד' רוחות</b>: ד: מו\"מ צו\"ד."],["5268","79","<b>המדידה</b>: דהו: הירידה."],["5269","80","<b>בשער היחוד פ\"א יעו\"ש </b>[דה: כו']: ראה גם בלקוטי ביאורים לשם."],["5270","81","<b>מקום. . מל'</b>: ראה שער היחוד והאמונה פ\"ז."],["5271","82","<b>ו\"ק</b>: ד: מקום."],["5272","83","<b>בביאור דוהתהלכתי</b>: נדפס לעיל — על יד הערה 46 ואילך."]]],[4801940446,"הגשמי בכלי גשמי שמדת הכלי הוא מקומה המגבילה, אבל האויר<sup data-n=\"5273\">84</sup> המקיף לכלי ונושא וסובל אותה הוא בחי' מקום שהוא יתר ממדת הכלי וכמארז\"ל אמתא באמתא היכי יתיב<sup data-n=\"5274\">85</sup> כו', ועד\"ז גם<sup data-n=\"5275\">86</sup> ברוחני' בחי' סוכ\"ע הוא בחי' המקיף לאור וחיות הממכ\"ע עם גוף העולמות והוא כח הנושא וסובל את כל העולמות עם האור וחיות שבהם והוא קיומם האמיתי, והוא בחי' בינה מקור כל המקיפים<sup data-n=\"5276\">87</sup> כו' (כן מבואר שם הל' ברשימה שלי, ולפ\"ד שאין הכוונה על עצמי' הבינה רק בחי' הבינה הכוללת המדות דאצי' בתוכה שבחי' זאת למעל' מבחי' סובב ומקיף<sup data-n=\"5277\">89</sup> כמשי\"ת לקמן)<sup data-n=\"5278\">88</sup>, וגם ע\"ז כוונו רז\"ל באמרם הוא מקומו של עולם שהוא סובל כל העולמות בידיעתו המקפת אותם מראשם ועד תחתיתם ותוכם ותוך תוכם הכל בפ\"מ והוא אמיתית המהווה אותם מאין ליש וגם הוא אמיתית קיומם (וכמבואר בלק\"א פ' מ\"ח יעו\"ש)<sup data-n=\"5279\">90</sup>, כי אינו דומה המשל דמקום של האויר המקיף כלי הגשמי שהוא משמש רק עמידת הכלי שתעמוד בו בלבד כו', אבל בנמשל המקום הנושא וסובל הוא ממלא את כל העולמות עד דלית אתר פנוי מיני'<sup data-n=\"5280\">91</sup> (רק מילוי זה הוא בהעלם ובכולם בהשוואה כו' והוא אמיתית התהוותם מאין ליש ואמיתית קיומם כנ\"ל)<sup data-n=\"5281\">92</sup>. ומבואר עוד במאמר הנ\"ל שב' בחי' מקום אלו דסובב וממלא הוא בחי' מקום דבע\"ת ומקום דצ\"ג יעו\"ש. ..).\n<b>ומעתה</b> יש להבין ענין ברוך המקום כי הנה כתיב הנה מקום אתי<sup data-n=\"5282\">93</sup> והמקום<sup data-n=\"5283\">94</sup> דהשתל' נכלל בלמעלה מהשתל' כו' (... ויתפרש ג\"כ בב' בחי' הנ\"ל בהג\"ה שמקום<sup data-n=\"5284\">95</sup> דממכ\"ע שהוא בחי' המל' דאצי' נכלל בבחי' הסוכ\"ע שהם בחי' המדות דאצי' כידוע דמתחילה קודם בנין המל' בבחי' פרצוף שלם<sup data-n=\"5285\">96</sup> בפ\"ע היתה כלולה בבחי' הי\"ס דאצי' בחי' עשיראה דכולהו<sup data-n=\"5286\">97</sup> ונק' עצם מעצמו<sup data-n=\"5287\">98</sup> כו' ומכ\"ש כשהיו בחי' המדות עצמם כלולים בבחי' בינה המקיפים ששם היתה בחי' המל' בבחי' ביטול בתכלית וזהו שהמקום דממכ\"ע הוא אתי<sup data-n=\"5288\">99</sup> נכלל בבחי' הסוכ\"ע למעלה מהשתל' דממכ\"ע. ויתפרש עוד באופן ב'<sup data-n=\"5289\">100</sup> שגם המקום דסוכ\"ע הוא אתי נכלל בלמעלה מהשתל' לגמרי שאינו גם בבחי' סובב לעלמין והוא עצמות הבינה דאצי' כנ\"ל כידוע בכהאריז\"ל דבחי' או\"א עילאין<sup data-n=\"5290\">101</sup> הם למעלה מבחי' מקור למדות דז\"א",[["5273","84","<b>האויר</b>: תוקן ע\"פ דהו. ובכת\"י זה: האור."],["5274","85","<b>אמתא באמתא היכי יתיב</b>: פסחים קט, ב כגי' התוס'."],["5275","86","<b>גם</b>: ניתוסף ע\"פ דהו."],["5276","87","<b>בינה מקור כל המקיפים</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["5277","89","<b>עצמי' הבינה. . ומקיף</b>: תוקן ע\"פ דהו. ובכת\"י זה: מקיף וסובב."],["5278","88","<b>(כן. . לקמן)</b>: ד: כן. . לקמן."],["5279","90","<b>(וכמבואר. . יעו\"ש)</b>: ד: וכמבואר. . יעו\"ש."],["5280","91","<b>דלית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["5281","92","<b>(רק. . כנ\"ל)</b>: ד: רק. . כנ\"ל."],["5282","93","<b>הנה מקום אתי</b>: תשא לג, כא."],["5283","94","<b>והמקום</b>: ד: שמקום זה."],["5284","95","<b>שמקום</b>: שם: הא' שהמקום."],["5285","96","<b>שלם</b>: ניתוסף ע\"פ ד."],["5286","97","<b>עשיראה דכולהו</b>: ראה זהר פינחס רנג, רע\"ב. ראה גם לעיל ע' פג. שעה\"י פמ\"ז. וראה גם לקוטי ביאורים — קה\"ת — לשם."],["5287","98","<b>עצם מעצמו </b>[ד: מעצמי]: בראשית ב, כג."],["5288","99","<b>אתי</b>: שם: ליתא."],["5289","100","<b>באופן ב'</b>: ניתוסף ע\"פ ד."],["5290","101","<b>או\"א עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. לעיל ע' תג ובהערה 21."]]],[4801940484,"(כי מקור מדות דז\"א נק' יסו\"ת<sup data-n=\"5291\">103</sup> כו'<sup data-n=\"5292\">102</sup> ), ונק' בלשון החסידות אור המאיר לעצמו וע\"ד מבשרי אחזה כשמשכיל השכלות עמוקות לעצמו<sup data-n=\"5293\">104</sup> שאינם שייכים להנהגת המדות כלל כו', ובחי' זאת נק' אתה הוי' לבדיך<sup data-n=\"5294\">106</sup> למעלה מבחי' סובב וממלא, אך אעפ\"כ היו כלולים שם המדות בתכלית הביטול כי אור המאיר להיות מקור לבחי' זולתו שהוא בחי' המדות דאצי' עם בחי' בינה המקור למדות נמשך מבחי' אור המאיר לעצמו וא\"כ ע\"כ היו כלולים בו מתחילה (וע\"ד מבשרי אחזה<sup data-n=\"5295\">105</sup> שבחי' השכל איך להתנהג במדותיו נמשך מעצמות השכל המשכיל השכלות שאינם שייכים להנהגת המדות, וראי' שלפ\"ע חכמתו בעצם כ\"ה חכמתו בהנהגת מדותיו כו'<sup data-n=\"5296\">107</sup> ), וזהו המקום דסובב שהוא ג\"כ אתי<sup data-n=\"5297\">109</sup> דהיינו שכלול ובטל באור העצמי' שלמעל' מבחי' סומ\"מ וד\"ל. ..)<sup data-n=\"5298\">108</sup> ולזה צריך לברך ולהמשיך מבחי' הנה מקום אתי הנ\"ל לבחי' הוא מקומו של עולם, והיינו שיומשך הביטול למטה בבחי' מקום דהשתל' (... שהוא בב' בחי' דסובב וממלא כנ\"ל בהג\"ה. ..), כמו למעלה כאשר הי' המקום כלול בלמעלה מהשתל' אשר שם הוא בתכלית הביטול, כן יתגלה ביטול זה בבחי' המקום שבגילוי כו', וזהו ברוך המקום ל' נפעל שבחי' הוא מקומו של עולם יתברך ויומשך ממקורו בחי' הנה מקום אתי הנ\"ל כו' וד\"ל.\n<b>והנה</b> המשכה זאת שיתגלה הביטול דבחי' הנה מקום אתי בבחי' הוא מקומו של עולם כנ\"ל שזהו גילוי אא\"ס למטה כמו למעלה כו'<sup data-n=\"5299\">110</sup> לא תהי' מצ\"ע רק ע\"י אתעדל\"ת דמעשה התחתונים דייקא (... כי כן הי' פנימי' הרצון אשר שלימות הכוונה שהוא להיות לו דירה בתחתונים שהוא גילוי אא\"ס למטה כמו למעלה יהי' תלוי במעשה התחתונים כמבואר בסידור בשער ברהמ\"ז<sup data-n=\"5300\">111</sup> בענין ואח\"כ תלוי במעשה התחתונים, שסוף מעשה מוכיח על תחילת המח' כו'. ..). והנה איזה אתעדל\"ת תוכל לעורר הגילוי דאא\"ס למטה כמו למעלה הוא ע\"י אהבה דבכל מאדך דייקא שלמעלה מבחי' אהבה דבכל לבבך ובכל נפשך כו' (... והטעם לזה כי כל התעוררות צ\"ל בדוגמתו דייקא וידוע אשר בחי' רצה\"ע הנ\"ל דלהיות לו דירה בתחתונים<sup data-n=\"5301\">113</sup> כו' הוא למעלה מן הטעם<sup data-n=\"5302\">112</sup> לגמרי אפי' מבחי' טעם הכמוס כו' ולמעלה אפי' מבחי' עונג כו' כי העונג הוא בחי' שלימות ואין דבר שישלימנו כי הוא שלימותא דכולא כו' ולזאת לעורר רצון זה צ\"ל ההתעוררות מלמטה ע\"י הרצון שבנפש ג\"כ בבחי' רצון<sup data-n=\"5303\">114</sup> שלמעלה מן הטעם לגמרי והוא בחי' נקודת הלב שהוא בחי' אהבה דבכל מאדך כנ\"ל כו' וד\"ל. ..). ולכן הם הנקראים עושין רצונו של מקום היינו שעושין וממשיכים בחי'",[["5291","103","<b>יסו\"ת</b>: ישראל סבא ותבונה — ראה שעה\"י פ\"ב. לעיל ע' קכט ובהערה 18."],["5292","102","<b>(כי. . כו')</b>: ד: כי. . כו'."],["5293","104","<b>וע\"ד. . לעצמו</b>: ניתוסף ע\"פ דהו. ואולי נשמט מפני תיבות הדומות: לעצמו. . לעצמו."],["5294","106","<b>אתה ה' לבדיך</b>: ישעי' לז, כ."],["5295","105","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["5296","107","<b>(וע\"ד. . כו')</b>: ד: וע\"ד. . כו'."],["5297","109","<b>אתי</b>: ניתוסף ע\"פ הו. ד: הניח מקום פנוי."],["5298","108","<b>וזהו. . וד\"ל... )</b>: ניתוסף ע\"פ דהו."],["5299","110","<b>כו'</b>: ד: כנ\"ל."],["5300","111","<b>בסידור בשער ברהמ\"ז</b>: קט, ב ואילך."],["5301","113","<b>בתחתונים</b>: ניתוסף ע\"פ ד."],["5302","112","<b>רצה\"ע. . דירה בתחתונים. . למעלה מן הטעם</b>: ראה גם סה\"מ תרכ\"ז ע' תנג ואילך. וש\"נ. המשך מים רבים פפ\"ו ע' צא. סה\"מ תרל\"ח ס\"ע תנד ואילך."],["5303","114","<b>רצון</b>: ניתוסף ע\"פ ד."]]],[4801940518,"רצה\"ע שלמעלה מבחי' מקום (... כנ\"ל שבחי' מקום הוא בחי' המדות ובחי' חו\"ב עילאין הוא למעלה מבחי' מדות ומכ\"ש רצה\"ע שזהו בחי' הכתר שלמעלה מחו\"ב כו'. ..), שיומשך ויתגלה בבחי' המקום (... דסובב וממלא שנק' מקומו של עולם כנ\"ל וד\"ל (ומה<sup data-n=\"5304\">115</sup> שנק' בשם רצונו של מקום הגם שהרצון הוא למעלה מבחי' מקום כנ\"ל היינו ע\"ד הידוע בשם הבעש\"ט שכל מקום שהרצון<sup data-n=\"5305\">116</sup> הוא שם<sup data-n=\"5306\">117</sup> שם הוא כולו, נמצא כיון שרצה\"ע הוא להתגלות בבחי' מקום ממילא הוא מלובש בבחי' המקום בהעלם וממילא כל העצמות מלובש בבחי' מקום וכידוע דנעוץ תחב\"ס<sup data-n=\"5307\">118</sup> וכתר עליון איהו כתר מל'<sup data-n=\"5308\">119</sup> רק שצריך שיתגלה בבחי' גילוי ממש וזהו ע\"י מעשה התחתונים דוקא, ובזה יובן שלכן נק' רש\"מ מצד שהוא מלובש בבחי' המקום בהעלם, מ\"מ נק' צדיקים עושין רצונו של מקום מצד שממשיכין אותו מהעלם אל הגילוי כו' וד\"ל. ..), משא\"כ אותן שלא הגיעו לבחי' אהבה דבכל מאדך רק לבחי' בכל לבבכם ובכל נפשיכם כו' הגם שממשיכים תוס' שפע ע\"י עבודתם מ\"מ לא יומשך הגילוי למטה כמו למעלה ולכן נק' אין עושין רצונו של מקום להיות שאינם משלימין לגמרי רצה\"ע ששלימות הרצון הוא להיות למטה כמו למעלה ממש דוקא כו' וד\"ל.\n<b>וזה\"ע</b> ותקנא רחל באחותה<sup data-n=\"5309\">120</sup> כו' שזהו תיאובתא דעלמא תתאה למהוי כגוונא דעלמא עילאה<sup data-n=\"5310\">121</sup> ממש (... כמו אל יקנא לבך<sup data-n=\"5311\">122</sup> כו' כ\"א ביראת ה' שהכוונה להיות כמותם כו'. ..). והענין הוא דבחי' לאה הוא בחי' עלמא<sup data-n=\"5312\">124</sup> דאתכסיא<sup data-n=\"5313\">123</sup> שזה\"ע התכללות המקום דהשתלשלות בלמעלה מהשתל' שנק' הנה מקום אתי וכידוע דבחי' לאה ילדה ששה בנים<sup data-n=\"5314\">125</sup> שהם ו\"ק שנק' בחי' הוא מקומו של עולם אך כל לידה מוכרח להיות ע\"י עיבור בתחילה, ונמצא שמתחילה היו כלולים המדות בהעלם בבחי' לאה הנ\"ל (... וזהו עלמא דאתכסייא שהעולם שהוא בבחי' מקום וזמן<sup data-n=\"5315\">127</sup> הוא בבחי' כיסוי והעלם<sup data-n=\"5316\">128</sup> להיותו נכלל ובטל בלמעלה מהשתל' כו'. ..), שהוא בחי' אותיות המחשבה<sup data-n=\"5317\">126</sup> וזהו הנה מקום אתי שהמדות שהם בחי' מקומו של עולם כלולים באותיות המחשבה שהם למעלה מהשתל' (... והגם שאותיות המחשבה הם מקבלים מן המדות",[["5304","115","<b>(דסובב. . (ומה</b>: תוקן ע\"פ ד. . ד: ומה."],["5305","116","<b>בשם הבעש\"ט שכל מקום שהרצון</b>: ראה גם לעיל ס\"ע שיא ובהערה 222."],["5306","117","<b>הוא שם</b>: ד: ליתא."],["5307","118","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["5308","119","<b>וכתר עליון איהו כתר מל'</b>: ת\"ז בהקדמה יז, א."],["5309","120","<b>ותקנא רחל באחותה</b>: ויצא ל, א."],["5310","121","<b>תיאובתא דעלמא תתאה. . עילאה</b>: ראה זהר תרומה קכו, ב."],["5311","122","<b>אל יקנא לבך</b>: משלי כג, יז. ראה גם אוה\"ת משלי כרך א ע' תריח ואילך."],["5312","124","<b>עלמא דאתכסיא</b>: ראה זהר בראשית יח, א. ויצא סתרי תורה קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך."],["5313","123","<b>לאה. . עלמא דאתכסיא</b>: ראה זהר סתרי תורה ויצא קנב, א. וארא כט, ב. ע\"ח שער מוחין דצלם שכ\"ג, פ\"ד."],["5314","125","<b>לאה ילדה ששה בנים</b>: ויצא ל, כ. ראה גם לקו\"ת להאריז\"ל ויצא (ד\"ה ענין בני לאה). תו\"ח שמות ח\"א יח, א. וש\"נ."],["5315","127","<b>שהעולם שהוא בבחי' מקום וזמן</b>: ראה שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. לקו\"ת בהר מא, ב. ברכה צח, א. לקו\"ש בא כרך כו ע' 62."],["5316","128","<b>שהעולם. . הוא בבחי' כיסוי והעלם</b>: ראה גם המשך חייב אדם לברך תרל\"ח פ\"כ."],["5317","126","<b>לאה. . בחי' </b>[ד: ליתא]<b> אותיות המחשבה</b>: ראה סידור שחרית ס, ג. סט, א. מאמרי אדה\"א נ\"ך ע' קג. וש\"נ. לעיל ע' תלז."]]],[4801940546,"כידוע דיעקב נשא שתי אחיות<sup data-n=\"5318\">129</sup> ויעקב הוא בחי' המדות<sup data-n=\"5319\">130</sup> והוא משפיע לבחי' לאה שהוא בחי' אותיות המח', הנה ידוע בפע\"ח שער הנהגת ע\"פ<sup data-n=\"5320\">131</sup> שיש ד' בחי' לאה ובחי' העליונה מד' בחי' הנ\"ל הוא בעטרת יסוד אבא במקומה ובחי' האחרונה הוא בעטרת יסוד אימא חוץ לאחורי ז\"א מבחוץ יעו\"ש. וע\"ד ההסבר בחי' האחרונה הוא בחי' הרהורי הלב שבוקעים ועולים אל המוח לחשוב ולהרהר בהם ובבחי' זאת המדות הם המשפיעים במחשבה שזה\"ע יעקב נשא ב' אחיות הנ\"ל, אך יש בחי' מחשבת שכל שהם אותיות דהשגה המולידים המדות, ויש בחי' אותיות המח' בעצם ההשכלה המוליד את המדות מצד עצם השכל למעלה מבחי' השגה כו', והוא בחי' העליונה דלאה ובחי' הק'<sup data-n=\"5321\">132</sup> דאותיות ההשגה שנק' מחשבת שכל ונק' אם לגבי המדות שהוא<sup data-n=\"5322\">133</sup> בחי' יעקב כו', וכמ\"ש בזהר ויצא ד' קנ\"ד ע\"ב וירא ה' כי שנואה לאה מהכא דסאני ב\"נ עריין דאימי' כו' וד\"ל. ..). משא\"כ בחי' רחל הוא עלמא<sup data-n=\"5323\">134</sup> דאתגלייא<sup data-n=\"5324\">135</sup> שהוא בחי' ירידת המל' להתלבש באותיות שנבראו בהם שמים וארץ שעי\"ז<sup data-n=\"5325\">136</sup> צירופי האותיות שנק' דבר ה' נראה העולם ליש ומסתיר על אור האלקי השופע בו וזהו בחי' ומשם יפרד<sup data-n=\"5326\">137</sup> (... וזהו עלמא דאתגלייא שהעולם שהוא בבחי' מקום וזמן הוא בהתגלות והאור האלקי המהווה אותו הוא מלובש בו בהסתר והעלם כו'. ..), אך אעפ\"כ האור האלקי המלובש בצירופי אותיות שנבראו בהם שמים וארץ תשוקתו בתמידות לצאת מגדרי הכלי ולעלות בבחי' כליון וביטול במקורה ולהיות בתכלית הביטול כמו בחי' עלמא דאתכסייא הנ\"ל וזה\"ע הקנאה דרחל באחותה כי קנאה נק' בחי' אהבה עזה כרשפי אש להיות בבחי' כלה שארי ולבבי<sup data-n=\"5327\">138</sup> (... והוא בחי' אהבה שהוא כמעלת הזהב על הכסף המבואר בלק\"א ח\"א פ\"נ שנק' קנאה כמאמר קשה כשאול קנאה רשפיה רשפי אש שלהבת י\"ה<sup data-n=\"5328\">139</sup> כי י\"ה הוא בחי' שלמעלה מהשתל' שנק' אור המאיר לעצמו כנ\"ל שהוא בחי' או\"א עילאין כנ\"ל<sup data-n=\"5329\">140</sup>. וההתבוננות בבחי' ביטול דמקור ההשתל' בלמעלה מהשתל' גורם הולדת אהבה כרשפי אש לצאת מגדרי הכלי וליכלל בלמעלה מהשתלשלות לגמרי לכן נק' בשם שלהבת י\"ה כו'. ומה שנק' בשם אחותה הגם<sup data-n=\"5330\">141</sup> שבחי' לאה בכל בחינתה<sup data-n=\"5331\">142</sup> הוא גבוה הרבה<sup data-n=\"5332\">143</sup> מבחי' רחל עד שנק' אם אפי' לגבי ז\"א כנ\"ל בהג\"ה מ\"מ<sup data-n=\"5333\">145</sup> מצד שרשם נק' אחותי כי שרש אותיות הדבור<sup data-n=\"5334\">144</sup> הוא בבחי'",[["5318","129","<b>דיעקב נשא שתי אחיות</b>: ויצא כט, טז ואילך."],["5319","130","<b>ויעקב. . המדות</b>: ראה סידור שחרית לשבת קפא, ב."],["5320","131","<b>בפע\"ח שער הנהגת ע\"פ</b>: דפוס קאריץ תקמ\"ב. לפנינו שער חג המצות שכ\"א, פ\"ד."],["5321","132","<b>הק'</b>: דהו: הנ\"ל."],["5322","133","<b>ונק' </b>[דה: נק']<b>. . שהוא</b>: תוקן ע\"פ דהו. ובכת\"י זה: הוא."],["5323","134","<b>רחל הוא עלמא דאתגלייא</b>: נסמן לעיל בהערה 123."],["5324","135","<b>עלמא דאתגלייא</b>: נסמן לעיל בהערה 124."],["5325","136","<b>שעי\"ז</b>: דה: שע\"י."],["5326","137","<b>ומשם יפרד</b>: בראשית ב, י."],["5327","138","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["5328","139","<b>קשה. . שלהבת י\"ה</b>: שה\"ש ח, ו."],["5329","140","<b>כנ\"ל</b>: ד: ליתא."],["5330","141","<b>הגם</b>: שם: אף."],["5331","142","<b>בכל בחינתה</b>: דה: וכל בחינותיה. ו: בכל בחינותיה."],["5332","143","<b>הרבה</b>: ניתוסף ע\"פ דהו."],["5333","145","<b>מ\"מ</b>: ניתוסף ע\"פ דהו."],["5334","144","<b>רחל. . הדבור</b>: ראה ע\"ח שער אח\"פ ש\"ד, פ\"א. סידור שחרית ס, ג. סט, א. מאמרי אדה\"א ויקרא ח\"א ע' רכז. וש\"נ. לעיל ע' תלז."]]],[4801940568,"חכמה עילאה כמאמר אבא יסד ברתא<sup data-n=\"5335\">146</sup> ושם הוא שרש בחי' העליונה דלאה שהוא בעטרת יסוד אבא במקומה כנ\"ל. ועוד אפ\"ל ששרש ב' מיני אותיות הנ\"ל דאותיות המח' ואותיות הדבור הם יותר נעלה בבחי' לובן העליון<sup data-n=\"5336\">147</sup> דעצמות אא\"ס ולכן נק' שתי בנות לבן<sup data-n=\"5337\">148</sup> כו' ע\"ש שרשם בלובן העליון<sup data-n=\"5338\">149</sup> כו' וד\"ל. ..).\n<b>והנה</b> בחי' אהבה כרשפי אש הנ\"ל הוא בחי' אהבה דבכל מאדך הנ\"ל והוא בבחי' רצוא, והעלאה זאת עולה לבחי' חכ\"ע ומעורר בחי' המשכה מלמעלה למטה ועי\"ז נעשה בחי' שוב ועי\"ז נעשה<sup data-n=\"5339\">150</sup> גילוי אא\"ס למטה כמו למעלה<sup data-n=\"5340\">151</sup> בעלמא דאתגלייא כמו בעלמא דאתכסייא (... והיינו שהם במהותם כמ\"ש בבחי' יש נברא ואעפ\"כ הם בתכלית הביטול כמו בעלמא דאתכסייא, משא\"כ הרצוא הוא בחי' הפשטת מהותם כו' וד\"ל. ..). וזהו ומעיין מבית ה' יוצא<sup data-n=\"5341\">152</sup> והשקה את נחל השטים, כי הנה כתי' ונהר<sup data-n=\"5342\">153</sup> יוצא מעדן נהר הוא בחי' יסוד אבא<sup data-n=\"5343\">154</sup> שהוא ממשיך בחי' הארה מחכמה עילאה<sup data-n=\"5344\">155</sup> ולא עצמית החכמה עילאה ולכן נק' בשם יוצא מעדן (... כי כל הארה לא תוכל להתגלות כ\"א ע\"י העלם העצמי' אז נראה ההארה בבחי' חוץ מן העצמות, משא\"כ כשהעצמי' מאיר אז ההארה נכללת בו בבחי' אין ואפס כזיו<sup data-n=\"5345\">156</sup> השמש בשמש כו' וד\"ל. ..), ואז נמשך להשקות את הגן בלבד שהוא בחי' בינה<sup data-n=\"5346\">157</sup> כו' או אפי' בחי' מל'<sup data-n=\"5347\">158</sup> כו' אבל מבחי' מל' בבי\"ע<sup data-n=\"5348\">159</sup> נמשכת ההארה בבחי' פירוד מן העצם וזהו ומשם יפרד כו', אבל כאשר ומעיין מבית ה' יוצא היינו שתהי' נמשך עצמות המהות<sup data-n=\"5349\">160</sup> בבחי' גילוי אז והשקה את נחל השיטים שהוא בחי' טורי דפרודא<sup data-n=\"5350\">161</sup> מקור תאות תענוגי עוה\"ז שגם הם יתהפכו ויהיו נכללים בבחי' ביטול באחדות ה' עד שמאיר אא\"ס למטה כמ\"ש למעלה, והיינו מטעם דאא\"ס שבחכ\"ע",[["5335","146","<b>אבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. תו\"ח שמות ח\"א יב, א."],["5336","147","<b>לובן העליון</b>: ראה בסמוך הערה 149."],["5337","148","<b>שתי בנות לבן</b>: ויצא כט, טז."],["5338","149","<b>לבן. . בלובן העליון</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' רכב. וש\"נ. תו\"ח ויצא קסח, ד ובהערה 31."],["5339","150","<b>ועי\"ז נעשה</b>: ניתוסף ע\"פ דהו."],["5340","151","<b>כמו למעלה</b>: ניתוסף ע\"פ דה. ו: כבפנים."],["5341","152","<b>ומעיין מבית ה' יוצא</b>: יואל ד, יח [וכ\"ה בסמוך בפנים. דה: ומעין יוצא מבית ה' — ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'א. שע\"ת סט, א הערה 1. תו\"ח בשלח ח\"א רנ, ג. מאמרי אדמו\"ר הצ\"צ תרט\"ו כאן ע' קטז]."],["5342","153","<b>ונהר יוצא מעדן. . יסוד אבא</b>: בראשית ב, י. ראה אוה\"ת וירא כרך ד ע' 1508: ”כן משמע בזח\"ב ס\"פ יתרו ד\"צ ע\"א וב\"פ ויקרא ד\"י ע\"ב וע' זח\"ג פ' אחרי דנ\"ח ע\"א יובל שמי' פי' במק\"מ חיבור או\"א וכן פי' במא\"א אות יו\"ד סל\"ח\"."],["5343","154","<b>ונהר יוצא. . יסוד אבא</b>: ד: בינה — ראה אוה\"ת שם: ”וברוב המקומות בזהר פי' ונהר יוצא מעדן היינו בינה\". ראה גם לעיל ס\"ע שעח ובהערה 100. ה: כתב: בינה וממעל לשורה כתב: יס\"א. ו: כבפנים."],["5344","155","<b>מעדן. . מחכמה עילאה</b>: ראה גם לעיל שם ובהערה 101."],["5345","156","<b>כזיו</b>: ד: כביטול זיו."],["5346","157","<b>הגן. . בינה</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ג מערכת גן."],["5347","158","<b>הגן. . מל'</b>: ראה פרדס שם. לעיל ע' קז ובהערה 30."],["5348","159","<b>בבי\"ע</b>: ד: לבי\"ע."],["5349","160","<b>עצמות המהות</b>: דהו: עצמי' הח\"ע."],["5350","161","<b>טורי דפרודא</b>: זהר בראשית כט, ב. ויצא קנח, א. פקודי רלד, סע\"א."]]],[4801940583,"הוא למעלה משני הבחי' דעלמא דאתגלייא דמל' ועלמא דאתכסייא דבינה<sup data-n=\"5351\">162</sup> ולכן כאשר מאיר הוא פועל הגילוי בעלמא דאתגלייא כמו בעלמא דאתכסייא בלי שום שינוי כלל וד\"ל (... וזה\"ע המבואר בזהר תרומה דקכ\"ו ע\"ב בענין קנאת סופרים אסגיאו משיכו דחכמתא עילאה לגבייהו היינו שיומשך החכמה עילאה בתוס' וריבוי שהוא המשכת עצמי' חכמה עילאה ולא הארה בלבד כסדר ההשתלשלות כו' וד\"ל. ..).\n<b>ומעתה</b> י\"ל ענין ב' מיני הילוך דבחי' פנים ובחי' אחוריים כי הנה יש ב' מיני נשמות הא' בחי' נשמות הגבוהות מבחי' אצי' שאצלם בחי' נקודת הלב שהוא בחי' רעו\"ד הוא בבחי' גילוי ממש והן הנק' עושין רצונו של מקום כי אצלם מאיר עצמות<sup data-n=\"5352\">163</sup> האהבה דבכל מאדך והם תמיד בבחי' כלות הנפש לעצמות אא\"ס המלובש בי\"ס דאצי' ולכן פועלים למעלה ג\"כ גילוי רצה\"ע שהוא בחי' עצמות הסובב שיתגלה בבחי' ממכ\"ע בבחי' גילוי ממש והיינו להיות שפועלים בעצמם בחי' שוב אחר הרצוא דאהבה דכל מאדך<sup data-n=\"5353\">164</sup> לקבל עליהם עומ\"ש ולבטל רצונם (... שהוא בבחי' כלות הנפש כנ\"ל)<sup data-n=\"5354\">165</sup> מפני רצון ה' להיות לו דירה בתחתונים ואז נתהפך הרצוא עצמו לשוב (ע' בב\"ז פ' תזריע<sup data-n=\"5355\">166</sup> ) והיינו שהאהבה כרשפי אש שהיתה מתחלה אצלם בבחי' רצוא עתה מתלבשת היא בתומ\"צ ללמוד תורה ולקיים מצותיו באהבה עזה כו'. ..), ולכן ממשיכים עצמות הסובב לבוא לידי גילוי למטה בבחי' ממכ\"ע כי ע\"י הרצוא יתעורר עצמות הסובב שבהעלם לבוא לידי גילוי<sup data-n=\"5356\">167</sup> וע\"י השוב הוא נמשך למטה כו', ולכן מאיר אצלם ד' אותית דשם הוי' כסדרן היינו מתחלה מאיר אצלם בחי' אהבה דבכל מאדך שהוא בחי' ה' ראשונה דשם הוי' (... וכוללת בתוכה בחי' יראה עילאה שהוא בחי' יו\"ד דשם הוי' כי ואהבת את<sup data-n=\"5357\">168</sup> כו' תיבת את מרבה בחי' יראה כו' כמבואר ברשימה דיונתי הנאמר בשנת תר\"ב <sup data-n=\"5358\">169</sup>... ), ואח\"כ נמשך אצלם בחי' ו\"ה דשם הוי' שהוא לימוד התורה וקיום המצות והוא<sup data-n=\"5359\">170</sup> פרשה ראשונה דק\"ש ובנשמות אלו מדבר בפ' ראשונה דק\"ש לכן אמר מתחלה ואהבת את כו'<sup data-n=\"5360\">171</sup> בכל מאדך שזהו בחי' ו\"ה<sup data-n=\"5361\">172</sup> כנ\"ל, ואח\"כ והיו הדברים האלה<sup data-n=\"5362\">173</sup> כו' ושננתם<sup data-n=\"5363\">174</sup> כו' שהוא בחי' וי\"ו דשם הוי', ואח\"כ וקשרתם<sup data-n=\"5364\">175</sup> כו' שכולל כל המצות במעשה (כידוע דהוקשה כל התורה לתפילין<sup data-n=\"5365\">177</sup> כו'<sup data-n=\"5366\">176</sup> ) שהוא בחי' ה' אחרונה דשם הוי' כו' וד\"ל.",[["5351","162","<b>דאתגלייא. . דבינה</b>: דהו: דאתכסייא. . דאתגלייא דמל'."],["5352","163","<b>עצמות</b>: ד ניתוסף: היחידה."],["5353","164","<b>דכל מאודך</b>: ניתוסף ע\"פ ד."],["5354","165","<b>כנ\"ל)</b>: שם: ליתא."],["5355","166","<b>בב\"ז פ' תזריע</b>: עב, א ואילך."],["5356","167","<b>למטה בבחי'. . גילוי</b>: ניתוסף ע\"פ ד. ואולי נשמט מפני תיבות הדומות: לידי גילוי. . לידי גילוי."],["5357","168","<b>ואהבת את</b>: ואתחנן ו, ה."],["5358","169","<b>ברשימה יונתי. . תר\"ב</b>: נדפס בפלח הרמון שה\"ש ע' מב."],["5359","170","<b>והוא</b>: ד: וזהו."],["5360","171","<b>כו'</b>: שם: הוי'."],["5361","172","<b>ו\"ה</b>: שם: י\"ה."],["5362","173","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["5363","174","<b>ושננתם</b>: שם שם, ז."],["5364","175","<b>וקשרתם</b>: ואתחנן שם, ח."],["5365","177","<b>דהוקשה כל התורה לתפילין</b>: ראה קדושין לה, א. סידור ערב שבת קסד, ב. תו\"ח וארא ח\"א סט, ב הערה 423. סה\"מ תרכ\"ט ע' רכה. לקו\"ש חנוכה כרך ה ע' 226."],["5366","176","<b>(כידוע. . לתפילין כו')</b>: ד: כידוע. . לתפילין."]]],[4801940594,"<b>והב'</b> הם בחי' נשמות הנמוכות ששרשם בבי\"ע ואצלם אינו מאיר נקודת הלב הנק' רעו\"ד<sup data-n=\"5367\">178</sup> בגילוי לכן העבודה שלהם הוא מלמטה למעלה היינו בתחילה צריכין לקיים המצות בבחי' יראה תתאה קבלת עומ\"ש והוא בחי' ה' אחרונה דשם הוי', ואח\"כ מגיעים ללימוד התורה ובחי' וי\"ו דשם הוי' (... וגם האהבה רבה<sup data-n=\"5368\">179</sup> שלהם הוא בחי' אהבה זוטא שנק' אהבת עולם שנמשך מהתבוננות דכי הוא חייך<sup data-n=\"5369\">180</sup> כו' וגם היראה שלהם נמשך מבחי' ההתבוננות בבחי' ריבוי רבבות העולמות איך דאיהו רב ושליט עליהם<sup data-n=\"5370\">181</sup> כו', וב' בחי' דאהבה ויראה אלו הם ג\"כ בחי' ו\"ה דשם הוי' כו'. ..), ולכן עבודת אהוי\"ר שלהם הוא בבחי' בכל לבבכם ובכל נפשכם בלבד רק אחר העבודה דתורה ומצות יעלו ויגיעו לבחי' אהוי\"ר עילאין אהבה דבכל מאדך ויראה עילאה שהוא בחי' ו\"ה דשם הוי' (כי גם אצלם מאיר אהבה דבכל מאדך, וראי' לדבר שגם בפסוק אחרי הוי' שהוא רק הילוך בבחי' אחוריים אמר אח\"כ ובו תדבקון כו'<sup data-n=\"5371\">182</sup> ), (... נמצא שמאיר אצלם בחי' ד' אותיות הוי' מלמטה למעלה כו'. ..), ובהם מדבר בפ' שני' דק\"ש לכן אמר וקשרתם קודם ולמדתם<sup data-n=\"5372\">183</sup> כו' ולכן הם נק' אין עושין רצונו של מקום כי הגם שאצלם מאיר אהבה דבכל מאדך כנ\"ל, אינו מאיר עצמות האהבה רק הארה בעלמא ממנה לפ\"ע עבודתם באהוי\"ר ותומ\"צ ולכן גם למעלה אינם גורמים להיות נמשך עצמות הסובב בממלא רק הארה בעלמא<sup data-n=\"5373\">184</sup> מבחי' הסובב ונמצא שלא נשלם על ידם הרצון שהוא להיות הגילוי למטה כמו למעלה ממש רק ע\"י נשמות הגבוהות שאצלם מאיר עצמות האהבה דבכל מאדך מצד שרש נשמתם בעצם לכן מעוררים למעלה ג\"כ עצם הרצון שהוא בחי' עצמות הסובב לבוא לידי גילוי<sup data-n=\"5374\">185</sup>, וממילא מתגלה למטה כמו למעלה בלי שום שינוי כלל כו' וד\"ל.\n<b>ומעתה</b> יובן הטעם דב' בחי' שמבואר בשני פסוקים דועמדו זרים כו' ואספת דגנך כו' שתלוי בעושין כו' ואין עושין כו', ויש בזה ב' טעמים הא' ע\"פ פשוט כי הנה ארז\"ל ע\"פ גבורי כח עושי דברו<sup data-n=\"5375\">186</sup> בשומרי שביעית הכתוב מדבר כו', כי הנה יש ב' בחי' בבעלי בטחון הא' שהוא עושה כלי לברכת ה' היינו שחורש בשעת חרישה וזורע בשעת זריעה כו' או עוסק במו\"מ רק שבוטח בה' שהוא ישלח ברכה והצלחה במעשה ידיו נמצא שבוטח בה' על אור השפע שישלח לו מלמעלה והוא בעצמו עושה הכלי להשפעה מלמטה כו', אך יש בחי' ב' בביטחון שהוא בוטח בה' שישלח לו גם הכלי מלמעלה כמאמר השלך על ה' יהבך והוא יכלכלך<sup data-n=\"5376\">187</sup> גם בבחי'",[["5367","178","<b>רעו\"ד</b>: זהר וירא ק, א."],["5368","179","<b>האהבה רבה</b>: ד: בחי' האוי\"ר."],["5369","180","<b>דכי הוא חייך</b>: נצבים ל, כ."],["5370","181","<b>דאיהו רב ושליט עליהם</b>: ראה זהר בהקדמה יא, ב."],["5371","182","<b>(כי. . כו')</b>: ד: כי. . כו'."],["5372","183","<b>וקשרתם קודם ולמדתם</b>: עקב יא, יח. יט."],["5373","184","<b>ממנה לפ\"ע. . בעלמא</b>: ד: ליתא. וכנראה נשמט מפני תיבות הדומות: רק הארה בעלמא. . רק הארה בעלמא."],["5374","185","<b>גילוי</b>: ד ניתוסף: אור."],["5375","186","<b>גבורי כח עושי דברו</b>: תהלים קג, כ. ויק\"ר פ\"א, א."],["5376","187","<b>השלך. . והוא יכלכלך</b>: תהלים נה, כג. ראה גם פלח הרמון וירא סב, ג. לקוטי ביאורים — ווארשא תרכ\"ח — הקדמת דרך חיים מז, ד. סה\"מ תרפ\"ח ע' כח. לקו\"ש יו\"ד שבט ח\"א ע' 134. עשרה בטבת כרך כ ע' 353."]]],[4801940601,"הכלים כו' (... וכמבואר לעיל דמ\"ח ע\"ב<sup data-n=\"5377\">188</sup> בשם הבעש\"ט<sup data-n=\"5378\">189</sup> ע\"פ ברוך הגבר<sup data-n=\"5379\">190</sup> אשר יבטח בה'<sup data-n=\"5380\">191</sup> כו' יעו\"ש. ..). והנה ב' בחי' בטחון אלו תלוי בשרש נשמתו, שבאם שרש נשמתו הוא ממקום גבוה (... בחי' אצי' כנ\"ל. ..) אזי נקודת הלב היא אצלו בבחי' גילוי כנ\"ל ממילא יש לו בטחון גם על הכלי שיושלח לו<sup data-n=\"5381\">192</sup> מלמעלה, משא\"כ כאשר שרש נשמתו הוא מבחי' בי\"ע אזי מוכרח לעשות כלי בעצמו ולבטוח בה' על שליחות אור השפע מלמעלה כו'. והנה שומרי שביעית אינם חורשין וזורעין ואינם עושים כלום רק בוטחים בה' שישלח מלמעלה אור השפע וגם הכלים, כמאמר וצויתי את ברכתי<sup data-n=\"5382\">193</sup> כו' הנה זה מורה על שנתגלה אצלם בחי' נקודת הלב הנק' רעו\"ד בגילוי גמור ולכן נק' גבורי בשם כח היינו שהתגברו בעצמם להביא בחי' יחידה שנעלם בנקודת הלב לידי גילוי (... ובחי' חי' יחידה נק' כח כמבואר בב\"ז פ' פנחס<sup data-n=\"5383\">194</sup> ע\"פ כל אשר תמצא ידך לעשות בכחך<sup data-n=\"5384\">195</sup> כו' יעו\"ש)<sup data-n=\"5385\">196</sup>, ולכן נק' עושי דברו היינו שמתקנים דבר ה' שהוא בחי' מל' דאצי' שהוא בחי' ממכ\"ע וממשיכים בה בחי' עצמות הסוכ\"ע בבחי' גילוי ממש למטה כמו למעלה כנ\"ל בענין עושין רש\"מ כו'. ..). והנה בזה יובן ג\"כ שלכן בנשמות שנק' עושין רצונו של מקום נאמר ועמדו זרים כו' כי גם הכלי נשלח אצלו מלמעלה כו' כנ\"ל. משא\"כ באותן שאין עושין רצונו של מקום נא' ואספת דגנך<sup data-n=\"5386\">197</sup> שצריכים לעשות בעצמם הכלי להשפעה לכן נאמר אצלם ואספת דגנך כו' וזהו טעם הפשוט.\n<b>אך</b> יש עוד טעם ב' והוא כי ואספת דגנך הוא ע\"ד ששת ימים תעבוד<sup data-n=\"5387\">198</sup> דלכאורה קשה הלא ששת ימים תעבוד אינו מצוה והי' לו לומר רק וביום השביעי תשבות שזהו עיקר המצוה כו'. אך הענין דתעבוד קאי על עבודת הבירורים בעצמו להפוך ולברר נפשו הטבעי' שתתהפך לאהבה את ה' (שיש בזה כל העבודות חרישה וזריעה ברוחניות כו')<sup data-n=\"5388\">199</sup>, וגם לברר דצ\"ח שבעולם ע\"י התורה והמצות כו', ומזה נעשה אח\"כ יום השבת<sup data-n=\"5389\">200</sup> כמבואר במ\"א, וכ\"ה בכאן בענין ואספת דגנך דקאי על עבודת הבירורים כו' ולכן אינו צריך לזה רק מי שלא הגיע לגילוי עצמות האהבה דבכל מאדך שבא מצד גילוי עצמות היחידה וממילא לא נתברר אצלו נפשו הטבעית בשלימות מן הרע<sup data-n=\"5390\">201</sup> שבה, ולכן צריך עדיין לעבודת הבירורים כו', משא\"כ מי שהגיע לבחי' גילוי עצמות האהבה דבכל מאדך ממילא נגלה עצמות היחידה אצלו, וזה לא יוכל להיות כ\"א כאשר כבר<sup data-n=\"5391\">202</sup> נתבררה ונזדככה נפשו הטבעית בשלימות מן",[["5377","188","<b>לעיל דמ\"ח ע\"ב</b>: כנראה הכוונה לבוך כת\"י של ר' הלל."],["5378","189","<b>דמ\"ח ע\"ב בשם הבעש\"ט</b>: דה: ליתא. ו: כבפנים."],["5379","190","<b>בשם הבעש\"ט ע\"פ ברוך הגבר</b>: ראה גם פלח הרמון וירא סב, ג. כתר שם טוב קה\"ת מהדורת תשנ\"ט סנ\"א ובהערה שם."],["5380","191","<b>ברוך הגבר אשר יבטח בה'</b>: ירמי' יז, ז."],["5381","192","<b>לו</b>: ניתוסף ע\"פ דה."],["5382","193","<b>וצויתי את ברכתי</b>: בהר כה, כא."],["5383","194","<b>בב\"ז פ' פנחס</b>: קי, א ואילך."],["5384","195","<b>כל אשר תמצא ידך לעשות בכחך</b>: קהלת ט, י."],["5385","196","<b>יעו\"ש)</b>: ד: יעו\"ש."],["5386","197","<b>נא' ואספת דגנך</b>: ניתוסף ע\"פ ד."],["5387","198","<b>ששת ימים תעבוד</b>: תשא לד, כא."],["5388","199","<b>(שיש. . כו')</b>: ד: שיש. . כו'."],["5389","200","<b>ומזה נעשה אח\"כ יום השבת</b>: ראה גם אוה\"ת תשא ע' א'תתקנד."],["5390","201","<b>מן הרע</b>: ד: בנר\"נ."],["5391","202","<b>כבר</b>: ניתוסף ע\"פ ד."]]],[4801940607,"הרע שבה מ\"מ<sup data-n=\"5392\">203</sup> אינו צריך כלל<sup data-n=\"5393\">204</sup> לעבודת הבירורים רק כל עבודתו הוא המשכת תוס' אורות עליונים למעלה וגם בנפשו כו' (... וממילא נעשה הבירורים בבחי' דצ\"ח שבעולם שלא נתבררו עדיין בשלימות כמשל האבוקה<sup data-n=\"5394\">205</sup> שממשיך כל הניצוצות אליו כו'. ..), וזהו ועמדו זרים ורעו<sup data-n=\"5395\">206</sup> כו' כלומר שמלאכתו שהם הבירורים נעשית ממילא ומאיליו כו' וד\"ל.\n<b>(והנה</b> ב' בחי' הילוך הנ\"ל דהילוך בבחי' פנים והילוך בבחי' אחוריים נוכל לומר שהם ב'<sup data-n=\"5396\">207</sup> בחי' דצדיקים גמורים וצדיקים שאינם גמורים ובינונים, כי שרש הבינונים הוא נשמות דיצי' ועשי', וצדיק שאינו גמור שרש נשמתו מבריאה ונשמות דבי\"ע ההילוך שלהם הוא מלמטה למעלה כנ\"ל, שזהו הילוך בבחי' אחוריים, אך צדיקים גמורים הם נשמות דאצי' הילוכם מלמעלה למטה בבחי' פנים כנ\"ל באריכות. אך לפי המבואר לעיל בהג\"ה<sup data-n=\"5397\">208</sup> שיש ב' מיני מקום, מקום דצדיקים גמורים ומקום דבעלי תשובה, מובן ממילא שב' מיני הילוך הנ\"ל הוא להמשיך מבחי' הנה מקום אתי לבחי' הוא<sup data-n=\"5398\">209</sup> מקומו של עולם היינו מבחי' סובב לממכ\"ע, כי בחי' ממכ\"ע נק' מקומו של עולם ובחי' סוכ\"ע נק' הנה מקום אתי להיות שהמקום דממכ\"ע נכלל ובטל בבחי' סוכ\"ע כנ\"ל בהג\"ה באריכות. רק שהנשמות שהילוכם הוא בבחי' אחרי הוי' הם ממשיכים רק הארת הסובב בממלא ונק' אין עושין רצונו של מקום, והנשמות שהילוכם בבחי' פנים ממשיכים עצמות הסובב בממלא ונק' עושין רצונו של מקום היינו שממשיכים הרצון שהוא בחי' סובב בממכ\"ע שנק' מקום. אך באמת יש עוד ב' מיני הילוך בבע\"ת, והיינו כמבואר למעלה שהמקום דבע\"ת הוא בחי' סוכ\"ע מטעם המבואר ברשימה שלי דתר\"ב בהג\"ה<sup data-n=\"5399\">210</sup> להיות שהכלי שלהם הוא מאנין תבירין לכן המקום שהוא הכלי שלהם בו שורה בחי' המקום דסוכ\"ע, ומה שנק' אצלם הנה מקום אתי היינו בחי' התכללות המקום דסוכ\"ע בבחי' אתה הוי' לבדך שלמעלה מבחי' סובב וממלא שעבודתם הוא להמשיך מבחי' הנה מקום אתי שהוא התכללות המקום שלהם בבחי' עצמות אא\"ס שלמעלה מבחי' סובב וממלא (כנ\"ל<sup data-n=\"5400\">212</sup> בהג\"ה שזהו בחי' אא\"ס המלובש באו\"א עילאין שלמעלה מבחי' בינה מקור המדות כו')<sup data-n=\"5401\">211</sup>, וזהו בחי' אתה הוי' לבדך הנ\"ל לבחי' המקום שלהם שהוא בחי' סוכ\"ע, וזהו ג\"כ ענין ההילוך שלהם להמשיך מבחי' עצמות הוי' כמ\"ש לבדו בבחי' סוכ\"ע.\n<b>ועד\"ז</b> יובן ג\"כ שבהילוך שלהם יש ג\"כ ב' בחי'<sup data-n=\"5402\">213</sup> הילוך בבחי' אחוריים והילוך בבחי' פנים, הילוך בבחי' אחוריים הוא בנשמות דבי\"ע שההילוך שלהם הוא בחי' תשובה תתאה ששב מן המיצר כאשר מתבונן בעוצם ריחוקו מצד כל",[["5392","203","<b>מ\"מ</b>: שם: ליתא."],["5393","204","<b>כלל</b>: ניתוסף ע\"פ ד."],["5394","205","<b>כמשל האבוקה</b>: ראה גם לעיל ע' תסה. וש\"נ."],["5395","206","<b>זרים ורעו</b>: ניתוסף ע\"פ ד."],["5396","207","<b>ב'</b>: שם: ג'."],["5397","208","<b>לעיל בהג\"ה</b>: על יד הערה 92."],["5398","209","<b>הוא</b>: ניתוסף ע\"פ ד."],["5399","210","<b>ברשימה שלי דתר\"ב בהג\"ה</b>: (ד: ברשימה הנ\"ל — הכוונה להנזכר לעיל על יד הערה 83) לעיל ע' תעב."],["5400","212","<b>כנ\"ל בהג\"ה</b>: על יד הערה 101."],["5401","211","<b>(כנ\"ל. . כו')</b>: ד: כנ\"ל. . כו'."],["5402","213","<b>בחי'</b>: ד: מיני."]]],[4801940613,"המחשבות ודיבורים ומעשים אשר לא לה' המה שעי\"ז נעשה אצלו רצון פשוט שלמעלה מן הטעם לגמרי שמואס בחייו לגמרי ולהיות כלה שארי ולבבי, ולהיות שכלות הנפש שלו הוא מצד המנגד שהוא הריחוק בעצם<sup data-n=\"5403\">214</sup> לזאת מגיע למעלה מבחי' כלות הנפש דצד\"ג שאצלם הכליון הוא מצד עוצם העריבות ומתיקות שמרגישים בבחי' האור שלמעלה כי בצדיקים גמורים אינם מגיעים רק לבחי' סוכ\"ע ובע\"ת יגיעו בכלות נפשם לבחי' העצמות שלמעלה מבחי' סוכ\"ע כו'. אך אעפ\"כ לא יגיעו רק לבחי' הארת העצמי' וממשיכים אותו בבחי' סובב כו', ולכן נק' בשם אין עושין רצונו של מקום בבחינתם כו', משא\"כ ההילוך בבחי' פנים בבע\"ת הוא בחי' תשו\"ע והיינו תשובה שאינה באה מצד הריחוק רק מצד ההסתכלות דאמיתית הביטול דסוכ\"ע וממכ\"ע לגבי אור העצמו' דבחי' אתה הוי' לבדך כו' (והם<sup data-n=\"5404\">215</sup> נשמות שנולדים בבחי' תאומים עם בחי' ז\"א בהיותם<sup data-n=\"5405\">216</sup> בבחי' עיבור באימא עילאה והם הנק' אחים ממש לז\"א כו' עיין בב\"ז פ' פנחס במאמר האיילת<sup data-n=\"5406\">217</sup> כו'<sup data-n=\"5407\">218</sup> ), וההסתכלות זאת אצלם הוא ע\"י לימוד התורה כמאמר גל עיני ואביטה נפלאות<sup data-n=\"5408\">219</sup> כו', שהוא ביטול דסובב וממלא בבחי' העצמות שנק' נפלאות ב' מיני פלא, והבטה זאת הוא מתורתך כו' להיות שהתורה קדמה לעולם בחי' סובב וממלא רק שרשה בבחי' העצמי' המלובש בחכמה<sup data-n=\"5409\">221</sup> עילאין שנק' אלפיים שנה<sup data-n=\"5410\">220</sup> אאלפך חכמה אאלפך<sup data-n=\"5411\">222</sup> בינה<sup data-n=\"5412\">223</sup> כו', וידוע דהתורה נק' תשו\"ע כמבואר באיגרת התשובה פ\"ח בשם הרע\"מ פ' נשא<sup data-n=\"5413\">224</sup> יעו\"ש, ועיין במאמר מה טובו הנאמר תר\"ב<sup data-n=\"5414\">226</sup> ברשימה שלי<sup data-n=\"5415\">225</sup> בענין תשובה דנשמה שזהו בחי' לימוד התורה. והנה ע\"י לימוד זה ממשיכין בחי' עצמות ממש בבחי' סובב וממלא כו'<sup data-n=\"5416\">227</sup>, ונק' זה עושין רצונו של מקום היינו הרצון הוא בחי' העצמי' שלמעלה מבחי' סובב וממשיכים אותו בבחי' המקום דסובב וזהו בחי' הילוך בבחי' פנים דבע\"ת, כ\"ז נלע\"ד<sup data-n=\"5417\">228</sup> בדא\"פ כו' וד\"ל. ..).\n<b>ומעתה</b> י\"ל ענין והתהלכתי בתוככם וענין המדרש במשל דמלך ואריס, דהנה כדוגמת ב' מיני הילוך דעכשיו בבחי' פנים ואחוריים שהוא בבחי' או\"י שמלמעלה למטה ובבחי' אור<sup data-n=\"5418\">229</sup> חוזר מלמטה למעלה ועל ידם נמשך הארת הסובב",[["5403","214","<b>בעצם</b>: שם: העצום."],["5404","215","<b>(והם</b>: שם: והם."],["5405","216","<b>בהיותם</b>: ניתוסף ע\"פ ד."],["5406","217","<b>בב\"ז פ' פנחס במאמר האיילת</b>: קיד, ד ואילך."],["5407","218","<b>כו')</b>: ד: כו'."],["5408","219","<b>גל עיני ואביטה נפלאות</b>: תהלים קיט, יח."],["5409","221","<b>בחכמה</b>: ד: בחו\"ב."],["5410","220","<b>שהתורה קדמה לעולם. . אלפיים שנה</b>: ראה שבת פח, ב וברש\"י שם. מדרש תהלים צ, ד. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["5411","222","<b>אלפים שנה. . אאלפך בינה</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשח. המשך והחרים תרל\"א ע' כו. וככה תרל\"ז פקי\"ז (ע' קפג). סה\"מ תרל\"ח ע' יד."],["5412","223","<b>אאלפך חכמה אאלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["5413","224","<b>הרע\"מ פ' נשא</b>: קכג, סע\"א."],["5414","226","<b>הנאמר תר\"ב</b>: ד: ליתא."],["5415","225","<b>במאמר מה טובו הנאמר תר\"ב ברשימה שלי</b>: יודפס בע\"ה בפלח הרמון פ' בלק."],["5416","227","<b>סובב וממלא כו'</b>: שם: סוכ\"ע."],["5417","228","<b>כ\"ז נלע\"ד</b>: שם: כנלפע\"ד."],["5418","229","<b>בבחי' או\"י. . אור</b>: שם: מלמעלה למטה ואור."]]],[4801940618,"בממלא ועצם הסובב בממלא<sup data-n=\"5419\">230</sup> (... ועוד יש ב' מיני הילוך בבע\"ת שממשיך הארת העצמי' בבחי' סובב וממלא בב' אופנים הנ\"ל כנ\"ל הכל באריכות. ..) כן יהי' לע\"ל ב' מיני הילוך הנ\"ל (... וגם בב' אופנים דצ\"ג ובע\"ת כו'. ..), רק ההפרש הוא דעכשיו כל בחי' הילוך הנ\"ל הוא בחי' הילוך הנשמות בבחי' הוי' דאצי' (... שיש בו כל הבחי' ממכ\"ע הוא בחי' ה' אחרונה דשם הוי' בחי' המל' דאצי' ובחי' בינה דאצי' מקור המדות עם המדות הוא בחי' וי\"ו דשם הוי' הוא בבחי' סוכ\"ע ובבחי' זאת מגיע ההילוך דצד\"ג ועצמות החו\"ב שהם בחי' י\"ה דשם הוי' הוא בחי' אתה הוי' לבדך ובבחי' זאת מגיע ההילוך דבע\"ת כנ\"ל. ..). אך לע\"ל יהי' ההילוך בשם הוי' עצמו<sup data-n=\"5420\">231</sup> והיינו מעצמות אא\"ס שלפני הצמצום בבחי' שם הוי' שהוא בחי' אא\"ס המלובש בי\"ס<sup data-n=\"5421\">232</sup> דאצי' (... ושם יש ג\"כ כל הבחי' בחי' שפע הממלא הנק' עמידה והוא בחי' הקו\"ח המשפיע בג' עולמות א\"ק ועתיק ואריך וי\"ס דאצי' שנק' ג' מיני אדם<sup data-n=\"5422\">233</sup>, אדם דבריאה ואדם דיצירה אדם דעשי' כידוע, וההתחדשות בבחי' הקו\"ח עצמו הוא מבחי' המדידה שכבר נמדד בהעלם שהוא בחי' גליף גליפו<sup data-n=\"5423\">234</sup> בטהירו עילאה שיער בעצמו בכח<sup data-n=\"5424\">235</sup> מה שעתיד להיות בפועל, ובחי' הילוך הוא בחי' שפע המשכת הסובב בממלא, ובחי' סוכ\"ע הוא בחי' מל' דא\"ס וחסד דא\"ס שגילוי בחי' המדות אלו בבחי' העצמי' ע\"י הרצון לזה שהוא הרצון להיטיב ומח' דאנא אמלוך<sup data-n=\"5425\">236</sup> נק' א\"ס ששפע זאת אינו בא במדה ושיעור, ושפע העצמות ממש הנק' יחיד שגם בחי' א\"ס לא יתכן לקרותו להיותו למעלה מגדר גילוי, וכל הבחי' הנ\"ל יומשכו ויתגלו בבחי' הי\"ס דאצי' ולכן לע\"ל יהיו מקיפים ופנימי' חדשים כי הפנימי' יהי' בחי' גילוי הסובב בממלא והמקיפים יהיו מבחי' גילוי העצמות בבחי' סובב וזהו ענין השמים החדשים והארץ החדשה<sup data-n=\"5426\">237</sup> כו' וד\"ל. ..).\n<b>אך</b> הילוך זה שיתגלה בבחי' שם הוי' עצמו מבחי' עצמות אא\"ס בב' אופנים דאו\"י ואו\"ח יתגלה ג\"כ בנשמות שהם ג\"כ יקבלו עצמות האורות שיומשכו מעצמות אא\"ס בבחי' שם הוי' עצמו וזהו והתהלכתי בתוככם (... ולא אמר והלכתי בתוככם, כי התהלך הוא בנין הפועל פעולה בעצמו כידוע למדקדקים, והכוונה שאקבל בעצמי שפע חדשה מעצמות אא\"ס המאציל ואותו השפע יהי' נמשך בתוככם כו' וד\"ל. ..). וע\"ד דוגמא דהיא מתהלכת בין החיות<sup data-n=\"5427\">238</sup>, שהכוונה ג\"כ שנפעל בעצם המל'<sup data-n=\"5428\">239</sup> בחי'",[["5419","230","<b>ועצם הסובב בממלא</b>: שם: ליתא."],["5420","231","<b>עצמו</b>: שם: העצמי'."],["5421","232","<b>בי\"ס</b>: שם: בחכ'."],["5422","233","<b>ג' מיני אדם</b>: ראה מאמרי אדה\"ז על ענינים בתחילתו ובהנסמן במ\"מ לשם. אוה\"ת על ענינים ע' עז. סה\"מ תש\"ח ע' 113 בהערה. הנסמן בסה\"מ תרל\"ב ח\"א ע' ד."],["5423","234","<b>גליף גליפו</b>: ראה זהר בראשית טו, א. לעיל ע' תמד הערה 61."],["5424","235","<b>שיער בעצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ. לעיל ע' פה ובהערה 30."],["5425","236","<b>ומח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["5426","237","<b>השמים החדשים והארץ החדשה</b>: ישעי' סו, כב."],["5427","238","<b>דהיא מתהלכת בין החיות</b>: יחזקאל א, יג."],["5428","239","<b>דהיא. . המל'</b>: ראה לקו\"ת במדבר י, א. המשך תער\"ב ח\"ב ס\"ע א'יט."]]],[4801940623,"הילוך ע\"י השפע שהוא משפיע בבחי' חיות שבמרכבה כידוע דהחיות נושאות את הכסא<sup data-n=\"5429\">240</sup> ע\"י ביטולם לבחי' הכסא ואדם שעל הכסא עי\"ז מנשאים את הכסא והאדם<sup data-n=\"5430\">241</sup> שעהכ\"ס<sup data-n=\"5431\">242</sup> למקום שלא יוכל להגיע מעצמו (... כידוע דשרש החיות שבמרכבה גבוה יותר בבחי' התהו שקדם לתיקון ועי\"ז שמתבררים ונהפכים מיש לאין ע\"י המל' דאצי' עולה החיות שבהם לשרשם בבחי' אורות ומעוררים וממשיכים אורות הנ\"ל שיומשכו בבחי' הכלים במל' דאצי' ואורות דתהו הם אורות חדשים להיותם בלתי מוגבלים כידוע, ולכן השפע שלהם נק' בחי' הילוך וזהו ההילוך שבבחי' מל' דאצי' עצמו כו'. ..). כ\"ה בכאן ענין והתהלכתי בתוככם היינו שיומשך בו בחי' הילוך שפע חדשה מעצמות אא\"ס (... ולגבי הילוך זה נק' בחי' הילוך דמאצי' לבי\"ע בשם עמידה כמבואר ברשימה דתר\"ב<sup data-n=\"5432\">243</sup> יעו\"ש. ..), ואותו ההילוך יהי' נמשך בתוככם.\n<b>וביאור</b> הדברים יש להקדים מאמר אז תתענג על הוי'<sup data-n=\"5433\">244</sup> על דוקא למעלה מבחי' שם הוי' (... וכדוגמא דכתיב גבי חנה ותתפלל על הוי'<sup data-n=\"5434\">245</sup> מצד שרצתה להמשיך בחי' בנים דבמזלא תליא<sup data-n=\"5435\">246</sup> שהוא בחי' שלמעלה משם הוי' שבחכ\"ע כו' וד\"ל. ..). והענין יובן ע\"ד דוגמא מבשרי אחזה<sup data-n=\"5436\">247</sup> שכשאדם משכיל שכל חדש שנתמלא נפשו מתענוג, וא\"א לומר שהתענוג עם השכל אחד הוא שא\"כ הי' צ\"ל נמצא התענוג במי ששומע את השכל ג\"כ בשוה כמו במי שהמציא את השכל ממקורו, וע\"כ צ\"ל שמקור התענוג הוא למעלה ממקור השכל רק שבכח ומקור התענוג כלול כח ומקור להשכיל שכל ומקור השכל מתייחד<sup data-n=\"5437\">249</sup> עם מקור התענוג<sup data-n=\"5438\">248</sup> ולכן הממציא את השכל ממקורו מעורר מקור התענוג שיומשך עמו ולכן הוא מלא מתענוג, משא\"כ במי ששומע את השכל אינו מאיר התענוג רק הארה מועטת כו', והנה באדם בחי' התענוג הוא מורכב באיזה מציאות דבר מה משא\"כ למעלה לא יתכן להתענג מאיזה דבר רק למעלה מציאות התענוג הוא מקור המשפיע כל מיני תענוג והוא בחי' א\"ס מקור כל התענוגים<sup data-n=\"5439\">250</sup> (... אך מבואר בכמה",[["5429","240","<b>דהחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["5430","241","<b>מנשאים את הכסא והאדם שעהכ\"ס</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' קעא. תקס\"ט ע' קנג. תו\"א יתרו עב, ב. לעיל ע' כג. פלח הרמון שה\"ש ס\"ע 84 ואילך."],["5431","242","<b>והאדם שעהכ\"ס</b>: ניתוסף ע\"פ ד."],["5432","243","<b>ברשימה דתר\"ב</b>: ראה מאמר ד\"ה והתהלכתי שנדפס לפנ\"ז בסופו."],["5433","244","<b>אז תתענג על הוי'</b>: ישעי' נח,יד. ראה גם לעיל ס\"ע רסח ובהערה 31."],["5434","245","<b>ותתפלל על הוי'</b>: שמו\"א א, י. ראה תו\"א בא ס, ג. משפטים עט, סע\"א ואילך. לקו\"ת במדבר ח, ד. נצבים מח, ב. דרושים לש\"ת סה, א. סו, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' קעא."],["5435","246","<b>בנים דבמזלא תליא</b>: מוע\"ק כח, א. ראה סה\"מ תרל\"ג ח\"א ע' רלח ואילך. ע' רמז ואילך."],["5436","247","<b>דוגמא מבשרי </b>[ד: ומבשרי]<b> אחזה</b>: ע\"פ איוב יט, כו."],["5437","249","<b>מתייחד</b>: ד: הוא מתאחד."],["5438","248","<b>שמקור התענוג. . ומקור השכל. . מקור התענוג</b>: ראה גם לעיל ע' רסו. ע' תכו. תו\"ח יתרו ח\"ב רסז, ג. וש\"נ."],["5439","250","<b>א\"ס מקור כל התענוגים</b>: ראה גם ע\"ח שער א\"א שי\"ג, רפ\"ב. מבו\"ש ש\"ג, ח\"א פ\"א. ח\"ב פ\"י. שער מאמרי רשב\"י לריש אד\"ז רלה, ב."]]],[4801940628,"מקומות שגם שם אא\"ס לא יתכן רק בבחי' מל' דא\"ס<sup data-n=\"5440\">251</sup> שנמשך ע\"י ירידת העצמות שהוא הרצון להיות מלך על עם וכל רצון מוכרח להיות ע\"י עונג והעונג הוא עונג פרטי להתענג מבחי' מדת המלוכה ועונג הפרטי הזה הוא נמשך מבחי' שעשועי המלך בעצמותו<sup data-n=\"5441\">252</sup> שזהו אמיתית המקור לכל מיני תענוג הנמשכים למטה כו' וד\"ל. ..).\n<b>והנה</b> בחי' זאת דאא\"ס מקור כל התענוגים הוא למעלה הרבה מבחי' חכ\"ע, וזהו על הוי', כי הוי' הוא בחכ'<sup data-n=\"5442\">253</sup> כי היו\"ד דשם הוי' הוא בחי' חכ\"ע שנמשך ע\"י צמצום מאא\"ס וכידוע דנקודה דיו\"ד הוא מורה על בחי' צמצום כו', משא\"כ אא\"ס הוא הגבה מאד נעלה מבחי' חכמה עילאה עד שהחכמה נחשב לבחי'<sup data-n=\"5443\">254</sup> עשי'<sup data-n=\"5444\">255</sup> כמאמר כולם בחכמה עשית<sup data-n=\"5445\">256</sup>, ועם זה יובן ענין ההילוך בשם הוי' עצמו היינו שנמשך בשם הוי' בחי' תוס' אורות מבחי' אא\"ס מקור כל התענוגים כנ\"ל (... ועוד הגבה יותר מבחי' שעשועי המלך בעצמותו כנ\"ל בהג\"ה. ..), וזה\"ע אז תתענג על הוי' היינו שתקבל השפע ממקור כל התענוגים שהוא למעלה משם הוי' שמשם נמשך תוס' אורות בש' הוי' ואותו השפע תהי' נמשכת בך ג\"כ, ובחי' זאת היא מאירה ביראי ה' וחושבי שמו<sup data-n=\"5446\">257</sup> בכל שבת ושבת רק אעפ\"כ ההארה דשבת הוא מעין לע\"ל (... וכן בכל חצות לילה מאיר מעין השפע דלע\"ל, וזהו דקוב\"ה אתא לאשתעשע<sup data-n=\"5447\">258</sup> בגנתא דעדן עם צדיקייא כו'. ..). אך עיקר הגילוי<sup data-n=\"5448\">259</sup> יהי' לע\"ל כו' שאזי יקבלו נש\"י בגופים שפע התענוג הנמשך בשם הוי' עצמו<sup data-n=\"5449\">260</sup> בשוה עמו כבי' (... וזהו והתהלכתי בתוככם שההילוך שיומשך בו יומשך בתוככם בשוה עמו ממש כבי'. ..).\n<b>ובזה</b> יובן מאמר<sup data-n=\"5450\">261</sup> המדרש שדימה הצדיקים עם הקב\"ה לאריס עם המלך כו' כי הגם שלמעלה לא יתכן שלימות מן עבודת הצדיקים, היינו דוקא בעצמות אא\"ס, אבל בבחי' שם הוי' שבאצי' שנק' מלך (... וכמאמר הת\"ז מלכא איהו וחיוהי<sup data-n=\"5451\">262</sup> חד בהון כו'. ..) יתכן שלימות מן העבודה כי ע\"י עבודת הצדיקים גורמים תוספת אורות בשם הוי' עצמו כבי', וזהו ענין מה שהקב\"ה מטייל עם הצדיקים בג\"ע כו',",[["5440","251","<b>שם אא\"ס. . מל' דא\"ס</b>: ראה גם לעיל ע' תטו בשם הה\"מ ובהערה 11."],["5441","252","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["5442","253","<b>הוי' הוא בחכ'</b>: ראה זהר רע\"מ פינחס רנה, רע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלה."],["5443","254","<b>שהחכמה נחשב לבחי' עשי'</b>: ראה תניא פ\"ב בהגהה. הנסמן במאמרי אדה\"א קונטרסים ע' רנב. סה\"מ תרל\"ח ס\"ע קג ובהערה 223."],["5444","255","<b>נחשב לבחי' עשי'</b>: ד: נחשבת כעשי' גשמי'."],["5445","256","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["5446","257","<b>ביראי ה' וחושבי שמו</b>: ע\"פ מלאכי ג, טז."],["5447","258","<b>דקוב\"ה אתא לאשתעשע</b>: ראה זהר אחרי סז, ב. לך עז, א. לעיל ע' רסו."],["5448","259","<b>אך עיקר הגילוי</b>: ד: אבל העיקר."],["5449","260","<b>בשם הוי' עצמו</b>: שם: ליתא."],["5450","261","<b>מאמר</b>: שם: ליתא."],["5451","262","<b>מלכא איהו וחיוהי</b>: ראה ת\"ז בהקדמה ג, ב."]]],[4801940633,"(... טייל הוא ל' תענוג<sup data-n=\"5452\">263</sup> מפולש<sup data-n=\"5453\">264</sup> שאינו מורכב בשום דבר והו\"ע גילוי שעשועי המלך בעצמותו כנ\"ל. ..) ואומר להם הריני כיוצא בכם היינו שמקבל אור השעשועים עמם בשוה וממילא לא יהיו צריכים להזדעזע כי ענין זעזוע הוא ביטול המהות לגמרי כדוגמת איבוד החושים בנביאים<sup data-n=\"5454\">266</sup> בעת קבלת הנבואה<sup data-n=\"5455\">265</sup>, ולע\"ל לא יצטרכו לזה כי יהיו שלמים במהותם בכל החושים שלהם, ואעפ\"כ יקבלו אור השעשועים המאיר בשם הוי' עצמו כנ\"ל כו'.\n<b>יכול</b> לא תהי' מוראי עליכם ת\"ל והייתי לכם לאלקים ואתם תהיו לי לעם, הענין הוא שאע\"פ שיקבלו אור השעשועים בשוה עם שם הוי' עצמו<sup data-n=\"5456\">267</sup> כבי' מ\"מ יקבלו אותו ע\"י שם הוי' מצד דבחי' הוי' הוא בחי' אלקים איהו וחיוהי חד איהו וגרמוהי חד וכמאמר אני הוי' כולא חד<sup data-n=\"5457\">268</sup> משא\"כ הנשמות נבראו מאין ליש כו', נמצא ששם הוי' הוא המשפיע להם והם המקבלים ממנו כו', ולכן צריכים להיות בטלי' להוי' בתכלית אך לא יצטרכו לאיבוד החושים מצד שיזדכך חומר גופם בתכלית עד שיקבלו האור בשוה עם הנשמה (... וכדוגמת משה שהי' מדבר בבחי' פב\"פ כאשר ידבר איש אל רעהו<sup data-n=\"5458\">269</sup> כו'. ..), וזהו והייתי לכם לאלקים ואתם תהיו לי לעם ולכן תהי' מוראי עליכם כמו מקבל למשפיע שהוא בבחי' ביטול אליו כו' וד\"ל. וזהו ג\"כ מה שאמר יעקב אע\"ה ושבתי בשלום<sup data-n=\"5459\">270</sup> אל בית אבי שהוא בחי' יצחק שהוא מלשון צחוק<sup data-n=\"5460\">271</sup> ותענוג שהוא בחי' גילוי השעשועים שיתגלה<sup data-n=\"5461\">272</sup> לע\"ל, ואעפ\"כ והי' הוי' לי לאלקים בבחי' משפיע אלי כו' וד\"ל.",[["5452","263","<b>טייל הוא ל' תענוג</b>: ראה לקו\"ש יתרו כרך כו ע' 123. וש\"נ."],["5453","264","<b>תענוג מפולש</b>: ראה גם תו\"ח ח\"ש קכח, א. ב. תולדות קמג, ג. ד. קמד, א. קמו, ג. ד. קנב, א. קנג, א. ויצא קסו, א. בשלח ח\"א קלז, א. פלח הרמון תולדות פא, ד. בשלח ע' קלא."],["5454","266","<b>בנביאים</b>: ד: הטבעיי'."],["5455","265","<b>איבוד החושים. . הנבואה</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ז, ה\"ב. ה\"ו. קו\"א לתניא קנו, א ובהנסמן במ\"מ לשם."],["5456","267","<b>עצמו</b>: ניתוסף ע\"פ ד."],["5457","268","<b>אני הוי' כולא חד</b>: ראה גם המשך תער\"ב ח\"ב ר\"ע תתקיט: ”דאני הוי' אני והוי' כולא חד\". שם ע' תתקכג: ”וכמ\"ש אני הוי' אני והוי' כולא חד\". זהר בראשית בהקדמה ו, א [בפי' אני הוי']: ”אקרי אני. . יי' וכלא חד\". אוה\"ת ויקרא כרך א ע' רלד. סה\"מ תרל\"ח ע' שלז ובהנסמן בריש המאמר שם."],["5458","269","<b>כאשר ידבר איש אל רעהו</b>: תשא לג, יא."],["5459","270","<b>ושבתי בשלום</b>: ויצא כח, כא."],["5460","271","<b>יצחק. . צחוק</b>: רש\"י לך יז, יט."],["5461","272","<b>שיתגלה</b>: ניתוסף ע\"פ ד."]]],[4801940134,"<b>יום ג' פ' בהעלותך ערב חג השבועות דשנת הנ\"ל — תרכ\"ב</b>\n<b>והתהלכתי</b><sup data-n=\"5462\">1</sup> בתוככם כו'<sup data-n=\"5463\">2</sup> ואולך אתכם קוממיות<sup data-n=\"5464\">3</sup> כו'<sup data-n=\"5465\">4</sup>. הנה ידוע דיש ב' מיני הילוך הא' בבחי' אחוריים וחיצוני' כמ\"ש אחרי הוי' תלכו<sup data-n=\"5466\">5</sup> שכללו' נש\"י צריך להיות מתחילה הילוכם בקדש בבחי' אחוריים וחיצוני' שהוא בבחי' מל' דאצי' שהיא בחי' חיצוני' לגבי הוי' [... כידוע דבחי' מל' אינו אלא בחי' זיו והארה משם הוי' שהוא בחי' עצמו' אלקות כו'. ..], וההילוך הוא להעלות וליכלול בחי' החיצונית בבחי' הפנימי' דשם הוי' [... שהוא בחי' מהו\"ע אלקות כנ\"ל. ..], ונק' הילוך מלמטה למעלה כו', והב' הילוך בבחי' פנים שהוא בחי' הפנימי' דשם הוי' [... שהוא בחי' מהו\"ע אלקו' די\"ס דאצי' כו'. ..] כמ\"ש באברהם התהלך לפני<sup data-n=\"5467\">6</sup> כו', והיינו מפני שאברהם ע\"י מצות מילה שהוא הסרת הערלה זכה להמשיך בבחי'<sup data-n=\"5468\">7</sup> פנימי' שהוא בחי' הי\"ס דאצי' בבחי' המל' כמ\"ש אחרי המילה וירא אליו הוי'<sup data-n=\"5469\">8</sup> ופי' בזהר דאליו קאי על בחי' המל' שנתגלה בחי' הוי' למדת המל' ולכן הי' ההילוך שלו בבחי' הפנימי' הנמשך במדת המל' [... כי כל הגילויים מוכרח להיות ע\"י המל' שנק' פתח<sup data-n=\"5470\">9</sup> ושער<sup data-n=\"5471\">10</sup> כידוע. ..], וגם בחזקי' נא' זכור אשר התהלכתי לפניך<sup data-n=\"5472\">11</sup> שהמשיך ג\"כ בחי' פנימי' שהוא בחי' עצמות הי\"ס דאצי' במדת המל' כמ\"ש והטוב בעיניך עשיתי<sup data-n=\"5473\">12</sup> וארז\"ל שסמך גאולה לתפילה כי תפי' הוא בחי' המל'<sup data-n=\"5474\">13</sup> נק'<sup data-n=\"5475\">15</sup> בחי' סיהרא דלית לה מגרמה כלום<sup data-n=\"5476\">14</sup> בחי' עני' ודלה כו', אך גאולה הוא בחי' יסוד<sup data-n=\"5477\">16</sup> וע\"י סמיכת גאולה לתפי' ממשיכים כל הי\"ס דאצי' ע\"י היסוד בבחי' המל' דאצי' ולכן הי' ההילוך שלו בבחי' הפנימי' שהמשיך במל' ולכן א' אשר התהלכתי לפניך כו' וד\"ל.",[["5462","1","<b>והתהלכתי בתוככם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס באוה\"ת בחוקותי כרך ב ע' תרעז. וראה לעיל מאמר ד\"ה והתהלכתי תר\"ב ובהנסמן בריש המאמר שם.\nעוד ע\"ד המאמר ראה לקמן ברשימת הכת\"י כאן."],["5463","2","<b>והתהלכתי בתוככם כו'</b>: בחוקותי כו, יב."],["5464","3","<b>ואולך אתכם קוממיות</b>: שם כו, יג."],["5465","4","<b>כו'</b>: וכ\"ה גם לעיל במאמר ד\"ה זה דשנת תר\"ב בתחילתו."],["5466","5","<b>אחרי הוי' תלכו</b>: פ' ראה יג, ה [בדילוג]."],["5467","6","<b>התהלך לפני</b>: לך יז, א."],["5468","7","<b>בבחי'</b>: אב: בחי'."],["5469","8","<b>וירא אליו הוי'</b>: וירא יח, יא. זהר וירא צח, א."],["5470","9","<b>המל' שנק' פתח</b>: ראה זהר בהקדמה א, ב. ועוד. פרדס שעה\"כ שכ\"ג, פי\"ז מערכת פתח. תו\"ח בא ח\"א צא, א ובהנסמן לשם. צב, ג (ספ\"ו). סה\"מ תרכ\"ז ע' שלט. וש\"נ. תרכ\"ט ע' רמד."],["5471","10","<b>המל'. . ושער</b>: ראה זהר בהקדמה ז, ב. רע\"מ תרומה קנח, א. תו\"ח בא ח\"א צא, ב ובהערה 216. לעיל ע' קכז."],["5472","11","<b>זכור אשר התהלכתי לפניך</b>: מל\"ב כ, ג־ ישעי' לח, ג [בדילוג]."],["5473","12","<b>והטוב בעיניך עשיתי</b>: מל\"ב וישעי' שם. ברכות י, ב."],["5474","13","<b>תפי' הוא בחי' המל'</b>: ראה פע\"ח שער התפלה בתחלתו. סה\"מ תרל\"ח ע' מג. וש\"נ."],["5475","15","<b>נק'</b>: אב: ונק'."],["5476","14","<b>המל'. . כלום</b>: ראה זהר בראשית לג, ב. תולדות קלה, סע\"ב. ויחי רלו, ב. רמט, ב. ויקהל רטו, א. בחוקותי קיג, ב. מאמרי אדה\"ז הקצרים ע' שפג."],["5477","16","<b>גאולה. . יסוד</b>: ראה מאו\"א מערכת גאולה ס\"ד. אוה\"ת ויחי ח\"ב ע' 710. שלח ע' תרטו. בחוקותי ע' תרמא."]]]]});
